Object.assign(window.TEM8_DICTIONARY, {"grubby":{"oxford":{"phon":"ˈɡrʌbi","pos":"adjective","senses":[{"en":"rather dirty, usually because it has not been washed or cleaned","cn":"肮脏的；邋遢的；污秽的","ex":{"en":"grubby hands/clothes","cn":"脏手；脏衣服"}},{"en":"unpleasant because it involves activities that are not honest or moral","cn":"卑鄙的；可鄙的","ex":{"en":"a grubby scandal","cn":"丑闻"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肮脏的；污秽的","en":"A grubby person or object is rather dirty.","ex":{"en":"His white coat was grubby and stained.","cn":"他的白色外套污迹斑斑，简直脏透了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"卑鄙的；可鄙的","en":"If you call an activity or someone's behaviour grubby, you mean that it is not completely honest or respectable.","ex":{"en":"...the grubby business of politics.","cn":"肮脏的政治活动"}}]},"media":{"uk":"media/uk/grubby__gb_1.mp3","us":"media/us/grubby__us_1.mp3"},"examples":[{"en":"grubby hands/clothes","cn":"脏手/衣服"},{"en":"a grubby scandal","cn":"丑闻"}]},"gratify":{"media":{"uk":"media/uk/gratify__gb_1.mp3","us":"media/us/gratify__us_1.mp3"},"oxford":{"phon":"ˈɡrætɪfaɪ","pos":"verb","senses":[{"en":"to please or satisfy somebody","cn":"使高兴；使满意","lab":"formal","ex":{"en":"It gratified him to think that it was all his work.","cn":"他想到这都是他的工作成果，感到十分欣慰。"}},{"en":"to satisfy a wish, need, etc.","cn":"满足（愿望、需要等）","lab":"formal","ex":{"en":"He only gave his consent in order to gratify her wishes.","cn":"他只是为满足她的愿望才同意的。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使高兴；令人满意","en":"If you are gratified by something, it gives you pleasure or satisfaction.","ex":{"en":"Mr. Dambar was gratified by his response.","cn":"丹巴尔先生对他的回答感到满意。"}},{"pos":"VERB 动词","cn":"满足（愿望等）","en":"If you gratify your own or another person's desire, you do what is necessary to please yourself or them.","ex":{"en":"We gratified our friend's curiosity","cn":"我们满足了朋友的好奇心。"}}]},"examples":[{"en":"It gratified him to think that it was all his work.","cn":"他想到这都是他的工作成果，感到十分欣慰。"},{"en":"She was gratified to find that they had followed her advice.","cn":"她看到他们听从了自己的建议，感到很欣慰。"}]},"greet":{"media":{"uk":"media/uk/greet__gb_1.mp3","us":"media/us/greet__us_1.mp3"},"oxford":{"phon":"ɡriːt","pos":"verb","senses":[{"en":"to say hello to somebody or to welcome them","cn":"和（某人）打招呼（或问好）；欢迎；迎接","ex":{"en":"He greeted all the guests warmly as they arrived.","cn":"客人到达时他都热情接待。"}},{"en":"to react to somebody/something in a particular way","cn":"（以某种方式）对…作出反应","g":"[often passive]","ex":{"en":"Loud cheers greeted the news.","cn":"这消息受到热烈欢呼。"}},{"en":"to be the first thing that you see, hear or smell at a particular time","cn":"映入…的眼帘；传入…的耳中（或鼻中）","g":"[usually passive]","ex":{"en":"When she opened the door she was greeted by a scene of utter confusion.","cn":"她打开门，一片混乱不堪的景象呈现在她的眼前。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"同…打招呼;向…问好；欢迎；迎接","en":"When you greet someone, you say 'Hello' or shake hands with them.","ex":{"en":"She liked to be home to greet Steve when he came in from school.","cn":"她喜欢呆在家里迎接放学回家的史蒂夫。"}},{"pos":"VERB 动词","cn":"对…作出反应；回应","en":"If something is greeted in a particular way, people react to it in that way.","ex":{"en":"The European Court's decision has been greeted with dismay by fishermen","cn":"渔民对欧洲法庭的裁决感到失望。"}},{"pos":"VERB 动词","cn":"呈现在…面前；映入…眼帘；最先被…感觉到","en":"If you are greeted by something, it is the first thing you notice in a particular place.","ex":{"en":"I was greeted by a shocking sight","cn":"一幅令人震惊的画面映入我的眼帘。"}}]},"examples":[{"en":"When she opened the door she was greeted by a scene of utter confusion.","cn":"她打开门，一片混乱不堪的景象呈现在她的眼前。"},{"en":"The team's win was greeted as a major triumph.","cn":"这个队获胜被看成是一个重大的胜利。"}]},"grey-haired":{"oxford":{"phon":"ˌɡreɪ ˈheəd","pos":"adjective","senses":[{"en":"with grey hair","cn":"头发灰白的；头发花白的"}]},"media":{"uk":"media/uk/grey_haired_1_gb_1.mp3","us":"media/us/grey_haired_1_us_1.mp3"}},"gravitate":{"media":{"uk":"media/uk/gravitate__gb_1.mp3","us":"media/us/gravitate__us_1.mp3"},"oxford":{"phon":"ˈɡrævɪteɪt","pos":"verb","senses":[{"en":"to move towards sb/sth that you are attracted to","cn":"被吸引到；受吸引而转向"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"被吸引到；受吸引而参加","en":"If you gravitate towards a particular place, thing, or activity, you are attracted by it and go to it or get involved in it.","ex":{"en":"Traditionally young Asians in Britain have gravitated towards medicine, law and engineering.","cn":"英国的亚裔年轻人通常被吸引到医学、法律及工程专业。"}}]},"examples":[{"en":"Many young people gravitate to the cities in search of work.","cn":"许多年轻人被吸引到城里找工作。"},{"en":"Most visitors to London gravitate to Piccadilly Circus and Leicester Square.","cn":"多数到了伦敦的游客会被吸引前往皮卡迪利广场和莱斯特广场。"}]},"great":{"media":{"uk":"media/uk/great__gb_1.mp3","us":"media/us/great__us_1.mp3"},"oxford":{"phon":"ɡreɪt","pos":"adjective","senses":[{"en":"very good or pleasant","cn":"美妙的；好极的；使人快乐的","lab":"informal","sc":"good","ex":{"en":"He's a great bloke.","cn":"他是个大好人。"}},{"en":"much more than average in degree or quantity","cn":"非常的；很多的；极大的","lab":"ironic","sc":"large","ex":{"en":"This is a matter of great importance.","cn":"这是个极其重要的问题。"}},{"en":"very large; much bigger than average in size or quantity","cn":"大的；巨大的；数量大的；众多的","g":"[usually before noun]","sc":"large","ex":{"en":"A great crowd had gathered.","cn":"一大群人聚集在一起。"}},{"en":"used to emphasize an adjective of size or quality","cn":"（强调尺寸、体积或质量）很","g":"[only before noun]","lab":"informal","sc":"large","ex":{"en":"There was a great big pile of books on the table.","cn":"桌上有很大一摞书。"}},{"en":"extremely good in ability or quality and therefore admired by many people","cn":"伟大的；优秀的；杰出的；卓越的","sc":"admired","ex":{"en":"Gary Kasparov, undoubtedly the greatest chess player of all time","cn":"加里·卡斯帕罗夫，无疑是有史以来最伟大的国际象棋棋手"}},{"en":"important and impressive","cn":"重要的；重大的；给人深刻印象的","g":"[only before noun]","sc":"important/impressive","ex":{"en":"The wedding was a great occasion.","cn":"这场婚礼可是一大盛典。"}},{"en":"having high status or a lot of influence","cn":"地位高的；位高权重的；影响大的","sc":"with influence","ex":{"en":"the great powers (= important and powerful countries)","cn":"大国"}},{"en":"in a very good state of physical or mental health","cn":"身心健康的；心情愉快的","sc":"in good health","ex":{"en":"She seemed in great spirits (= very cheerful).","cn":"她好像心情很不错。"}},{"en":"able to do something well","cn":"擅长；精通","g":"[not usually before noun]","lab":"informal","sc":"skilled","ex":{"en":"She's great at chess.","cn":"她国际象棋下得很好。"}},{"en":"very suitable or useful for something","cn":"适合；（对…）有用","lab":"informal","sc":"useful","ex":{"en":"This gadget's great for opening jars.","cn":"这小玩意儿开广口瓶挺好。"}},{"en":"used when you are emphasizing a particular description of somebody/something","cn":"（强调某种情况）","g":"[only before noun]","sc":"for emphasis","ex":{"en":"We are great friends.","cn":"我们是最要好的朋友。"}},{"en":"added to words for family members to show a further stage in relationship","cn":"（冠于家庭成员的称呼前，表示更高或更低一辈的亲属关系）","sc":"family","ex":{"en":"my great-aunt (= my father’s or mother’s aunt)","cn":"我的姑婆／姨婆"}},{"en":"used in the names of animals or plants that are larger than similar kinds","cn":"（用于相似动植物中较大者的名称前）大","g":"[only before noun]","sc":"larger animals/plants","ex":{"en":"the great tit","cn":"大山雀"}},{"en":"used with the name of a city to describe an area that includes the centre of the city and a large area all round it","cn":"（与城市名连用，指包括市区和周围广大地区在内的区域）大","sc":"city name","ex":{"en":"Greater London","cn":"大伦敦"}},{"en":"a very well-known and successful person","cn":"名人；伟人","ex":{"en":"He was one of boxing's all-time greats.","cn":"他是一位空前的拳击好手。"},"pos":"noun"},{"en":"very well","cn":"极佳地；非常好地","ex":{"en":"Well done. You did great.","cn":"干得好。你干得真棒。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"很大的；巨大的","en":"You use great to describe something that is very large. Great is more formal than big .","ex":{"en":"The room had a great bay window.","cn":"这间房有一扇巨大的凸窗。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（数量或程度）大的，巨大的，超乎寻常的","en":"Great means large in amount or degree.","ex":{"en":"I'll take great care of it","cn":"我会加倍爱惜它的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"重大的；闻名的；令人激动的","en":"You use great to describe something that is important, famous, or exciting.","ex":{"en":"...the great cultural achievements of the past","cn":"昔日辉煌的文化成就"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"伟大的；著名的； 卓越的；优秀的","en":"You can describe someone who is successful and famous for their actions, knowledge, or skill as great .","ex":{"en":"Wes Hall was once one of the West Indies' great cricketers.","cn":"韦斯·霍尔曾经是西印度群岛伟大的板球运动员之一。"}},{"pos":"N-PLURAL 复数名词","cn":"伟人；名人；大人物","en":"The greats in a particular subject or field of activity are the people who have been most successful or famous in it.","ex":{"en":"...all the greats of Hollywood.","cn":"所有的好莱坞名流"}},{"pos":"N-PLURAL 复数名词","cn":"金曲","en":"The greats of popular modern music are records that have been successful and that continue to be popular.","ex":{"en":"...a medley of rock'n'roll greats.","cn":"摇滚金曲大联唱"}},{"pos":"ADJ 形容词","cn":"美妙的；好极了的；了不起的","en":"If you describe someone or something as great, you approve of them or admire them.","ex":{"en":"Arturo has this great place in Cazadero","cn":"阿图罗在卡扎德罗威望极高。"}},{"pos":"ADJ 形容词","cn":"十分健康的；精力旺盛的；充满热情的","en":"If you feel great, you feel very healthy, energetic, and enthusiastic.","ex":{"en":"I feel just great.","cn":"我感觉好极了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"十足的；非常的","en":"You use great in order to emphasize the size or degree of a characteristic or quality.","ex":{"en":"...a great big Italian wedding.","cn":"场面盛大的意大利式婚礼"}},{"pos":"EXCLAM 感叹语","cn":"妙极了；太好了","en":"You say great in order to emphasize that you are pleased or enthusiastic about something.","ex":{"en":"Oh great! That'll be good for Fergus.","cn":"哦，太棒了！那将对弗格斯很有利。"}},{"pos":"EXCLAM 感叹语","cn":"哼，这倒好（表示气愤、恼火等）","en":"You say great in order to emphasize that you are angry or annoyed about something.","ex":{"en":"'Oh great,' I thought. 'Just what I need.'","cn":"“哼，”我想，“正合我心。”"}},{"pos":"N-IN-NAMES 名称名词","cn":"（用于同类动植物中较大者的名称前）大","en":"Great is used as part of the name of a species of plant or animal when there is another species of the same plant or animal which is smaller and has different characteristics.","ex":{"en":"...the great white shark.","cn":"大白鲨"}}]},"examples":[{"en":"You've been a great help, I must say (= no help at all).","cn":"依我看，你真是帮了个大忙啊（指帮倒忙）。"},{"en":"‘I'll pick you up at seven.’ ‘That'll be great, thanks.’ “","cn":"我七点钟来接你。” “太好了，谢谢。”"}]},"grass":{"media":{"img":["media/pic/blade_comp.jpg","media/thumb/grass.jpg"],"uk":"media/uk/grass__gb_1.mp3","us":"media/us/grass__us_1.mp3"},"oxford":{"phon":"ɡrɑːs","pos":"noun","senses":[{"en":"a common wild plant with narrow green leaves and stems that are eaten by cows, horses, sheep, etc.","cn":"草；青草；牧草","g":"[uncountable]","ex":{"en":"a blade of grass","cn":"一片草叶"}},{"en":"any type of grass","cn":"禾本科植物","g":"[countable]","ex":{"en":"ornamental grasses","cn":"观赏性草"}},{"en":"an area of ground covered with grass","cn":"草地；草坪；草场；牧场","g":"[singular, uncountable]","ex":{"en":"to cut/mow the grass","cn":"割草"}},{"en":"marijuana","cn":"大麻","g":"[uncountable]","lab":"informal"},{"en":"a person, usually a criminal, who tells the police about somebody’s criminal activities and plans","cn":"向警方告密的人（通常指罪犯）","g":"[countable]","lab":"British English, informal, usually disapproving，，，，"},{"en":"to tell the police about somebody’s criminal activities","cn":"（向警方）告密，告发","ex":{"en":"Who grassed on us?","cn":"谁向警方告发了我们？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"草；青草","en":"Grass is a very common plant consisting of large numbers of thin, spiky, green leaves that cover the surface of the ground.","ex":{"en":"Small things stirred in the grass around the tent","cn":"一些小东西在帐篷四周的草丛里窸窸窣窣地动着。"}},{"pos":"N-SING 单数名词","cn":"草地；草坪；草场","en":"If you talk about the grass, you are referring to an area of ground that is covered with grass, for example in your garden.","ex":{"en":"In the old days, there were strict fines for walking on the grass or missing a study period","cn":"过去，踩踏草坪或旷课都会被重金处罚。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"同marijuana","en":"Grass is the same as marijuana .","ex":{"en":"I started smoking grass when I was about sixteen.","cn":"我大约16岁的时候开始吸大麻。"}},{"pos":"VERB 动词","cn":"（向警方等）揭发，告发","en":"If you say that one person grasses on another, the first person tells the police or other authorities about something criminal or wrong which the second person has done.","ex":{"en":"His wife wants him to grass on the members of his own gang","cn":"妻子要他向警方告发他所在团伙的成员。"}},{"pos":"N-COUNT 可数名词","cn":"告密者；揭发者","en":"A grass is someone who tells the police or other authorities about criminal activities that they know about."},{"pos":"PHRASE 短语","cn":"草是那边绿；这山望着那山高","en":"If you say the grass is greener somewhere else, you mean that other people's situations always seem better or more attractive than your own, but may not really be so.","ex":{"en":"He was very happy with us but wanted to see if the grass was greener elsewhere.","cn":"他对我们感到十分满意，但还想看看是否有更合适的人选。"}},{"pos":"PHRASE 短语","cn":"（因年老等）被辞退，遭解雇","en":"If you say that someone is being put out to grass, you mean they are no longer being employed because they are considered to be too old or no longer useful.","ex":{"en":"The Prime Minister refused to be put out to grass. Asked if he would quit, he replied: 'The answer is No'.","cn":"首相拒绝被解除职务，当问到他是否会辞职时，他说，“我的回答是不。”"}},{"pos":"","cn":"","en":"相关词组：grass over grass up"}]},"examples":[{"en":"Keep off the grass. (= on a sign)","cn":"请勿践踏草地。"},{"en":"The dry grass caught fire.","cn":"干草着火了。"}]},"grants":{"oxford":{"phon":"ɡrɑːnt","pos":"verb","senses":[{"en":"to agree to give sb what they ask for, especially formal or legal permission to do sth （","cn":"尤指正式地或法律上）同意，准予，允许"},{"en":"to admit that sth is true, although you may not like or agree with it （","cn":"勉强）承认，同意"}]}},"ground":{"media":{"uk":"media/uk/ground__gb_2.mp3","us":"media/us/ground__us_2.mp3"},"oxford":{"phon":"ɡraʊnd","pos":"noun","senses":[{"en":"the solid surface of the earth","cn":"地；地面","g":"[uncountable]","sc":"surface of earth","ex":{"en":"I found her lying on the ground.","cn":"我发现她躺在地上。"}},{"en":"used to describe activities that take place on the ground, not in the air or at sea","cn":"地面上的；陆地上的","g":"[uncountable]","sc":"surface of earth","ex":{"en":"Ground forces were deployed in the area.","cn":"该地区部署了地面部队。"}},{"en":"an area of open land","cn":"开阔地；空旷地","g":"[uncountable]","sc":"area of land","ex":{"en":"The kids were playing on waste ground behind the school.","cn":"孩子们在学校后面的荒地上玩耍。"}},{"en":"an area of land that is used for a particular purpose, activity or sport","cn":"（特定用途的）场地","g":"[countable]","lab":"North American English","sc":"area of land","ex":{"en":"a football/cricket ground","cn":"足球场；板球场"}},{"en":"a large area of land or sea that is used for a particular purpose","cn":"（某种用途的）地域，水域","g":"[plural]","sc":"area of land","ex":{"en":"fishing grounds","cn":"渔场"}},{"en":"soil on the surface of the earth","cn":"土；土地；土壤","g":"[uncountable]","lab":"especially North American English","sc":"soil","ex":{"en":"fertile ground for planting crops","cn":"种植农作物的肥沃土壤"}},{"en":"the land or gardens around a large building","cn":"（大建筑物周围的）场地，庭院，花园","g":"[plural]","sc":"gardens","ex":{"en":"the hospital grounds","cn":"医院的院子"}},{"en":"an area of interest, knowledge or ideas","cn":"（兴趣、知识或思想的）范围，领域","g":"[uncountable]","sc":"area of knowledge/ideas","ex":{"en":"He managed to cover a lot of ground in a short talk.","cn":"他在简短的谈话中涵盖了许多领域。"}},{"en":"a good or true reason for saying, doing or believing something","cn":"充分的理由；根据","g":"[countable, usually plural]","lab":"law","sc":"good reason","ex":{"en":"You have no grounds for complaint.","cn":"你没有理由抱怨。"}},{"en":"the small pieces of solid matter in a liquid that have fallen to the bottom","cn":"渣滓；沉淀物","g":"[plural]","sc":"in liquid","ex":{"en":"coffee grounds","cn":"咖啡渣"}},{"en":"a wire that connects an electric circuit with the ground and makes it safe","cn":"（接）地线","g":"[countable, usually singular]","lab":"North American English","sc":"electrical wire","ex":{"en":"Don't forget to connect the ground wire.","cn":"别忘了接地线。"}},{"en":"a background that a design is painted or printed on","cn":"（绘画或印刷的）背景，底子","g":"[countable]","sc":"background","ex":{"en":"pink roses on a white ground","cn":"白底粉红玫瑰"}},{"en":"when a boat grounds or something grounds it, it touches the ground in shallow water and is unable to move","cn":"（使）搁浅，触底","g":"[transitive, intransitive]","sc":"boat","ex":{"en":"The fishing boat had been grounded on rocks off the coast of Cornwall.","cn":"渔船在康沃尔海岸外礁石上搁浅了。"},"pos":"verb"},{"en":"to prevent an aircraft from taking off","cn":"使停飞；阻止…起飞","g":"[transitive, often passive]","sc":"aircraft","ex":{"en":"The balloon was grounded by strong winds.","cn":"热气球因强风停飞。"},"pos":"verb"},{"en":"to punish a child or young person by not allowing them to go out with their friends for a period of time","cn":"罚（儿童）不准出去玩","g":"[transitive, usually passive]","sc":"child","ex":{"en":"You're grounded for a week!","cn":"罚你一周不准出门！"},"pos":"verb"},{"en":"to make electrical equipment safe by connecting it to the ground with a wire","cn":"把（电线）接地","g":"[transitive, usually passive]","lab":"North American English","sc":"electricity","ex":{"en":"The spark plugs must be grounded to complete the electrical circuit.","cn":"火花塞必须接地才能完成电路。"},"pos":"verb"},{"en":"cut or crushed into very small pieces or powder","cn":"磨细的；剁碎的","lab":"US English","ex":{"en":"ground coffee","cn":"咖啡粉"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"地；地面","en":"The ground is the surface of the earth.","ex":{"en":"Forty or fifty women were sitting cross-legged on the ground","cn":"四五十个女人盘腿坐在地上。"}},{"pos":"N-SING 单数名词","cn":"（相对于空中的）地面","en":"If you say that something takes place on the ground, you mean it takes place on the surface of the earth and not in the air.","ex":{"en":"Coordinating airline traffic on the ground is as complicated as managing the traffic in the air.","cn":"协调地面的航空交通与管理空中交通一样复杂。"}},{"pos":"N-SING 单数名词","cn":"土；土地；土壤","en":"The ground is the soil and rock on the earth's surface.","ex":{"en":"The ground had eroded.","cn":"这片土壤遭到侵蚀。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指建筑物极少或具有某种特性的）土地","en":"You can refer to land as ground, especially when it has very few buildings or when it is considered to be special in some way.","ex":{"en":"...a stretch of waste ground","cn":"一块荒地"}},{"pos":"N-COUNT 可数名词","cn":"（有特定用途的）场地","en":"You can use ground to refer to an area of land, sea, or air which is used for a particular activity.","ex":{"en":"...Indian hunting grounds","cn":"印第安人的狩猎场"}},{"pos":"N-COUNT 可数名词","cn":"运动场，…场（美国英语中亦作grounds）","en":"A ground is an area of land which is specially designed and made for playing sport or for some other activity. In American English grounds is also used.","ex":{"en":"...the city's football ground.","cn":"该市的足球场"}},{"pos":"N-PLURAL 复数名词","cn":"（大型或重要建筑周围的）场地，庭院，花园","en":"The grounds of a large or important building are the garden or area of land which surrounds it.","ex":{"en":"...the palace grounds.","cn":"皇家花园"}},{"pos":"N-VAR 可变名词","cn":"（适于方法、思想等发展的）地方","en":"You can use ground to refer to a place or situation in which particular methods or ideas can develop and be successful.","ex":{"en":"The company has maintained its reputation as the developing ground for new techniques","cn":"该公司一直享有新技术研发基地的美誉。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"范围；领域；基础","en":"You can use ground in expressions such as on shaky ground and the same ground to refer to a particular subject, area of experience, or basis for an argument.","ex":{"en":"Sensing she was on shaky ground, Marie changed the subject","cn":"感到自己的观点站不住脚，玛丽于是换了个话题。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"优势；有利条件","en":"Ground is used in expressions such as gain ground ,lose ground, and give ground in order to indicate that someone gets or loses an advantage.","ex":{"en":"There are signs that the party is gaining ground in the latest polls","cn":"有迹象表明该党在最新一轮投票中正逐渐领先。"}},{"pos":"N-VAR 可变名词","cn":"理由；根据","en":"If something is grounds for a feeling or action, it is a reason for it. If you do something on the grounds of a particular thing, that thing is the reason for your action.","ex":{"en":"In the interview he gave some grounds for optimism","cn":"他接受采访时阐述了持乐观态度的理由。"}},{"pos":"VERB 动词","cn":"以…为根据；建立在…基础上","en":"If an argument, belief, or opinion is grounded in something, that thing is used to justify it.","ex":{"en":"Her argument was grounded in fact","cn":"她的观点有事实根据。"}},{"pos":"VERB 动词","cn":"使不能起飞；使停飞","en":"If an aircraft or its passengers are grounded, they are made to stay on the ground and are not allowed to take off.","ex":{"en":"The civil aviation minister ordered all the planes to be grounded","cn":"民航部长下令所有飞机不得起飞。"}},{"pos":"VERB 动词","cn":"罚（儿童）不能出门；禁足","en":"When parents ground a child, they forbid them to go out and enjoy themselves for a period of time, as a punishment.","ex":{"en":"Thompson grounded him for a month, and banned television.","cn":"汤普森罚他一个月不能出门，并禁止看电视。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）搁浅","en":"If a ship or boat is grounded or if it grounds, it touches the bottom of the sea, lake, or river it is on, and is unable to move off.","ex":{"en":"Residents have been told to stay away from the region where the ship was grounded","cn":"居民们被告知不要靠近船只搁浅的区域。"}},{"pos":"N-COUNT 可数名词","cn":"接地装置；地线","en":"The ground in an electric plug or piece of electrical equipment is the wire through which electricity passes into the ground and which makes the equipment safe."},{"pos":"ADJ 形容词","cn":"（肉等）切碎的，磨碎的","en":"Ground meat has been cut into very small pieces in a machine.","ex":{"en":"...ground beef.","cn":"绞碎的牛肉"}},{"pos":"","cn":"","en":"Ground is the past tense and past participle of grind ."},{"pos":"PHRASE 短语","cn":"开辟新领域；开创新方法","en":"If you break new ground, you do something completely different or you do something in a completely different way.","ex":{"en":"Gellhorn may have broken new ground when she filed her first report on the Spanish Civil War.","cn":"当盖尔霍恩发出她第一篇关于西班牙内战的报道时，她也许已经开辟了一片新的天地。"}},{"pos":"PHRASE 短语","cn":"烧为灰烬；夷为平地","en":"If you say that a town or building is burnt to the ground or is razed to the ground, you are emphasizing that it has been completely destroyed by fire.","ex":{"en":"The town was razed to the ground after the French Revolution.","cn":"该镇在法国大革命后被夷为平地。"}},{"pos":"PHRASE 短语","cn":"共同看法；相同的立场","en":"If two people or groups find common ground, they agree about something, especially when they do not agree about other things."},{"pos":"PHRASE 短语","cn":"躲藏起来；潜伏起来","en":"If you go to ground, you hide somewhere where you cannot easily be found.","ex":{"en":"Citizens of East Beirut went to ground in basements and shelters.","cn":"东贝鲁特的市民们躲进了地下室和掩体中。"}},{"pos":"PHRASE 短语","cn":"中间立场；中间观点","en":"The middle ground between two groups, ideas, or plans involves things which do not belong to either of these groups, ideas, or plans but have elements of each, often in a less extreme form.","ex":{"en":"She seems to have found a middle ground in which mutual support, rather than complete dependency, is possible.","cn":"她似乎已经找到了实现相互支持而非完全依赖其中一方的中间立场。"}},{"pos":"PHRASE 短语","cn":"开始；起步","en":"If something such as a project gets off the ground, it begins or starts functioning.","ex":{"en":"We help small companies to get off the ground.","cn":"我们帮助一些小公司顺利起步。"}},{"pos":"PHRASE 短语","cn":"在自己熟悉的领域里；在自己的地盘","en":"If you are on your own ground, you are in a place or situation in which you feel confident because you are very familiar with it.","ex":{"en":"On her own ground she knows exactly what she's doing.","cn":"她在自己熟悉的领域里对自己的行为有十足的把握。"}},{"pos":"PHRASE 短语","cn":"为…打下基础","en":"If you prepare the ground for a future event, course of action, or development, you make it easier for it to happen.","ex":{"en":"...a political initiative which would prepare the ground for war.","cn":"为战争埋下了伏笔的政治倡议"}},{"pos":"PHRASE 短语","cn":"改变立场；改变观点","en":"If you shift your ground or change your ground, you change the basis on which you are arguing."},{"pos":"PHRASE 短语","cn":"坚持主张；坚定立场","en":"If you stand your ground or hold your ground, you continue to support a particular argument or to have a particular opinion when other people are opposing you or trying to make you change your mind.","ex":{"en":"The spectacle of Sakharov standing his ground and speaking his mind gave me hope.","cn":"萨哈罗夫坚持立场、坦率直言的样子让我看到了希望。"}},{"pos":"PHRASE 短语","cn":"坚守阵地；不退却","en":"If you stand your ground or hold your ground, you do not run away from a situation, but face it bravely.","ex":{"en":"She had to force herself to stand her ground when she heard someone approaching.","cn":"听到有人走近，她只好强迫自己鼓起勇气，绝不退缩。"}},{"pos":"PHRASE 短语","cn":"（工作、衣服等）完全适合","en":"If you say that something such as a job or piece of clothing suits someone down to the ground, you mean that it is completely suitable or right for them."},{"pos":"PHRASE 短语","cn":"为数不多；数目少","en":"If people or things of a particular kind are thin on the ground, there are very few of them.","ex":{"en":"Good managers are often thin on the ground.","cn":"优秀的经理人常常寥寥无几。"}},{"pos":"","cn":"","en":"to have one's ear to the ground→see: ;"}]},"examples":[{"en":"All planes out of Heathrow have been grounded by the strikes.","cn":"所有由希思罗机场起飞的飞机均因罢工而停飞。"},{"en":"Houses and a luxury tourist hotel were burned to the ground (= completely destroyed, so that there is nothing left).","cn":"多间房屋和一家豪华旅馆被大火焚烧殆尽。"}]},"greenhouse":{"media":{"uk":"media/uk/greenhouse__gb_1.mp3","us":"media/us/greenhouse__us_1.mp3","img":["media/ldoce/img/greenhouse.jpg"]},"oxford":{"phon":"ˈɡriːnhaʊs","pos":"noun","senses":[{"en":"a building with glass sides and a glass roof for growing plants in","cn":"温室；暖房"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"温室；暖房","en":"A greenhouse is a glass building in which you grow plants that need to be protected from bad weather."},{"pos":"ADJ 形容词","cn":"温室效应的；引起温室效应的","en":"Greenhouse means relating to or causing the greenhouse effect."}]}},"grant":{"oxford":{"phon":"ɡrɑːnt","pos":"verb","senses":[{"en":"to agree to give somebody what they ask for, especially formal or legal permission to do something","cn":"（尤指正式地或法律上）同意，准予，允许","g":"[often passive]","ex":{"en":"My request was granted.","cn":"我的要求得到了满足。"}},{"en":"to admit to somebody that something is true, although you may not like or agree with it","cn":"（勉强）承认，同意","ex":{"en":"She's a smart woman, I grant you, but she's no genius.","cn":"我同意你的观点，她是一个很聪明的女人，但绝不是天才。"}},{"en":"a sum of money that is given by the government or by another organization to be used for a particular purpose","cn":"（政府、机构的）拨款","ex":{"en":"government/federal grants","cn":"政府／联邦拨款"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拨款;补助金","en":"A grant is an amount of money that a government or other institution gives to an individual or to an organization for a particular purpose such as education or home improvements.","ex":{"en":"They'd got a special grant to encourage research","cn":"他们得到一笔用以鼓励科研的特别经费。"}},{"pos":"VERB 动词","cn":"授予；给予","en":"If someone in authority grants you something, or if something is granted to you, you are allowed to have it.","ex":{"en":"France has agreed to grant him political asylum","cn":"法国已经同意给予他政治避难。"}},{"pos":"VERB 动词","cn":"承认","en":"If you grant that something is true, you accept that it is true, even though your opinion about it does not change.","ex":{"en":"The magistrates granted that the charity was justified in bringing the action.","cn":"地方法官承认该慈善机构有理由提起诉讼。"}},{"pos":"PHRASE 短语","cn":"（因视作理所当然而）不把…当回事，对…不予重视（或不知感激）","en":"If you say that someone takes you for granted, you are complaining that they benefit from your help, efforts, or presence without showing that they are grateful.","ex":{"en":"What right has the family to take me for granted, Martin?","cn":"这家人有什么资格瞧不起我，马丁？"}},{"pos":"PHRASE 短语","cn":"认为…是理所当然的","en":"If you take something for granted, you believe that it is true or accept it as normal without thinking about it.","ex":{"en":"I was amazed that virtually all the things I took for granted up north just didn't happen in London.","cn":"几乎所有我认为在北方是理所当然的事情在伦敦都没有发生，这让我惊诧不已。"}},{"pos":"PHRASE 短语","cn":"理所当然地认为","en":"If you take it for granted that something is the case, you believe that it is true or you accept it as normal without thinking about it.","ex":{"en":"He seemed to take it for granted that he should speak as a representative.","cn":"他似乎想当然地认为他应该以代表的身份发言。"}}]},"media":{"uk":"media/uk/grant__gb_1.mp3","us":"media/us/grant__us_1.mp3"},"examples":[{"en":"She's a smart woman, I grant you, but she's no genius.","cn":"我同意你的观点，她是一个很聪明的女人，但绝不是天才。"},{"en":"We take having an endless supply of clean water for granted.","cn":"我们想当然地认为洁净水的供应无穷无尽而不予以珍惜。"}]},"grown":{"media":{"uk":"media/uk/grown__gb_2.mp3","us":"media/us/grown__us_2.mp3"},"oxford":{"phon":"ɡrəʊn","pos":"adjective","senses":[{"en":"mentally and physically an adult","cn":"成熟的；成年的；长大成人的","ex":{"en":"It's pathetic that grown men have to resort to violence like this.","cn":"成年人还得这样诉诸暴力，真可悲。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"成年的；成熟的；长大的","en":"A grown man or woman is one who is fully developed and mature, both physically and mentally.","ex":{"en":"Few women can understand a grown man's love of sport","cn":"很少有女人能理解一个成年男人对体育的那份热爱。"}}]},"examples":[{"en":"It's pathetic that grown men have to resort to violence like this.","cn":"成年人还得这样诉诸暴力，真可悲。"},{"en":"Who ever heard of a grown man being scared of the dark?","cn":"有谁听说过一个大男人还怕黑？"}]},"grasped":{"oxford":{"phon":"ɡrɑːsp","pos":"verb","senses":[{"en":"to take a firm hold of sb/sth","cn":"抓紧；抓牢"},{"en":"to understand sth completely","cn":"理解；领会；领悟；明白"}]}},"group":{"media":{"uk":"media/uk/group__gb_1.mp3","us":"media/us/group__us_1.mp3"},"oxford":{"phon":"ɡruːp","pos":"noun","senses":[{"en":"a number of people or things that are together in the same place or that are connected in some way","cn":"组；群；批；类；簇","ex":{"en":"a group of people/students/friends","cn":"一伙人；一群学生；一帮朋友"}},{"en":"a number of people who work or do something together or share particular beliefs","cn":"伙；帮；组","ex":{"en":"The residents formed a community action group.","cn":"居民组成了社区行动组。"}},{"en":"a number of companies that are owned by the same person or organization","cn":"集团","lab":"business","ex":{"en":"This acquisition will make them the largest newspaper group in the world.","cn":"这次收购将使他们成为世界上最大的报业集团。"}},{"en":"a number of musicians who perform together, especially to play pop music","cn":"（尤指流行音乐的）演奏组，乐团，乐队","lab":"rather old-fashioned","ex":{"en":"She sings in a rock group.","cn":"她是摇滚乐队的歌手。"}},{"en":"to gather into a group; to make somebody/something form a group","cn":"（使）成群，成组，聚集","g":"[transitive, intransitive]","ex":{"en":"The children grouped themselves around their teacher.","cn":"孩子们聚集在老师周围。"},"pos":"verb"},{"en":"to divide people or things into groups of people or things that are similar in some way","cn":"将…分类；把…分组","g":"[transitive]","ex":{"en":"The books are grouped together by subject.","cn":"这些书按科目分类。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"（一）组；（一）群；（一）批","en":"A group of people or things is a number of people or things which are together in one place at one time.","ex":{"en":"The trouble involved a small group of football supporters","cn":"这次骚乱涉及一小撮足球迷。"}},{"pos":"N-COUNT 可数名词","cn":"集体；群体；团体","en":"A group is a set of people who have the same interests or aims, and who organize themselves to work or act together.","ex":{"en":"...the Minority Rights Group","cn":"少数民族权益团体"}},{"pos":"N-COUNT 可数名词","cn":"（具有共同点而被放在一起考虑的）组，群，类","en":"A group is a set of people, organizations, or things which are considered together because they have something in common.","ex":{"en":"She is among the most promising players in her age group","cn":"她是所在年龄组中最有前途的选手之一。"}},{"pos":"N-COUNT 可数名词","cn":"（企业）集团","en":"A group is a number of separate commercial or industrial firms which all have the same owner.","ex":{"en":"The group made a pre-tax profit of £11.05 million.","cn":"该集团的税前利润为1,105万英镑。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指流行乐的）乐队,乐团,组合","en":"A group is a number of musicians who perform together, especially ones who play popular music.","ex":{"en":"At school he played bass in a pop group called The Urge.","cn":"他上学的时候在一个叫“冲动”的流行乐队中担任贝司手。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）形成组；（把…）归在一起","en":"If a number of things or people are grouped together or group together, they are together in one place or within one organization or system.","ex":{"en":"The fact sheets are grouped into seven sections","cn":"这些资料被分成了7部分。"}}]},"examples":[{"en":"The colleges grouped together to offer a wider range of courses.","cn":"这些学院联合在一起，以开设范围更广的课程。"},{"en":"The proportion of single parent families varies between different income groups.","cn":"单亲家庭比例在不同收入群中各不相同。"}]},"granddaughter":{"oxford":{"phon":"ˈɡrændɔːtə(r)","pos":"noun","senses":[{"en":"a daughter of your son or daughter","cn":"（外）孙女"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"孙女；外孙女","en":"Someone's granddaughter is the daughter of their son or daughter.","ex":{"en":"...a drawing of my granddaughter Amelia.","cn":"我孙女阿梅莉亚的一张素描"}}]},"media":{"uk":"media/uk/granddaughter__gb_1.mp3","us":"media/us/granddaughter__us_1.mp3"}},"graphite":{"oxford":{"phon":"ˈɡræfaɪt","pos":"noun","senses":[{"en":"a soft black mineral that is a form of carbon. Graphite is used to make pencils, to lubricate machines and in nuclear reactors.","cn":"石墨"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"石墨","en":"Graphite is a soft black substance that is a form of carbon. It is used in pencils and electrical equipment."}]},"media":{"uk":"media/uk/graphite__gb_1.mp3","us":"media/us/graphite__us_1.mp3"}},"grave":{"media":{"uk":"media/uk/grave__gb_1.mp3","us":"media/us/grave__us_1.mp3"},"oxford":{"phon":"ɡreɪv","pos":"noun","senses":[{"en":"a place in the ground where a dead person is buried","cn":"坟墓；墓穴；坟头","ex":{"en":"We visited Grandma's grave.","cn":"我们给祖母扫了墓。"}},{"en":"a way of referring to death or a person’s death","cn":"死亡","g":"[singular]","lab":"usually literary","ex":{"en":"Is there life beyond the grave (= life after death)?","cn":"人死后有来生吗？"}},{"en":"very serious and important; giving you a reason to feel worried","cn":"严重的；重大的；严峻的；深切的","ex":{"en":"The police have expressed grave concern about the missing child's safety.","cn":"警方对失踪孩子的安全深表关注。"},"pos":"adjective"},{"en":"serious in manner, as if something sad or important has just happened","cn":"严肃的；庄严的；表情沉重的","ex":{"en":"He looked very grave as he entered the room.","cn":"他进入房间时表情非常严肃。"},"pos":"adjective"},{"en":"a mark placed over a vowel in some languages to show how it should be pronounced, as over the e in the French word père","cn":"钝重音符，沉音符，抑音符（标在元音上面表发音）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"墓穴；坟墓；埋葬处","en":"A grave is a place where a dead person is buried.","ex":{"en":"They used to visit her grave twice a year.","cn":"他们以前每年去她的墓前凭吊两次。"}},{"pos":"N-COUNT 可数名词","cn":"死亡;终结","en":"You can refer to some-one's death as their grave or to death as the grave .","ex":{"en":"...drinking yourself to an early grave","cn":"纵酒而自折其寿"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"严重的；重大的；严峻的","en":"A grave event or situation is very serious, important, and worrying.","ex":{"en":"He said that the situation in his country is very grave","cn":"他说他的国家情况十分危急。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"严肃的；表情沉重的","en":"A grave person is quiet and serious in their appearance or behaviour.","ex":{"en":"William was up on the roof for some time and when he came down he looked grave","cn":"威廉在屋顶上呆了一段时间，他下来的时候面色凝重。"}},{"pos":"ADJ 形容词","cn":". 重音符;抑音符;沉音符","en":"In some languages such as French, a grave accent is a symbol that is placed over a vowel in a word to show how the vowel is pronounced. For example, the word 'mère' has a grave accent over the first 'e'"},{"pos":"PHRASE 短语","cn":"自掘坟墓；自取灭亡","en":"If you say that someone is digging their own grave, you are warning them that they are doing something foolish or dangerous that will cause their own failure.","ex":{"en":"The magazine isn't trying to ruin his career, the man's digging his own grave by refusing an interview.","cn":"这份杂志并非想断送他的事业，而他拒绝接受采访就是在自毁前程。"}},{"pos":"PHRASE 短语","cn":"九泉之下不得安宁","en":"If you say that someone who is dead would turn in their grave at something that is happening now, you mean that they would be very shocked or upset by it, if they were alive.","ex":{"en":"Darwin must be turning in his grave at the thought of what is being perpetrated in his name.","cn":"一想到冒他之名所做下的那些事，达尔文在九泉之下一定不得安宁。"}},{"pos":"","cn":"","en":"from the cradle to the grave→see: ;"}]},"examples":[{"en":"My father would turn in his grave if he knew.","cn":"我父亲知道的话在九泉之下也会不得安宁的。"},{"en":"The consequences will be very grave if nothing is done.","cn":"如果不采取任何措施后果将会是非常严重的。"}]},"gradual":{"media":{"uk":"media/uk/gradual__gb_1.mp3","us":"media/us/gradual__us_1.mp3"},"oxford":{"phon":"ˈɡrædʒuəl","pos":"adjective","senses":[{"en":"happening slowly over a long period; not sudden","cn":"逐渐的；逐步的；渐进的","ex":{"en":"a gradual change in the climate","cn":"气候的逐渐变化"}},{"en":"not steep","cn":"平缓的；不陡的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"逐渐的；逐步的","en":"A gradual change or process occurs in small stages over a long period of time, rather than suddenly.","ex":{"en":"Losing weight is a slow, gradual process","cn":"减肥是一个缓慢而渐进的过程。"}}]},"examples":[{"en":"Recovery from the disease is very gradual.","cn":"这种疾病的康复过程缓慢。"},{"en":"a gradual change in the climate","cn":"气候的逐渐变化"}]},"green":{"media":{"img":["media/pic/hobbies_comp.jpg","media/thumb/golf.jpg"],"uk":"media/uk/green__gb_1.mp3","us":"media/us/green__us_1.mp3"},"oxford":{"phon":"ɡriːn","pos":"adjective","senses":[{"en":"having the colour of grass or the leaves of most plants and trees","cn":"绿色的；草绿色的","sc":"colour","ex":{"en":"green grass/leaves/vegetables","cn":"绿草；绿叶；绿叶蔬菜"}},{"en":"covered with grass or other plants","cn":"长满青草的；布满植被的；绿油油的；青葱的","sc":"covered with grass","ex":{"en":"green fields/pastures/hills","cn":"绿油油的农田；绿色的草地；葱绿的山丘"}},{"en":"not yet ready to eat","cn":"未成熟的","sc":"fruit","ex":{"en":"green tomatoes","cn":"青西红柿"}},{"en":"connected with the protection of the environment; supporting the protection of the environment as a political principle","cn":"环境保护的；主张环保的","sc":"politics","ex":{"en":"green energy","cn":"绿色能源"}},{"en":"young and without experience","cn":"幼稚无经验的；不成熟的","lab":"informal","sc":"person","ex":{"en":"The new trainees are still very green.","cn":"这些受培训的新学员还很不成熟。"}},{"en":"being a pale colour, as if the person is going to vomit","cn":"苍白的；发青的；无血色的","sc":"person","ex":{"en":"It was a rough crossing and most of the passengers looked distinctly green.","cn":"渡海时风浪很大，多数乘客看上去脸色发青。"}},{"en":"the colour of grass and the leaves of most plants and trees","cn":"绿色；草绿色","g":"[uncountable, countable]","sc":"colour","ex":{"en":"light/pale green","cn":"浅绿色"},"pos":"noun"},{"en":"vegetables with dark green leaves, for example cabbage or spinach","cn":"青菜，绿叶菜（如卷心菜、菠菜）","g":"[plural]","sc":"vegetables","ex":{"en":"Eat up your greens.","cn":"把你那份青菜都吃了吧。"},"pos":"noun"},{"en":"an area of grass, especially in the middle of a town or village","cn":"（尤指城镇或村庄中心的）草地，草坪，公共绿地","g":"[countable]","lab":"British English","sc":"area of grass","ex":{"en":"Children were playing on the village green.","cn":"孩子们在村子里的公共草坪上玩耍。"},"pos":"noun"},{"en":"an area of grass cut short around a hole on a golf course","cn":"球穴区，果岭（高尔夫球洞口附近草修得很平整的地区）","g":"[countable]","sc":"area of grass","ex":{"en":"the 18th green","cn":"第 18 洞果岭"},"pos":"noun"},{"en":"the Green Party (= the party whose main aim is the protection of the environment)","cn":"绿党（以保护环境为主要目标）","g":"[plural]","sc":"politics","pos":"noun"},{"en":"to create parks and other areas with trees and plants in a city","cn":"绿化","sc":"create parks","ex":{"en":"projects for greening the cities","cn":"绿化城市的方案"},"pos":"verb"},{"en":"to make somebody more aware of issues connected with the environment; to make something appear friendly towards the environment","cn":"使增强环境保护意识；使善待环境","sc":"politics","ex":{"en":"an attempt to green industry bosses","cn":"使企业老板重视环境保护的努力"},"pos":"verb"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"绿；绿色","en":"Green is the colour of grass or leaves.","ex":{"en":"...shiny red and green apples","cn":"红红绿绿、富有光泽的苹果"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"长满青草的；绿油油的；碧绿的","en":"A place that is green is covered with grass, plants, and trees and not with houses or factories.","ex":{"en":"Cairo has only thirteen square centimetres of green space for each inhabitant.","cn":"开罗居民的人均绿地面积仅13平方厘米。"}},{"pos":"ADJ 形容词","cn":"环境保护的；主张环境保护的","en":"Green issues and political movements relate to or are concerned with the protection of the environment.","ex":{"en":"The power of the Green movement in Germany has made that country a leader in the drive to recycle more waste materials.","cn":"德国环保运动的影响力使得该国率先发起了回收利用更多废品的运动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有利于环境的；环保的；绿色的","en":"If you say that someone or something is green, you mean they harm the environment as little as possible.","ex":{"en":"...trying to persuade governments to adopt greener policies","cn":"试图说服政府采取更为环保的政策"}},{"pos":"N-COUNT 可数名词","cn":"绿党成员（主张环境保护）","en":"Greens are members of green political movements.","ex":{"en":"The Greens see themselves as a radical alternative to the two major British political parties.","cn":"绿党人士认为他们与英国的两个主要政党截然不同。"}},{"pos":"N-COUNT 可数名词","cn":"（高尔夫球场的）球穴区，果岭","en":"A green is a smooth, flat area of grass around a hole on a golf course.","ex":{"en":"...the 18th green.","cn":"第18洞轻击区"}},{"pos":"N-COUNT 可数名词","cn":"（尤指城市或村庄中心的）草坪，绿地","en":"A green is an area of land covered with grass, especially in a town or in the middle of a village.","ex":{"en":"...the village green.","cn":"村子里的草坪"}},{"pos":"N-IN-NAMES 名称名词","cn":"（用于有绿地或过去有绿地的地方中）","en":"Green is used in the names of places that contain or used to contain an area of grass.","ex":{"en":"...Bethnal Green.","cn":"贝斯纳尔格林区"}},{"pos":"N-PLURAL 复数名词","cn":"绿叶菜；青菜","en":"You can refer to the cooked leaves of vegetables such as spinach or cabbage as greens .","ex":{"en":"Eat your greens.","cn":"把青菜吃掉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未熟的；青的；生的","en":"You can describe fruit and vegetables as green when they are unripe and not ready to be eaten.","ex":{"en":"Pick and ripen any green fruits in a warm dark place.","cn":"摘些还没有熟的水果然后在温暖阴暗的地方放熟。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"缺乏经验的；不成熟的；幼稚的","en":"If you say that someone is green, you mean that they have had very little experience of life or a particular job.","ex":{"en":"He was a young lad, very green, very immature.","cn":"他还是个毛头小子，幼稚得很，一点都不成熟。"}},{"pos":"PHRASE 短语","cn":"非常嫉妒的；眼红的","en":"If you say that someone is green with envy, you mean that they are very envious indeed."},{"pos":"PHRASE 短语","cn":"高超的园艺技能","en":"If someone has green fingers, they are very good at gardening and their plants grow well.","ex":{"en":"You don't need green fingers to fill your home with lush leaves.","cn":"不是园艺大师也可以把自己的家里装点得绿意盎然。"}},{"pos":"","cn":"","en":"to give someone the green light→see: ;"}]},"examples":[{"en":"The room was decorated in a combination of greens and blues.","cn":"这房间是把不同的绿色和蓝色搭配起来装饰的。"},{"en":"It was a rough crossing and most of the passengers looked distinctly green.","cn":"渡海时风浪很大，多数乘客看上去脸色发青。"}]},"grocers":{"oxford":{"phon":"ˈɡrəʊsə(r)","pos":"noun","senses":[{"en":"a person who owns, manages or works in a shop/store selling food and other things used in the home","cn":"食物杂货商"},{"en":"a shop/store that sells these things","cn":"食物杂货店"}]}},"grammatically":{"oxford":{"phon":"ɡrəˈmætɪkli","pos":"adverb","senses":[{"en":"in a way that is connected with the rules of grammar","cn":"语法的；文法的","ex":{"en":"a grammatically correct sentence","cn":"语法正确的句子"}},{"en":"in a way that correctly follows the rules of grammar","cn":"符合语法规则的；合乎文法的","ex":{"en":"to speak grammatically","cn":"合乎语法地说话"}}]},"media":{"uk":"media/uk/grammatically__gb_1.mp3","us":"media/us/grammatically__us_1.mp3"},"examples":[{"en":"a grammatically correct sentence","cn":"语法上正确的句子"}]},"graphic":{"media":{"uk":"media/uk/graphic__gb_1.mp3","us":"media/us/graphic__us_1.mp3"},"oxford":{"phon":"ˈɡræfɪk","pos":"adjective","senses":[{"en":"connected with drawings and design, especially in the production of books, magazines, websites, etc.","cn":"绘画的；书画的；图样的；图案的","g":"[only before noun]","ex":{"en":"graphic design","cn":"平面设计"}},{"en":"very clear and full of details, especially about something unpleasant","cn":"（尤指令人不快的事物）形象的，生动的，逼真的","ex":{"en":"a graphic account/description of a battle","cn":"对战斗的生动叙述／描述"}},{"en":"a diagram or picture, especially one that appears on a computer screen or in a newspaper or book","cn":"（尤指电脑屏幕、报纸或书上的）图表，图形，图画","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对令人不快之事的描述）形象的，具体的，活灵活现的","en":"If you say that a description or account of something unpleasant is graphic, you are emphasizing that it is clear and detailed.","ex":{"en":"The descriptions of sexual abuse are graphic.","cn":"这些性虐待的描写绘声绘色。"}},{"pos":"ADJ 形容词","cn":"绘画的；绘图的；图像的","en":"Graphic means concerned with drawing or pictures, especially in publishing, industry, or computing.","ex":{"en":"...fine and graphic arts.","cn":"美术与平面艺术"}},{"pos":"N-UNCOUNT 不可数名词","cn":"绘画；(尤指出版、工业或计算机领域的)制图,图形设计","en":"Graphics is the activity of drawing or making pictures, especially in publishing, industry, or computing.","ex":{"en":"...a computer manufacturer which specialises in graphics.","cn":"专注于图形设计的计算机制造商"}},{"pos":"N-COUNT 可数名词","cn":"绘画作品；图表；图样","en":"Graphics are drawings and pictures that are composed using simple lines and sometimes strong colours.","ex":{"en":"The articles are noticeably shorter with strong headlines and graphics","cn":"这些文章明显短了许多，并且配上了醒目的标题和图表。"}}]},"examples":[{"en":"He kept telling us about his operation, in the most graphic detail.","cn":"他不停地向我们绘声绘色地讲述他动手术的详细情况。"},{"en":"a graphic account/description of a battle","cn":"对战斗的生动叙述/描述"}]},"gratification":{"media":{"uk":"media/uk/gratification__gb_1.mp3","us":"media/us/gratification__us_1.mp3"},"oxford":{"phon":"ˌɡrætɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"the state of feeling pleasure when something goes well for you or when your desires are satisfied; something that gives you pleasure","cn":"满足；满意；快感；令人喜悦的事物","ex":{"en":"sexual gratification","cn":"性满足"}}]},"examples":[{"en":"A feed will usually provide instant gratification to a crying baby.","cn":"喂食通常可使正在哭闹的婴儿立即得到满足。"},{"en":"sexual gratification","cn":"性满足"}]},"grocery":{"media":{"uk":"media/uk/grocery__gb_1.mp3","us":"media/us/grocery__us_1.mp3","img":["media/ldoce/img/grocery_bag.jpg"]},"oxford":{"phon":"ˈɡrəʊsəri","pos":"noun","senses":[{"en":"a shop that sells food and other things used in the home. In American English ‘grocery store’ is often used to mean ‘supermarket’.","cn":"食品杂货店（在美式英语中 grocery store 常指 supermarket）","g":"[countable]","lab":"especially British English","ex":{"en":"the corner grocery store","cn":"街角处的杂货店"}},{"en":"food and other goods sold by a grocer or at a supermarket","cn":"食品杂货","g":"[plural]","lab":"especially British English","ex":{"en":"He walked in and set the bag of groceries down on the floor.","cn":"他走进来，把那袋食品杂货放在地板上。"}},{"en":"connected with food and other goods sold by a grocer or at a supermarket","cn":"食品杂货","ex":{"en":"the grocery bill","cn":"食品杂货账单"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"食品杂货店","en":"A grocery or a grocery store is a grocer's shop."},{"pos":"N-PLURAL 复数名词","cn":"食品杂货","en":"Groceries are foods you buy at a grocer's or at a supermarket such as flour, sugar, and tinned foods."}]},"examples":[{"en":"the grocery bill","cn":"食品杂货账单"}]},"gravy":{"oxford":{"phon":"ˈɡreɪvi","pos":"noun","senses":[{"en":"a brown sauce made by adding flour to the juices that come out of meat while it is cooking","cn":"（调味）肉汁","g":"[uncountable, countable]"},{"en":"something, especially money, that is obtained when you do not expect it","cn":"意外之财；飞来福","g":"[uncountable]","lab":"North American English, informal，，","ex":{"en":"Anything on top of eight percent profit is just gravy for the industry.","cn":"任何高于百分之八利润的东西都只是这个行业的肉汁。"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"肉汁；肉卤","en":"Gravy is a sauce made from the juices that come from meat when it cooks."}]},"media":{"uk":"media/uk/gravy__gb_1.mp3","us":"media/us/gravy__us_1.mp3"}},"gross":{"media":{"uk":"media/uk/gross__gb_1.mp3","us":"media/us/gross__us_1.mp3"},"oxford":{"phon":"ɡrəʊs","pos":"adjective","senses":[{"en":"being the total amount of something before anything is taken away","cn":"（未扣除税费）总的，毛的","g":"[only before noun]","ex":{"en":"gross weight (= including the container or wrapping)","cn":"毛重"}},{"en":"very obvious and unacceptable","cn":"严重的","g":"[only before noun]","lab":"formal or law","ex":{"en":"gross negligence/misconduct","cn":"严重过失／失职"}},{"en":"very unpleasant","cn":"令人不快的；令人恶心的；使人厌恶的","lab":"informal","ex":{"en":"‘He ate it with mustard.’ ‘Oh, gross!’","cn":"“他用芥末拌着吃。”“啊，真恶心！”"}},{"en":"very rude","cn":"粗鲁的；不雅的","ex":{"en":"gross behaviour","cn":"粗鲁的行为"}},{"en":"very fat and ugly","cn":"肥胖而丑陋的"},{"en":"in total, before anything is taken away","cn":"（未扣除税费）总共","ex":{"en":"She earns £25 000 a year gross.","cn":"她税前年收入 25 000 英镑。"},"pos":"adverb"},{"en":"to earn a particular amount of money before tax has been taken off it","cn":"（未扣除税费）总收入为，总共赚得","ex":{"en":"It is one of the biggest grossing movies of all time.","cn":"这是有史以来票房总收入最高的影片之一。"},"pos":"verb"},{"en":"a group of 144 things","cn":"一罗（144 个）","ex":{"en":"two gross of apples","cn":"两罗苹果"},"pos":"noun"},{"en":"a total amount of money earned by something, especially a film, before any costs are taken away","cn":"（尤指影片的）毛收入，总收入","lab":"especially US English","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"重大的；严重的；极端的","en":"You use gross to describe something unacceptable or unpleasant to a very great amount, degree, or intensity.","ex":{"en":"The company were guilty of gross negligence.","cn":"该公司犯有严重过失。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（言语、行为）极端粗俗的，下流的","en":"If you say that someone's speech or behaviour is gross, you think it is very rude or unacceptable.","ex":{"en":"He abused the Admiral in the grossest terms","cn":"他用不堪入耳的话辱骂那位海军上将。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人不快的；让人恶心的；令人厌恶的","en":"If you describe something as gross, you think it is very unpleasant.","ex":{"en":"They had a commercial on the other night for Drug Free America that was so gross I thought Daddy was going to faint","cn":"他们前几天晚上为“美国远离毒品”组织播的那则广告非常恶心，我觉得爸爸看了都快晕过去了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肥胖难看的；臃肿的","en":"If you describe someone as gross, you mean that they are extremely fat and unattractive.","ex":{"en":"I only resist things like chocolate if I feel really gross.","cn":"我只有在觉得自己胖得很难看的时候才能拒绝巧克力这类东西的诱惑。"}},{"pos":"ADJ 形容词","cn":"（尤指金额）总的，毛的","en":"Gross means the total amount of something, especially money, before any has been taken away.","ex":{"en":"...a fixed rate account guaranteeing 10.4% gross interest or 7.8% net until October.","cn":"10月份之前保证10.4%的毛利或7.8%的纯利收益的固定利率账户"}},{"pos":"ADJ 形容词","cn":"全部的；总计的","en":"Gross means the total amount of something, after all the relevant amounts have been added together.","ex":{"en":"National Savings gross sales in June totalled £709 million.","cn":"6月份国民储蓄机构的总销售额为7.09亿英镑。"}},{"pos":"ADJ 形容词","cn":"总重量的；毛重的","en":"Gross means the total weight of something, including its container or wrapping."},{"pos":"VERB 动词","cn":"（扣除税金前）总共赚得，总收入为","en":"If a person or a business grosses a particular amount of money, they earn that amount of money before tax has been taken away.","ex":{"en":"I'm a factory worker who grossed £12,900 last year","cn":"我是个工厂工人，去年的总收入为12,900英镑。"}},{"pos":"NUM 数词","cn":"罗（一罗为144个）","en":"A gross is a group of 144 things.","ex":{"en":"He ordered twelve gross of the disks.","cn":"他订购了12罗磁盘。"}},{"pos":"","cn":"","en":"相关词组：gross out"}]},"examples":[{"en":"‘He ate it with mustard.’ ‘Oh, gross!’ “","cn":"他用芥末拌着吃。” “啊，真恶心！”"},{"en":"She earns £25 000 a year gross.","cn":"她一年总收入为 25 000 英镑。"}]},"gravitational":{"media":{"uk":"media/uk/gravitational__gb_1.mp3","us":"media/us/gravitational__us_1.mp3"},"oxford":{"phon":"ˌɡrævɪˈteɪʃənl","pos":"adjective","senses":[{"en":"connected with or caused by the force of gravity","cn":"引力的；重力引起的","ex":{"en":"a gravitational field","cn":"引力场"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"与引力有关的；引力所致的","en":"Gravitational means relating to or resulting from the force of gravity.","ex":{"en":"If a spacecraft travels faster than 11 km a second, it escapes the earth's gravitational pull.","cn":"如果飞行速度超过每秒11公里，宇宙飞船将摆脱地球的引力。"}}]},"examples":[{"en":"the gravitational pull of the moon","cn":"月球的引力"},{"en":"a gravitational field","cn":"引力场"}]},"grassland":{"media":{"uk":"media/uk/grassland__gb_1.mp3","us":"media/us/grassland__us_1.mp3"},"oxford":{"phon":"ˈɡrɑːslænd","pos":"noun","senses":[{"en":"a large area of open land covered with wild grass","cn":"草原；草地；草场","ex":{"en":"turning grassland into farm land","cn":"把草地变成农田"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"草原；草地；草场","en":"Grassland is land covered with wild grass.","ex":{"en":"...areas of open grassland.","cn":"一片片开阔的草地"}}]}},"grin":{"media":{"uk":"media/uk/grin__gb_1.mp3","us":"media/us/grin__us_1.mp3","img":["media/ldoce/img/grin.jpg"]},"oxford":{"phon":"ɡrɪn","pos":"verb","senses":[{"en":"to smile widely","cn":"露齿而笑；咧着嘴笑；粲然而笑","ex":{"en":"They grinned with delight when they heard our news.","cn":"他们得知我们的消息时高兴得直咧着嘴笑。"}},{"en":"a wide smile","cn":"露齿的笑；咧着嘴笑","ex":{"en":"She gave a broad grin.","cn":"她露出大大的笑容。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"露齿而笑；咧嘴大笑","en":"When you grin, you smile broadly.","ex":{"en":"He grins, delighted at the memory","cn":"想到往事，他开心地咧嘴笑了起来。"}},{"pos":"N-COUNT 可数名词","cn":"露齿的笑；咧嘴的笑","en":"A grin is a broad smile.","ex":{"en":"She came out of his office with a big grin on her face","cn":"她笑容满面地走出他的办公室。"}},{"pos":"PHRASE 短语","cn":"苦笑着忍受；默默承受","en":"If you grin and bear it, you accept a difficult or unpleasant situation without complaining because you know there is nothing you can do to make things better.","ex":{"en":"They cannot stand the sight of each other, but they will just have to grin and bear it.","cn":"他们连看对方一眼都不愿意，但是也只得默默忍受。"}}]},"examples":[{"en":"They grinned with delight when they heard our news.","cn":"他们得知我们的消息时高兴得直咧着嘴笑。"},{"en":"There's nothing we can do about it. We'll just have to grin and bear it.","cn":"对此我们无能为力，只好默默地忍受。"}]},"grime":{"media":{"uk":"media/uk/grime__gb_1.mp3","us":"media/us/grime__us_1.mp3"},"oxford":{"phon":"ɡraɪm","pos":"noun","senses":[{"en":"dirt that forms a layer on the surface of something","cn":"一层污垢；尘垢；积垢","ex":{"en":"a face covered with grime and sweat","cn":"满是污垢和汗水的脸"}},{"en":"a type of electronic dance music that developed from drum and bass, UK garage and other styles","cn":"车库说唱（由鼓打贝司、英式车库等音乐风格发展而来的一种电子舞曲音乐）"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"污垢；尘垢","en":"Grime is dirt which has collected on the surface of something.","ex":{"en":"Kelly got the grime off his hands before rejoining her in the kitchen.","cn":"凯利洗去手上的污垢，又回到厨房来帮她的忙。"}}]},"examples":[{"en":"a face covered with grime and sweat","cn":"满是污垢和汗水的脸"},{"en":"The walls were black with grime.","cn":"墙上黑黑的﹐积满了污垢。"}]},"gravelled":{"media":{"uk":"media/uk/gravelled__gb_1.mp3","us":"media/us/gravelled__us_1.mp3"},"oxford":{"phon":"ˈɡrævld","pos":"adjective","senses":[{"en":"covered with gravel","cn":"砾石铺的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（道路等）铺上碎石的","en":"A gravelled path, road, or area has a surface made of gravel."}]}},"greatness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely big","cn":""},{"en":"very big – used especially to describe the level or number of something","cn":""}]},"examples":[{"en":"The movie was a great success.","cn":"","src":"ld"},{"en":"The news came as possibly the greatest shock of my life.","cn":"","src":"ld"}],"media":{"uk":"media/uk/greatness__gb_1.mp3","us":"media/us/greatness__us_1.mp3"},"oxford":{"phon":"ˈɡreɪtnəs","pos":"noun","senses":[{"en":"the fact of having high status or a lot of influence","cn":"地位高的；位高权重的；影响大的","ex":{"en":"He was made into a symbol of national greatness.","cn":"他被塑造成国家强大的象征。"}},{"en":"the quality of being extremely good in ability or quality and therefore admired by many people","cn":"伟大的；优秀的；杰出的；卓越的","ex":{"en":"The novel's greatness lies in its simplicity.","cn":"这部小说的伟大之处在于它的简洁。"}}]}},"gregarious":{"media":{"uk":"media/uk/gregarious__gb_1.mp3","us":"media/us/gregarious__us_1.mp3"},"oxford":{"phon":"ɡrɪˈɡeəriəs","pos":"adjective","senses":[{"en":"liking to be with other people","cn":"爱交际的；合群的","ex":{"en":"She’s very outgoing and gregarious.","cn":"她非常外向且合群。"}},{"en":"living in groups","cn":"群居的","lab":"biology"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"爱交际的；合群的","en":"Someone who is gregarious enjoys being with other people.","ex":{"en":"She is such a gregarious and outgoing person.","cn":"她很外向，喜欢交朋结友。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（动物、鸟等）群居的","en":"Gregarious animals or birds normally live in large groups.","ex":{"en":"Snow geese are very gregarious birds.","cn":"雪雁是群居性鸟类。"}}]}},"groundbreaking":{"media":{"uk":"media/uk/groundbreaking__gb_1.mp3","us":"media/us/groundbreaking__us_1.mp3"},"oxford":{"phon":"ˈɡraʊndbreɪkɪŋ","pos":"adjective","senses":[{"en":"making new discoveries; using new methods","cn":"开创性的；创新的；革新的","ex":{"en":"a groundbreaking piece of research","cn":"富有开拓性的一项研究"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"开创性的；创新的；革新的","en":"You use groundbreaking to describe things which you think are significant because they provide new and positive ideas, and influence the way people think about things.","ex":{"en":"...his groundbreaking novel on homosexuality.","cn":"他关于同性恋题材的开创性小说"}}]},"examples":[{"en":"a groundbreaking piece of research","cn":"富有开拓性的一项研究"},{"en":"groundbreaking research","cn":"具开拓性的研究"}]},"gravel":{"media":{"uk":"media/uk/gravel__gb_1.mp3","us":"media/us/gravel__us_1.mp3"},"oxford":{"phon":"ˈɡrævl","pos":"noun","senses":[{"en":"small stones, often used to make the surface of paths and roads","cn":"沙砾；砾石；石子","ex":{"en":"a gravel path","cn":"石子路"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"砂砾；砾石","en":"Gravel consists of very small stones. It is often used to make paths.","ex":{"en":"...a gravel path leading to the front door.","cn":"通向前门的石子路"}}]},"examples":[{"en":"a gravel pit (= a place where gravel is taken from the ground)","cn":"砾石采掘场"},{"en":"a gravel path","cn":"石子路"}]},"grocer":{"oxford":{"phon":"ˈɡrəʊsə(r)","pos":"noun","senses":[{"en":"a person who owns, manages or works in a shop selling food and other things used in the home","cn":"食品杂货商"},{"en":"a shop that sells these things","cn":"食品杂货店"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"食品杂货商","en":"A grocer is a shopkeeper who sells foods such as flour, sugar, and tinned foods."},{"pos":"N-COUNT 可数名词","cn":"食品杂货店","en":"A grocer or a grocer's is a shop where foods such as flour, sugar, and tinned foods are sold."}]},"media":{"uk":"media/uk/grocer__gb_1.mp3","us":"media/us/grocer__us_1.mp3"}},"growing":{"media":{"uk":"media/uk/growing__gb_1.mp3","us":"media/us/growing__us_1.mp3"},"oxford":{"phon":"ˈɡrəʊɪŋ","pos":"adjective","senses":[{"en":"increasing in size, amount or degree","cn":"增加的；增长的；增强的","ex":{"en":"A growing number of people are returning to full-time education.","cn":"越来越多的人重返学校接受全日制教育。"}},{"en":"becoming bigger and taller and developing into an adult","cn":"成长的；发育的；生长的","ex":{"en":"A growing child needs plenty of sleep.","cn":"成长中的孩子需要充足的睡眠。"}}]},"examples":[{"en":"A growing number of people are returning to full-time education.","cn":"越来越多的人重返学校接受全日制教育。"},{"en":"There is growing concern over the safety of the missing teenager.","cn":"人们对这个失踪少年的安全越来越担心。"}]},"granted":{"oxford":{"phon":"ˈɡrɑːntɪd","pos":"adverb","senses":[{"en":"used to show that you accept that something is true, often before you make another statement about it","cn":"（表示肯定属实，然后再作另一番表述）不错，的确","ex":{"en":"‘You could have done more to help.’ ‘Granted.’","cn":"“你本可以多给点帮助的。”“我承认。”"}},{"en":"because of the fact that","cn":"因为","ex":{"en":"Granted that it is a simple test to perform, it should be easy to get results quickly.","cn":"因为这化验做起来简单，所以应该不难很快得出结果。"},"pos":"conjunction"}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"（表示某事属实，然后再对其作出评论）不错，的确","en":"You use granted or granted that at the beginning of a clause to say that something is true, before you make a comment on it.","ex":{"en":"Granted that the firm has not broken the law, is the law what it should be?","cn":"的确，这家公司没有违法，但这样的法律是否合理呢？"}}]},"media":{"uk":"media/uk/granted__gb_1.mp3","us":"media/us/granted__us_1.mp3"},"examples":[{"en":"Granted that it is a simple test to perform, it should be easy to get results quickly.","cn":"因为这化验做起来简单，所以应该不难很快得出结果。"},{"en":"Granted, it's not the most pleasant of jobs but it has to be done.","cn":"的确，这不是最令人愉快的工作，但也得做呀。"}]},"gray":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/gray__gb_1.mp3","us":"media/us/gray__us_1.mp3"},"oxford":{"phon":"ɡreɪ","pos":"adjective","senses":[{"en":"having the colour of smoke or ashes","cn":"灰色的；烟灰色的；灰白色的","ex":{"en":"gray eyes/hair","cn":"灰色的眼睛/头发"}},{"en":"not bright; full of clouds","cn":"昏暗的；阴沉的","ex":{"en":"gray skies","cn":"灰蒙蒙的天空"}},{"en":"having grey hair","cn":"头发花白；头发灰白","g":"[not usually before noun]","ex":{"en":"He's gone very gray.","cn":"他的脸色已经非常灰白了。"}},{"en":"pale, because they are ill, tired or sad","cn":"苍白的","ex":{"en":"The next morning she looked very gray and hollow-eyed.","cn":"第二天早上，她看上去脸色灰白，眼睛凹陷。"}},{"en":"without interest or variety; making you feel sad","cn":"单调乏味的；忧郁的；沉闷的","ex":{"en":"Life seems gray and pointless without him.","cn":"没有他，生活显得灰暗而毫无意义。"}},{"en":"not interesting or attractive","cn":"没趣味的；毫无吸引力的","lab":"disapproving","ex":{"en":"The company was full of faceless gray men who all looked the same.","cn":"公司里挤满了没有面孔的灰色男人，他们看起来都一样。"}},{"en":"connected with old people","cn":"老年人的","g":"[only before noun]","ex":{"en":"the gray vote","cn":"老年选民的投票"}},{"en":"the colour of smoke or ashes","cn":"灰色；烟灰色；灰白色","g":"[uncountable, countable]","ex":{"en":"the dull gray of the sky","cn":"天空的暗灰色"},"pos":"noun"},{"en":"a gray or white horse","cn":"褐马","g":"[countable]","ex":{"en":"She's riding the gray.","cn":"她骑着那匹灰马。"},"pos":"noun"},{"en":"to become grey","cn":"变灰白；变花白","ex":{"en":"His hair was greying at the sides.","cn":"他的两鬓已渐渐斑白。"},"pos":"verb"}]}},"grand":{"media":{"uk":"media/uk/grand__gb_1.mp3","us":"media/us/grand__us_1.mp3"},"oxford":{"phon":"ɡrænd","pos":"adjective","senses":[{"en":"impressive and large or important","cn":"壮丽的；堂皇的；重大的","ex":{"en":"It's not a very grand house.","cn":"这房子并不是十分富丽堂皇。"}},{"en":"used in the names of impressive or very large buildings, etc.","cn":"（用于大建筑物等的名称）大","g":"[only before noun]","ex":{"en":"the Grand Canyon","cn":"大峡谷"}},{"en":"needing a lot of effort, money or time to succeed but intended to achieve impressive results","cn":"宏大的；宏伟的；有气派的","ex":{"en":"a grand plan/strategy/scheme","cn":"宏大计划；重大战略；重要方案"}},{"en":"used to describe the largest or most important item of its kind","cn":"最大的；最重要的","ex":{"en":"The film won the grand prize at the Berlin Film Festival.","cn":"这部电影在柏林电影节上获大奖。"}},{"en":"behaving in a proud way because they are rich or from a high social class","cn":"傲慢的；高高在上的","ex":{"en":"They're all Lord or Lady somebody or other, but they're not at all grand.","cn":"他们都是勋爵或夫人，但他们一点也不伟大。"}},{"en":"very good or great fun; excellent","cn":"极好的；快乐的；美妙的；出色的","lab":"dialect or informal","ex":{"en":"I had a grand day out at the seaside.","cn":"我在海边痛痛快快玩了一天。"}},{"en":"used in the titles of people of very high social rank","cn":"（对上层社会的人的称呼）大","ex":{"en":"the Grand Duchess Elena","cn":"大公夫人埃琳娜"}},{"en":"$1 000; £1 000","cn":"1 000 美元；1 000 英镑","lab":"informal","ex":{"en":"It'll cost you five grand!","cn":"这要花去你五千块钱！"},"pos":"noun"},{"en":"a large piano in which the strings are horizontal","cn":"大钢琴；三角钢琴","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宏伟的；壮丽的；富丽堂皇的","en":"If you describe a building or a piece of scenery as grand, you mean that its size or appearance is very impressive.","ex":{"en":"...this grand building in the center of town","cn":"这幢位于市中心的宏伟建筑"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（计划等）宏伟的，宏大的","en":"Grand plans or actions are intended to achieve important results.","ex":{"en":"Critics will point to other grand schemes that have gone less well, such as Sheffield's World Student Games disaster","cn":"批评家将会指出其他一些并不成功的大项目，比如谢菲尔德世界大学生运动会这一败笔。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"牛气的；不可一世的","en":"People who are grand think they are important or socially superior.","ex":{"en":"He is grander and even richer than the Prince of Wales","cn":"他比威尔士亲王还牛气，甚至更有钱。"}},{"pos":"ADJ 形容词","cn":"快乐的；令人非常愉快的","en":"If you describe an activity or experience as grand, you mean that it is very pleasant and enjoyable.","ex":{"en":"Few museums could rival the Old Royal Observatory at Greenwich for a grand day out","cn":"若想找个地儿开心地逛一天，没有哪家博物馆能比得上格林尼治皇家天文台。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"了不起的；出色的；极好的","en":"You can describe someone or something as grand when you admire or approve of them very much.","ex":{"en":"He was a grand bloke.","cn":"他非常了不起。"}},{"pos":"ADJ 形容词","cn":"总括的","en":"A grand total is one that is the final amount or the final result of a calculation.","ex":{"en":"It came to a grand total of £20,329.","cn":"总计20,329英镑。"}},{"pos":"ADJ 形容词","cn":"（常用于大型建筑物的名称前）大的","en":"Grand is often used in the names of buildings such as hotels, especially when they are very large.","ex":{"en":"They stayed at The Grand Hotel, Budapest.","cn":"他们住在布达佩斯大饭店。"}},{"pos":"N-COUNT 可数名词","cn":"一千美元（或英镑）","en":"A grand is a thousand dollars or a thousand pounds.","ex":{"en":"They're paying you ten grand now for those adaptations of old plays.","cn":"他们打算付你一万美元作为改编老剧本的报酬。"}},{"pos":"N-COUNT 可数名词","cn":"同grand piano","en":"A grand is the same as a grand piano ."}]},"examples":[{"en":"James Lovelock, the grand old man of environmental science","cn":"詹姆斯 · 洛夫洛克，环境科学的元老"},{"en":"She finally learned to drive at the grand old age of 70.","cn":"她终于在 70 岁高龄学会了开车。"}]},"grasp":{"oxford":{"phon":"ɡrɑːsp","pos":"verb","senses":[{"en":"to take a strong hold of somebody/something","cn":"抓紧；抓牢","ex":{"en":"He grasped my hand and shook it warmly.","cn":"他热情地抓住我的手握了起来。"}},{"en":"to understand something completely","cn":"理解；领会；领悟；明白","ex":{"en":"They failed to grasp the importance of his words.","cn":"他们没有理解他的话的重要性。"}},{"en":"to take an opportunity without hesitating and use it","cn":"急忙抓住，毫不犹豫地抓住（机会）","ex":{"en":"I grasped the opportunity to work abroad.","cn":"我毫不犹豫地抓住了去国外工作的机会。"}},{"en":"a strong hold of somebody/something or control over somebody/something","cn":"紧抓；紧握；控制","ex":{"en":"I grabbed him, but he slipped from my grasp.","cn":"我紧抓着他，可他还是从我手里溜掉了。"},"pos":"noun"},{"en":"a person’s understanding of a subject or of difficult facts","cn":"理解（力）；领会","ex":{"en":"He has a good grasp of German grammar.","cn":"他德语语法掌握得很好。"},"pos":"noun"},{"en":"the ability to get or achieve something","cn":"能力所及","ex":{"en":"Success was within her grasp.","cn":"她有把握获得成功。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"抓紧；握牢；握紧","en":"If you grasp something, you take it in your hand and hold it very firmly.","ex":{"en":"He grasped both my hands","cn":"他紧紧抓住我的双手。"}},{"pos":"N-SING 单数名词","cn":"紧抓；紧握","en":"A grasp is a very firm hold or grip.","ex":{"en":"His hand was taken in a warm, firm grasp.","cn":"他的手被热情地紧紧握住了。"}},{"pos":"N-SING 单数名词","cn":"掌握；控制","en":"If you say that something is in someone's grasp, you disapprove of the fact that they possess or control it. If something slips from your grasp, you lose it or lose control of it.","ex":{"en":"The people in your grasp are not guests, they are hostages","cn":"你所控制的这些人不是客人，而是人质。"}},{"pos":"VERB 动词","cn":"理解；领悟；明白","en":"If you grasp something that is complicated or difficult to understand, you understand it.","ex":{"en":"The Government has not yet grasped the seriousness of the crisis","cn":"政府当局还没有意识到这场危机的严重性。"}},{"pos":"N-SING 单数名词","cn":"理解；掌握","en":"A grasp of something is an understanding of it.","ex":{"en":"They have a good grasp of foreign languages.","cn":"他们外语掌握得很好。"}},{"pos":"PHRASE 短语","cn":"为…所能实现；为…所能及","en":"If you say that something is within someone's grasp, you mean that it is very likely that they will achieve it.","ex":{"en":"Peace is now within our grasp.","cn":"现在和平在望。"}}]},"media":{"uk":"media/uk/grasp__gb_1.mp3","us":"media/us/grasp__us_1.mp3"},"examples":[{"en":"She grasped at his coat as he rushed past her.","cn":"他从她身边冲过去时，她使劲地向他的外衣抓去。"},{"en":"It took him some time to grasp that he was now a public figure.","cn":"他过了些时候才意识到自己已是个公众人物了。"}]},"grey":{"media":{"uk":"media/uk/grey__gb_1.mp3","us":"media/us/grey__us_1.mp3"},"oxford":{"phon":"ɡreɪ","pos":"adjective","senses":[{"en":"having the colour of smoke or ashes","cn":"灰色的；烟灰色的；灰白色的","ex":{"en":"grey eyes/hair","cn":"灰色的眼睛；花白的头发"}},{"en":"not bright; full of clouds","cn":"昏暗的；阴沉的","ex":{"en":"grey skies","cn":"昏暗的天空"}},{"en":"having grey hair","cn":"头发花白；头发灰白","g":"[not usually before noun]","ex":{"en":"He's gone very grey.","cn":"他已满头银丝。"}},{"en":"pale, because they are ill, tired or sad","cn":"苍白的","ex":{"en":"The next morning she looked very grey and hollow-eyed.","cn":"第二天早上她脸色苍白，眼窝深陷。"}},{"en":"without interest or variety; making you feel sad","cn":"单调乏味的；忧郁的；沉闷的","ex":{"en":"Life seems grey and pointless without him.","cn":"没有他，生活就显得沉闷而无意义。"}},{"en":"not interesting or attractive","cn":"没趣味的；毫无吸引力的","lab":"disapproving","ex":{"en":"The company was full of faceless grey men who all looked the same.","cn":"公司里全是些缺乏个性、毫无吸引力的男人。"}},{"en":"connected with old people","cn":"老年人的","g":"[only before noun]","ex":{"en":"the grey vote","cn":"老年人的投票总数"}},{"en":"the colour of smoke or ashes","cn":"灰色；烟灰色；灰白色","g":"[uncountable, countable]","ex":{"en":"the dull grey of the sky","cn":"暗灰色的天空"},"pos":"noun"},{"en":"a grey or white horse","cn":"灰马；白马","g":"[countable]","ex":{"en":"She's riding the grey.","cn":"她骑着一匹灰马。"},"pos":"noun"},{"en":"to become grey","cn":"变灰白；变花白","ex":{"en":"His hair was greying at the sides.","cn":"他的两鬓已渐渐斑白。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"灰色","en":"Grey is the colour of ashes or of clouds on a rainy day.","ex":{"en":"...a grey suit.","cn":"灰色套装"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（头发）灰白的","en":"You use grey to describe the colour of people's hair when it changes from its original colour, usually as they get old.","ex":{"en":"...my grey hair","cn":"我灰白的头发"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天气）昏暗的，阴沉的","en":"If the weather is grey, there are many clouds in the sky and the light is dull.","ex":{"en":"It was a grey, wet April Sunday.","cn":"这是4月一个阴雨绵绵的星期天。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沉闷的；阴郁的；暗淡的","en":"If you describe a situation as grey, you mean that it is dull, unpleasant, or difficult.","ex":{"en":"Brazilians look gloomily forward to a New Year that even the president admits will be grey and cheerless.","cn":"展望新年，巴西人心情沮丧，甚至连总统都承认明年困难重重，不容乐观。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"单调乏味的；无特色的；不吸引人的","en":"If you describe someone or something as grey, you think that they are boring and unattractive, and very similar to other things or other people.","ex":{"en":"...little grey men in suits.","cn":"身着西服、缺乏个性的小个子男人们"}},{"pos":"ADJ 形容词","cn":"老年人的（新闻用语）","en":"Journalists sometimes use grey to describe things concerning old people.","ex":{"en":"There was further evidence of grey consumer power last week, when Ford revealed a car designed with elderly people in mind.","cn":"福特汽车公司为老年人设计的一款汽车于上周亮相，这进一步体现了老年消费者的购买力。"}}]},"examples":[{"en":"The company was full of faceless grey men who all looked the same.","cn":"公司里全是些缺乏个性、毫无吸引力的男人。"},{"en":"Life seems grey and pointless without him.","cn":"没有他，生活就显得沉闷而无意义。"}]},"grimy":{"media":{"uk":"media/uk/grimy__gb_1.mp3","us":"media/us/grimy__us_1.mp3"},"oxford":{"phon":"ˈɡraɪmi","pos":"adjective","senses":[{"en":"covered with dirt","cn":"沾满污垢的；满是灰尘的","ex":{"en":"grimy hands/windows","cn":"沾满污垢的手；满是灰尘的窗户"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"满是污垢的；肮脏的","en":"Something that is grimy is very dirty.","ex":{"en":"...a grimy industrial city.","cn":"肮脏的工业城市"}}]},"examples":[{"en":"grimy hands/windows","cn":"沾满污垢的手；满是灰尘的窗户"},{"en":"grimy windows","cn":"落满灰尘的窗子"}]},"gratitude":{"media":{"uk":"media/uk/gratitude__gb_1.mp3","us":"media/us/gratitude__us_1.mp3"},"oxford":{"phon":"ˈɡrætɪtjuːd","pos":"noun","senses":[{"en":"the feeling of being grateful and wanting to express your thanks","cn":"感激之情；感谢","ex":{"en":"He smiled at them with gratitude.","cn":"他向他们微笑表示谢意。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"感恩之情；感谢","en":"Gratitude is the state of feeling grateful.","ex":{"en":"...a sense of gratitude","cn":"感恩图报之意"}}]},"examples":[{"en":"She was presented with the gift in gratitude for her long service.","cn":"这礼物赠送给她以表达对她长期服务的感激之情。"},{"en":"I would like to express my gratitude to everyone for their hard work.","cn":"我要对所有辛勤劳动的人表示感谢。"}]},"grew":{"collins":{"senses":[{"pos":"","cn":"","en":"Grew is the past tense of grow."}]},"media":{"uk":"media/uk/grew__gb_1.mp3","us":"media/us/grew__us_1.mp3"}},"growth":{"media":{"uk":"media/uk/growth__gb_1.mp3","us":"media/us/growth__us_1.mp3"},"oxford":{"phon":"ɡrəʊθ","pos":"noun","senses":[{"en":"the process in people, animals or plants of growing physically, mentally or emotionally","cn":"发育；成长；生长","g":"[uncountable]","ex":{"en":"Lack of water will stunt the plant's growth.","cn":"缺水会阻碍植物生长。"}},{"en":"an increase in the size, amount or degree of something","cn":"增加；增长；增强","g":"[uncountable]","ex":{"en":"The report links population growth with rural poverty.","cn":"该报告把人口增长与农村的贫困联系起来。"}},{"en":"an increase in economic activity","cn":"经济增长；经济发展","g":"[uncountable]","ex":{"en":"policies aimed at sustaining economic growth","cn":"旨在保持经济增长的政策"}},{"en":"a mass of cells caused by a disease that forms on or inside a person, an animal or a plant","cn":"肿瘤；赘生物","g":"[countable]","ex":{"en":"a malignant growth","cn":"恶性肿瘤"}},{"en":"something that has grown","cn":"生长物；长成物；产物","g":"[uncountable, countable]","ex":{"en":"The forest's dense growth provides nesting places for a wide variety of birds.","cn":"森林里茂密的植物为各种各样的鸟儿提供了筑巢的地方。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"发展；增长；兴起","en":"The growth of something such as an industry, organization, or idea is its development in size, wealth, or importance.","ex":{"en":"...the growth of nationalism.","cn":"民族主义的高涨"}},{"pos":"N-UNCOUNT 不可数名词","cn":"增加；增多；增长","en":"The growth in something is the increase in it.","ex":{"en":"A steady growth in the popularity of two smaller parties may upset the polls","cn":"两个较小政党的支持率稳步上升，可能会打乱投票结果。"}},{"pos":"ADJ 形容词","cn":"发展的；增长的","en":"A growth industry, area, or market is one which is increasing in size or activity.","ex":{"en":"Computers and electronics are growth industries and need skilled technicians","cn":"计算机与电子行业属于蓬勃发展的产业，需要娴熟的技术人员。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（性格的）成长，发展","en":"Someone's growth is the development and progress of their character.","ex":{"en":"...the child's emotional and intellectual growth","cn":"孩子的情感与智力发展"}},{"pos":"N-UNCOUNT 不可数名词","cn":"发育；生长；成长","en":"Growth in a person, animal, or plant is the process of increasing in physical size and development.","ex":{"en":"...hormones which control fertility and body growth","cn":"控制生殖和身体发育的荷尔蒙"}},{"pos":"N-VAR 可变名词","cn":"新生发的植株；一茬植株","en":"You can use growth to refer to plants which have recently developed or which developed at the same time.","ex":{"en":"This helps to ripen new growth and makes it flower profusely","cn":"这有助于新生发植株的成熟，令其开出繁茂的花朵。"}},{"pos":"N-COUNT 可数名词","cn":"肿块；肿瘤；赘生物","en":"A growth is a lump that grows inside or on a person, animal, or plant, and that is caused by a disease.","ex":{"en":"This type of surgery could even be used to extract cancerous growths.","cn":"这种外科手术甚至可以用来切除癌性肿瘤。"}}]},"examples":[{"en":"The forest's dense growth provides nesting places for a wide variety of birds.","cn":"森林里茂密的植物为各种各样的鸟儿提供了筑巢的地方。"},{"en":"a disappointing year of little growth in Britain and America","cn":"英美经济增长无几令人沮丧的一年"}]},"grape":{"media":{"img":["media/pic/fruit_comp.jpg","media/thumb/grape.jpg"],"uk":"media/uk/grape__gb_1.mp3","us":"media/us/grape__us_1.mp3"},"oxford":{"phon":"ɡreɪp","pos":"noun","senses":[{"en":"a small green or purple fruit that grows in bunches on a climbing plant (called a vine). Wine is made from grapes.","cn":"葡萄","ex":{"en":"a bunch of grapes","cn":"一串葡萄"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"葡萄","en":"Grapes are small green or dark purple fruit which grow in bunches. Grapes can be eaten raw, used for making wine, or dried."},{"pos":"PHRASE 短语","cn":"酸葡萄心理（指因得不到想要的东西便说它一文不值）","en":"If you describe some-one's attitude as sour grapes, you mean that they say something is worthless or undesirable because they want it themselves but cannot have it.","ex":{"en":"These accusations have been going on for some time now, but it is just sour grapes.","cn":"这些指责到现在已经持续了一段时间，但这不过是吃不到葡萄说葡萄酸罢了。"}}]},"examples":[{"en":"black/white grapes (= grapes that are actually purple/green in colour)","cn":"紫/绿葡萄"},{"en":"a bunch of grapes","cn":"一串葡萄"}]},"grip":{"media":{"uk":"media/uk/grip__gb_1.mp3","us":"media/us/grip__us_1.mp3"},"oxford":{"phon":"ɡrɪp","pos":"noun","senses":[{"en":"an act of holding somebody/something tightly; a particular way of doing this","cn":"紧握；紧抓","g":"[countable, usually singular]","lab":"figurative","sc":"holding tightly","ex":{"en":"Keep a tight grip on the rope.","cn":"紧紧抓住绳索不放。"}},{"en":"control or power over somebody/something","cn":"（对…的）控制，影响力","g":"[singular]","sc":"control/power","ex":{"en":"The home team took a firm grip on the game.","cn":"主队牢牢控制着比赛的局面。"}},{"en":"an understanding of something","cn":"理解；了解","g":"[singular]","sc":"understanding","ex":{"en":"I couldn't get a grip on what was going on.","cn":"我无法理解正在发生的事情。"}},{"en":"the ability of something to move over a surface without slipping","cn":"不打滑；走得稳","g":"[uncountable, singular]","sc":"moving without slipping","ex":{"en":"These tyres give the bus better grip in slippery conditions.","cn":"这些轮胎可使公共汽车在路滑时行驶得平稳一些。"}},{"en":"a part of something that has a special surface so that it can be held without the hands slipping","cn":"把手；手柄；握杆","g":"[countable]","sc":"part of object","ex":{"en":"the grip on a golf club","cn":"高尔夫球杆的握柄"}},{"en":"a small thin piece of metal or plastic folded in the middle, used by women for holding their hair in place","cn":"发夹","g":"[countable]","lab":"both British English","sc":"for hair"},{"en":"a person who prepares and moves the cameras, and sometimes the lighting equipment, when a film is being made","cn":"（拍摄电影时）摄影机和灯光设备管理人员","g":"[countable]","sc":"job in the movies"},{"en":"a large soft bag, used when travelling","cn":"旅行袋；手提包","g":"[countable]","lab":"old-fashioned","sc":"bag"},{"en":"to hold something tightly","cn":"抓紧某物","g":"[transitive, intransitive]","sc":"hold tightly","ex":{"en":"‘Please don't go,’ he said, gripping her arm.","cn":"“请别走。”他紧紧抓住她的手臂说。"},"pos":"verb"},{"en":"to interest or have a strong effect on somebody; to hold somebody’s attention","cn":"使感兴趣；使受强有力的影响；吸引住（某人的）注意","g":"[transitive]","sc":"interest/excite","ex":{"en":"The book grips you from start to finish.","cn":"这本书从头至尾扣人心弦。"},"pos":"verb"},{"en":"to have a powerful effect on somebody/something","cn":"对…产生强有力的影响","g":"[transitive]","sc":"have powerful effect","ex":{"en":"I was gripped by a feeling of panic.","cn":"我惊恐万状。"},"pos":"verb"},{"en":"to hold onto or to move over a surface without slipping","cn":"抓牢","g":"[transitive, intransitive]","sc":"move/hold without slipping","ex":{"en":"tyres that grip the road","cn":"抓地力好的车胎"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"紧握；抓牢","en":"If you grip something, you take hold of it with your hand and continue to hold it firmly.","ex":{"en":"She gripped the rope.","cn":"她紧紧抓住绳索。"}},{"pos":"N-COUNT 可数名词","cn":"紧握；抓牢","en":"A grip is a firm, strong hold on something.","ex":{"en":"His strong hand eased the bag from her grip.","cn":"他强有力的手迫使她松开了握紧袋子的双手。"}},{"pos":"N-SING 单数名词","cn":"掌握；支配；控制","en":"Someone's grip on something is the power and control they have over it.","ex":{"en":"The president maintains an iron grip on his country","cn":"总统牢牢地控制着他的国家。"}},{"pos":"VERB 动词","cn":"强烈地影响","en":"If something grips you, it affects you very strongly.","ex":{"en":"Pain gripped him","cn":"他感到一阵剧痛。"}},{"pos":"VERB 动词","cn":"吸引;迷住","en":"If you are gripped by something such as a story or a series of events, your attention is concentrated on it and held by it.","ex":{"en":"The nation is gripped by the dramatic story.","cn":"举国上下都为那个戏剧性的故事牵动着。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"防滑；抓地力","en":"If things such as shoes or car tyres have grip, they do not slip.","ex":{"en":"...a new way of reinforcing rubber which gives car tyres better grip.","cn":"加固橡胶以增强车胎抓地力的新方法"}},{"pos":"N-COUNT 可数名词","cn":"手提包；旅行袋","en":"A grip is a bag that is smaller than a suitcase, and that you use when you are travelling."},{"pos":"PHRASE 短语","cn":"认真考虑并着手处理","en":"If you get to grips with a problem or if you come to grips with it, you consider it seriously, and start taking action to deal with it.","ex":{"en":"The government's first task is to get to grips with the economy.","cn":"政府的首要任务是处理好经济问题。"}},{"pos":"PHRASE 短语","cn":"（使自己）镇定下来；控制住（自己）","en":"If you get a grip on yourself, you make an effort to control or improve your behaviour or work."},{"pos":"PHRASE 短语","cn":"受制于；受…的深刻影响","en":"If a person, group, or place is in the grip of something, they are being severely affected by it.","ex":{"en":"Britain is still in the grip of recession.","cn":"英国依然没有摆脱经济衰退。"}},{"pos":"PHRASE 短语","cn":"效率降低；失去信心；驾驭不住","en":"If you lose your grip, you become less efficient and less confident, and less able to deal with things."},{"pos":"PHRASE 短语","cn":"了解形势；理解现状","en":"If you say that someone has a grip on reality, you mean they recognize the true situation and do not have mistaken ideas about it.","ex":{"en":"Shakur loses his fragile grip on reality and starts blasting away at friends and foe alike.","cn":"沙库尔丧失了对形势仅存的一点判断，无论对敌对友都开始大加挞伐。"}}]},"examples":[{"en":"These tyres give the bus better grip in slippery conditions.","cn":"这些轮胎可使公共汽车在路滑时行驶得平稳一些。"},{"en":"I have to take a grip on myself, he told himself firmly.","cn":"我一定要控制住自己的情绪，他坚定地对自己说。"}]},"grandmother":{"oxford":{"phon":"ˈɡrænmʌðə(r)","pos":"noun","senses":[{"en":"the mother of your father or mother","cn":"（外）祖母；奶奶；姥姥；外婆","ex":{"en":"I always loved going to visit my grandmother.","cn":"我总是喜欢去看望我的祖母。"}}]},"collins":{"senses":[{"pos":"N-FAMILY 家庭成员名词","cn":"（外）祖母；奶奶；外婆","en":"Your grandmother is the mother of your father or mother.","ex":{"en":"My grandmothers are both widows.","cn":"我奶奶和外婆都是孤寡一人。"}}]},"media":{"uk":"media/uk/grandmother__gb_1.mp3","us":"media/us/grandmother__us_1.mp3"},"examples":[{"en":"My grandma used to make lovely cakes.","cn":"我祖母以前常做很好吃的蛋糕。"}]},"grateful":{"oxford":{"phon":"ˈɡreɪtfl","pos":"adjective","senses":[{"en":"feeling or showing thanks because somebody has done something kind for you or has done as you asked","cn":"感激的；表示感谢的","ex":{"en":"Thank you for doing this. I really am so grateful.","cn":"谢谢你这样做。我实在是太感激了。"}},{"en":"used to make a request, especially in a letter or in a formal situation","cn":"（尤用于书信或正式场合提出请求）感激不尽，请","ex":{"en":"I would be grateful if you could send the completed form back as soon as possible.","cn":"如能尽快把表格填好寄回，将不胜感激。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感激的；表示感谢的","en":"If you are grateful for something that someone has given you or done for you, you have warm, friendly feelings towards them and wish to thank them.","ex":{"en":"She was grateful to him for being so good to her","cn":"他对她这么好，令她很感激。"}}]},"media":{"uk":"media/uk/grateful__gb_1.mp3","us":"media/us/grateful__us_1.mp3"},"examples":[{"en":"Grateful thanks are due to the following people for their help …","cn":"向下列给予过帮助的人表示衷心的感谢 …"},{"en":"She seems to think I should be grateful to have a job at all.","cn":"她似乎认为我有份工作就该谢天谢地了。"}]},"grapple":{"media":{"uk":"media/uk/grapple__gb_1.mp3","us":"media/us/grapple__us_1.mp3"},"oxford":{"phon":"ˈɡræpl","pos":"verb","senses":[{"en":"to take a strong hold of somebody/something and struggle with them","cn":"扭打；搏斗","g":"[intransitive, transitive]","ex":{"en":"Passers-by grappled with the man after the attack.","cn":"袭击之后过路人便与这男人扭打起来。"}},{"en":"to try hard to find a solution to a problem","cn":"努力设法解决","g":"[intransitive]","ex":{"en":"The new government has yet to grapple with the problem of air pollution.","cn":"新政府还需尽力解决空气污染问题。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"努力解决（问题）；设法克服（困难）","en":"If you grapple with a problem or difficulty, you try hard to solve it.","ex":{"en":"The economy is just one of several critical problems the country is grappling with.","cn":"经济问题只是该国正竭力解决的几个关键问题之一。"}},{"pos":"V-RECIP 相互动词","cn":"扭打;搏斗","en":"If you grapple with someone, you take hold of them and struggle with them, as part of a fight. You can also say that two people grapple .","ex":{"en":"He was grappling with an alligator in a lagoon","cn":"他正在环礁湖里与一只短吻鳄搏斗。"}}]},"examples":[{"en":"Passers-by grappled with the man after the attack.","cn":"袭击之后过路人便与这男人扭打起来。"},{"en":"The new government has yet to grapple with the problem of air pollution.","cn":"新政府还需尽力解决空气污染问题。"}]},"groom":{"media":{"uk":"media/uk/groom__gb_1.mp3","us":"media/us/groom__us_1.mp3"},"oxford":{"phon":"ɡruːm","pos":"verb","senses":[{"en":"to clean or brush an animal","cn":"（给动物）擦洗，刷洗","ex":{"en":"to groom a horse/dog/cat","cn":"刷洗马／狗／猫"}},{"en":"to clean the fur or skin of another animal or itself","cn":"（给自己或其他动物）理毛，梳毛","ex":{"en":"a female ape grooming her mate","cn":"为同伴梳毛的母猿"}},{"en":"to prepare or train somebody for an important job or position","cn":"使做好准备；培养；训练","ex":{"en":"Our junior employees are being groomed for more senior roles.","cn":"我们的初级雇员正在接受培训以承担更重要的职责。"}},{"en":"to prepare a child for a meeting, especially using social media, with the intention of performing an illegal sexual act","cn":"（尤指利用网络社交媒体）勾引（儿童）"},{"en":"a person whose job is to feed and take care of horses, especially by brushing and cleaning them","cn":"马夫；马倌；马匹饲养员","pos":"noun"},{"en":"a man on his wedding day, or just before or just after it","cn":"新郎；即将（或刚刚）结婚的男子","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同bridegroom","en":"A groom is the same as a bridegroom .","ex":{"en":"...the bride and groom.","cn":"新娘与新郎"}},{"pos":"N-COUNT 可数名词","cn":"马夫；马倌","en":"A groom is someone whose job is to look after the horses in a stable and to keep them clean."},{"pos":"VERB 动词","cn":"洗刷（动物）；给（动物）梳毛","en":"If you groom an animal, you clean its fur, usually by brushing it.","ex":{"en":"The horses were exercised and groomed with special care.","cn":"这些马接受专门训练，鬃毛也得到精心梳理。"}},{"pos":"VERB 动词","cn":"训练；培养","en":"If you are groomed for a special job, someone prepares you for it by teaching you the skills you will need.","ex":{"en":"George was already being groomed for the top job","cn":"为承担这份高级工作，乔治已在接受专门的培训。"}}]},"examples":[{"en":"Our junior employees are being groomed for more senior roles.","cn":"我们的初级雇员正在接受培训以承担更重要的职责。"},{"en":"The eldest son is being groomed to take over when his father dies.","cn":"长子正在接受培养，以在父亲过世后接手父业。"}]},"graduated":{"media":{"img":["media/pic/laboratory_equipment_comp.jpg","media/thumb/graduatedcylinder.jpg"],"uk":"media/uk/graduated__gb_1.mp3","us":"media/us/graduated__us_1.mp3"},"oxford":{"phon":"ˈɡrædʒueɪtɪd","pos":"adjective","senses":[{"en":"divided into groups or levels on a scale","cn":"分等级的；分层次的","ex":{"en":"graduated lessons/tests","cn":"分级课程／测验"}},{"en":"marked with lines to show measurements","cn":"标有刻度的","ex":{"en":"a graduated jar","cn":"标有刻度的广口瓶"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"递增的；递进的","en":"Graduated means increasing by regular amounts or grades.","ex":{"en":"The US military wants to avoid the graduated escalation that marked the Vietnam War.","cn":"美国军方希望避免出现类似于越南战争那样逐步升级的态势。"}},{"pos":"ADJ 形容词","cn":"（广口瓶等）标有刻度的","en":"Graduated jars are marked with lines and numbers which show particular measurements.","ex":{"en":"...a graduated tube marked in millimetres.","cn":"以毫米标注刻度的试管"}}]},"examples":[{"en":"a graduated jar","cn":"标有刻度的广口瓶"},{"en":"graduated lessons/tests","cn":"分级教程/测验"}]},"gram":{"oxford":{"phon":"ɡræm","pos":"noun","senses":[{"en":"a unit for measuring weight. There are 1 000 grams in one kilogram.","cn":"克（重量单位，等于 0.001 千克）","lab":"also British English, less frequent，，"},{"en":"a thing that is written or drawn","cn":"写（或画）的东西","ex":{"en":"telegram","cn":"电报"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"克（重量单位）","en":"A gram is a unit of weight. One thousand grams are equal to one kilogram.","ex":{"en":"A football weighs about 400 grams.","cn":"足球重约400克。"}}]},"media":{"uk":"media/uk/gram__gb_1.mp3","us":"media/us/gram__us_1.mp3"},"examples":[{"en":"hologram","cn":"全息图"},{"en":"telegram","cn":"电报"}]},"greeting":{"media":{"uk":"media/uk/greeting__gb_1.mp3","us":"media/us/greeting__us_1.mp3"},"oxford":{"phon":"ˈɡriːtɪŋ","pos":"noun","senses":[{"en":"something that you say or do to greet somebody","cn":"问候；招呼；迎接；致意","g":"[countable, uncountable]","ex":{"en":"She waved a friendly greeting.","cn":"她友好地挥手致意。"}},{"en":"a message of good wishes for somebody’s health, happiness, etc.","cn":"问候的话；祝词；贺词","g":"[plural]","ex":{"en":"Christmas/birthday, etc. greetings","cn":"圣诞、生日等祝词"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"问候；招呼；致意","en":"A greeting is something friendly that you say or do when you meet someone.","ex":{"en":"His greeting was familiar and friendly","cn":"他的问候让人觉得随意又亲切。"}},{"pos":"CONVENTION 惯用语","cn":"（旧时的）祝词，贺词，问候语","en":"'Greetings' is an old-fashioned greeting."}]},"examples":[{"en":"They exchanged greetings and sat down to lunch.","cn":"他们相互致意后便坐下吃午饭。"},{"en":"My mother sends her greetings to you all.","cn":"我母亲向你们各位问好。"}]},"grow":{"media":{"uk":"media/uk/grow__gb_1.mp3","us":"media/us/grow__us_1.mp3"},"oxford":{"phon":"ɡrəʊ","pos":"verb","senses":[{"en":"to increase in size, number, strength or quality","cn":"扩大；增加；增强","g":"[intransitive]","sc":"increase","ex":{"en":"The sector is growing at a phenomenal rate.","cn":"该行业正在以惊人的速度增长。"}},{"en":"to become bigger or taller and develop into an adult","cn":"长大；长高；发育；成长","g":"[intransitive]","sc":"of person/animal","ex":{"en":"You've grown since the last time I saw you!","cn":"自从我上次见到你后，你又见长了！"}},{"en":"to exist and develop in a particular place; to make plants grow","cn":"（使）生长，发育","g":"[intransitive, transitive]","sc":"of plant","ex":{"en":"The region is too dry for plants to grow.","cn":"这地区干旱得草木不生。"}},{"en":"to become longer; to allow something to become longer by not cutting it","cn":"（使）留长，蓄长","g":"[intransitive, transitive]","sc":"of hair/nails","ex":{"en":"I've decided to let my hair grow.","cn":"我已决定留长发。"}},{"en":"to begin to have a particular quality or feeling over a period of time","cn":"逐渐变得；逐渐成为","sc":"become/begin","ex":{"en":"He had grown old and fat.","cn":"他年纪大了，也胖了。"}},{"en":"to gradually begin to do something","cn":"逐渐开始","g":"[intransitive]","sc":"become/begin","ex":{"en":"I'm sure you'll grow to like her in time.","cn":"我肯定你慢慢就会喜欢她了。"}},{"en":"to develop and improve particular qualities or skills","cn":"提升品质；培养技能","g":"[intransitive]","sc":"develop skills","ex":{"en":"She continues to grow as an artist.","cn":"她作为艺术家不断有所提高。"}},{"en":"to increase the size, quality or number of something","cn":"扩大；扩展；增加","g":"[transitive]","sc":"business","ex":{"en":"We are trying to grow the business.","cn":"我们正在努力扩展业务。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"生长；长大；发育","en":"When people, animals, and plants grow, they increase in size and change physically over a period of time.","ex":{"en":"We stop growing at maturity.","cn":"我们成年之后不再长个儿。"}},{"pos":"VERB 动词","cn":"成活；生长","en":"If a plant or tree grows in a particular place, it is alive there.","ex":{"en":"The station had roses growing at each end of the platform.","cn":"车站月台的两头种着玫瑰花。"}},{"pos":"VERB 动词","cn":"栽种；种植","en":"If you grow a particular type of plant, you put seeds or young plants in the ground and look after them as they develop.","ex":{"en":"I always grow a few red onions","cn":"我总是喜欢种一些红洋葱。"}},{"pos":"VERB 动词","cn":"（毛发、指甲等）变长","en":"When someone's hair grows, it gradually becomes longer. Your nails also grow.","ex":{"en":"Then the hair began to grow again and I felt terrific.","cn":"然后，头发又长起来了，我感觉棒极了。"}},{"pos":"VERB 动词","cn":"留长（头发或指甲）；蓄（胡须）","en":"If someone grows their hair, or grows a beard or moustache, they stop cutting their hair or shaving so that their hair becomes longer. You can also grow your nails.","ex":{"en":"I'd better start growing my hair.","cn":"我最好开始留头发。"}},{"pos":"VERB 动词","cn":"成长；长大；成熟","en":"If someone grows mentally, they change and develop in character or attitude.","ex":{"en":"They began to grow as persons.","cn":"他们开始长大成人了。"}},{"pos":"V-LINK 连系动词","cn":"变得；变成；长成","en":"You use grow to say that someone or something gradually changes until they have a new quality, feeling, or attitude.","ex":{"en":"I grew a little afraid of the guy next door","cn":"我开始有些害怕隔壁的那个家伙。"}},{"pos":"VERB 动词","cn":"增加；增强；增大","en":"If an amount, feeling, or problem grows, it becomes greater or more intense.","ex":{"en":"The number of unemployed people in Poland has grown by more than a quarter in the last month","cn":"上个月，波兰的失业人数增长超过了1/4。"}},{"pos":"VERB 动词","cn":"成长为；发展为","en":"If one thing grows into another, it develops or changes until it becomes that thing.","ex":{"en":"The boys grew into men","cn":"这些男孩子长成了男子汉。"}},{"pos":"VERB 动词","cn":"（观点、计划等）产生于，源于","en":"If something such as an idea or a plan grows out of something else, it develops from it.","ex":{"en":"The idea for this book grew out of conversations with Philippa Brewster.","cn":"创作这本书的想法来源于跟菲莉帕·布鲁斯特的谈话。"}},{"pos":"VERB 动词","cn":"（经济或公司）增长，扩大，发展","en":"If the economy or a business grows, it increases in wealth, size, or importance.","ex":{"en":"The economy continues to grow.","cn":"经济持续发展。"}},{"pos":"VERB 动词","cn":"扩大，壮大，发展（公司等）","en":"If someone grows a business, they take actions that will cause it to increase in wealth, size, or importance.","ex":{"en":"To grow the business, he needs to develop management expertise and innovation across his team.","cn":"为了拓展业务，他需要提高整个团队的管理技能和创新能力。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（晶体）产生；使（晶体）形成","en":"If a crystal grows, or if a scientist grows it, it forms from a solution.","ex":{"en":"...crystals that grow in cavities in the rock","cn":"岩石洞穴中形成的水晶"}},{"pos":"","cn":"","en":"相关词组：grow apart grow away from grow into grow on grow out grow out of grow up"}]},"examples":[{"en":"The dress is too long for her now but she'll grow into it.","cn":"这件连衣裙她现在穿太长，不过她长大了可以穿。"},{"en":"Fears are growing for the safety of a teenager who disappeared a week ago.","cn":"大家对那一周前失踪少年的安危越来越担忧。"}]},"grammatical":{"oxford":{"phon":"ɡrəˈmætɪkl","pos":"adjective","senses":[{"en":"connected with the rules of grammar","cn":"语法的；文法的","ex":{"en":"a grammatical error","cn":"语法错误"}},{"en":"correctly following the rules of grammar","cn":"符合语法规则的；合乎文法的","ex":{"en":"That sentence is not grammatical.","cn":"那个句子不合语法。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"语法的；文法的","en":"Grammatical is used to indicate that something relates to grammar.","ex":{"en":"Should the teacher present grammatical rules to students?","cn":"老师是否应该给学生讲授语法规则？"}},{"pos":"ADJ 形容词","cn":"符合语法规则的；符合文法的","en":"If someone's language is grammatical, it is considered correct because it obeys the rules of grammar.","ex":{"en":"...a new test to determine whether students can write grammatical English.","cn":"考查学生是否能用符合语法规则的英语进行写作的新型考试"}}]},"media":{"uk":"media/uk/grammatical__gb_1.mp3","us":"media/us/grammatical__us_1.mp3"},"examples":[{"en":"That sentence is not grammatical.","cn":"那个句子不合语法。"},{"en":"a grammatically correct sentence","cn":"语法上正确的句子"}]},"grilling":{"oxford":{"phon":"ˈɡrɪlɪŋ","pos":"noun","senses":[{"en":"a period of being questioned closely about your ideas, actions, etc.","cn":"盘问，责问，审问（的一段时间）","ex":{"en":"The minister faced a tough grilling at today's press conference.","cn":"部长在今天的记者招待会上受到了严厉的盘问。"}}]},"media":{"uk":"media/uk/grilling__gb_1.mp3","us":"media/us/grilling__us_1.mp3"},"examples":[{"en":"The minister faced a tough grilling at today's press conference.","cn":"部长在今天的记者招待会上受到了严厉的盘问。"},{"en":"The three party leaders each endured a 20-minute television grilling from voters.","cn":"三名政党领导人各在电视上接受了选民二十分钟的提问。"}]},"gravity":{"media":{"uk":"media/uk/gravity__gb_1.mp3","us":"media/us/gravity__us_1.mp3"},"oxford":{"phon":"ˈɡrævəti","pos":"noun","senses":[{"en":"the force that attracts objects in space towards each other, and that on the earth pulls them towards the centre of the planet, so that things fall to the ground when they are dropped","cn":"重力；地球引力","ex":{"en":"Newton’s law of gravity","cn":"牛顿万有引力定律"}},{"en":"extreme importance and a cause for worry","cn":"严重性","lab":"formal","ex":{"en":"I don't think you realise the gravity of the situation.","cn":"我认为你没有意识到形势的严重性。"}},{"en":"serious behaviour, speech or appearance","cn":"严肃；庄严","lab":"formal","ex":{"en":"They were asked to behave with the gravity that was appropriate in a court of law.","cn":"他们被要求在法庭上表现出应有的严肃态度。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"重力；地球引力","en":"Gravity is the force which causes things to drop to the ground.","ex":{"en":"Arrows would continue to fly forward forever in a straight line were it not for gravity, which brings them down to earth.","cn":"要不是重力使箭落向地面，它们将永远以直线往前飞行。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（事态的）严重性，重大","en":"The gravity of a situation or event is its extreme importance or seriousness.","ex":{"en":"They deserve punishment which matches the gravity of their crime","cn":"应当根据罪行的严重性来惩治他们。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（言谈举止的）庄重，严肃","en":"The gravity of someone's behaviour or speech is the extremely serious way in which they behave or speak.","ex":{"en":"There was an appealing gravity to everything she said.","cn":"她说的每句话都带着一种庄严，很能吸引人。"}}]},"examples":[{"en":"They were asked to behave with the gravity that was appropriate in a court of law.","cn":"他们被要求在法庭上表现出应有的严肃态度。"},{"en":"Punishment varies according to the gravity of the offence.","cn":"处罚根据罪行的严重程度而有所不同。"}]},"grounded":{"media":{"uk":"media/uk/grounded__gb_1.mp3","us":"media/us/grounded__us_1.mp3"},"oxford":{"phon":"ˈɡraʊndɪd","pos":"adjective","senses":[{"en":"having a sensible and realistic attitude to life","cn":"（对生活）持有理智和现实态度的","ex":{"en":"Away from Hollywood, he relies on his family and friends to keep him grounded.","cn":"离开好莱坞之后，他靠家人和朋友使自己保持心态平衡。"}}]},"collins":{"senses":[{"pos":"","cn":"头脑清醒的；理智的；脚踏实地的","en":"If you say that someone is grounded, you mean that they are sensible and reasonable, and that they understand the importance of ordinary things in life.","ex":{"en":"Family and old friends help me stay grounded.","cn":"是家人和老友帮助我始终做到脚踏实地。"}}]},"examples":[{"en":"Away from Hollywood, he relies on his family and friends to keep him grounded.","cn":"离开好莱坞之后，他靠家人和朋友使自己保持心态平衡。"},{"en":"His views are grounded on the assumption that all people are equal.","cn":"他的观点建立在人人平等的假设之上。"}]},"greenfield":{"oxford":{"phon":"ˈɡriːnfiːld","pos":"adjective","senses":[{"en":"used to describe an area of land that has not yet had buildings on it, but for which building development may be planned","cn":"未开发地区的；地产发展规划区的；绿色开发区的","ex":{"en":"a greenfield site","cn":"待开发区"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未开发地区的；待开发地区的","en":"Greenfield is used to refer to land that has not been built on before.","ex":{"en":"The Government has ruled out the building of a new airport on a greenfield site.","cn":"政府禁止在一块未开发地皮上建设新机场的。"}}]},"media":{"uk":"media/uk/greenfield__gb_1.mp3","us":"media/us/greenfield__us_1.mp3"},"examples":[{"en":"a greenfield site","cn":"绿色开发区"}]},"greek":{"media":{"uk":"media/uk/greek__gb_1.mp3","us":"media/us/greek__us_1.mp3"},"oxford":{"phon":"ɡriːk","pos":"noun","senses":[{"en":"a person from modern or ancient Greece","cn":"希腊人；古希腊人","g":"[countable]"},{"en":"the language of modern or ancient Greece","cn":"希腊语","g":"[uncountable]"},{"en":"a member of a fraternity or a sorority at a college or university","cn":"（大学的）学生联谊会会员，女生联谊会会员","g":"[countable]","lab":"North American English"},{"en":"of or connected with Greece, its people or their language","cn":"希腊的；希腊人的；希腊语的","pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"希腊的","en":"Greek means belonging or relating to Greece.","ex":{"en":"In the Greek general election, the New Democracy party has claimed victory.","cn":"新民主党在希腊大选中获胜。"}},{"pos":"N-COUNT 可数名词","cn":"希腊人","en":"A Greek is a person who comes from Greece.","ex":{"en":"He had looked through the house for the two Greeks.","cn":"他搜遍了整个房子想要找到那两个希腊人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"希腊语","en":"Greek is the language used in Greece.","ex":{"en":"I had to learn Greek.","cn":"我不得不学习希腊语。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"古希腊语","en":"Greek or Ancient Greek was the language used in Greece in ancient times.","ex":{"en":"Teachers warn today that Latin, Greek and other classics will be squeezed out of school timetables.","cn":"老师们今天发出警告说，拉丁语、古希腊语和其他古典文学将被挤出学校的课程表。"}}]},"examples":[{"en":"She tried to explain how the system works, but it's all Greek to me.","cn":"她努力解释系统如何运作，可我就是怎么也弄不明白。"},{"en":"Greek yoghurt","cn":"希腊酸奶"}]},"gradually":{"media":{"uk":"media/uk/gradually__gb_1.mp3","us":"media/us/gradually__us_1.mp3"},"oxford":{"phon":"ˈɡrædʒuəli","pos":"adverb","senses":[{"en":"slowly, over a long period of time","cn":"逐渐地；逐步地；渐进地","ex":{"en":"to gradually increase/decrease","cn":"逐渐增加／减少"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"逐渐地；逐步地","en":"If something changes or is done gradually, it changes or is done in small stages over a long period of time, rather than suddenly.","ex":{"en":"Electricity lines to 30,000 homes were gradually being restored yesterday","cn":"昨天，3万户家庭逐渐恢复了供电。"}}]},"examples":[{"en":"Gradually, the children began to understand.","cn":"孩子们渐渐开始明白。"},{"en":"The weather gradually improved.","cn":"天气逐渐好转。"}]},"grinding":{"media":{"uk":"media/uk/grinding__gb_1.mp3","us":"media/us/grinding__us_1.mp3"},"oxford":{"phon":"ˈɡraɪndɪŋ","pos":"adjective","senses":[{"en":"that never ends or improves","cn":"没完没了的；无休止的；无改进的","ex":{"en":"grinding poverty","cn":"贫困不堪"}},{"en":"rough and unpleasant to listen to","cn":"刺耳的；难听的","ex":{"en":"I heard a loud grinding noise coming from the engine.","cn":"我听到发动机发出巨大的摩擦声。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没完没了的；无休止的；毫无起色的","en":"If you describe a bad situation as grinding, you mean it never gets better, changes, or ends.","ex":{"en":"Their grandfather had left his village in order to escape the grinding poverty.","cn":"为了摆脱贫困的煎熬，他们的祖父离开了村子。"}},{"pos":"PHRASE 短语","cn":"突然停顿下来","en":"If you say that something comes to a grinding halt, you are emphasizing that it stops very suddenly, especially before it was meant to.","ex":{"en":"A car will come to a grinding halt if you put water in the petrol tank.","cn":"如果把水灌进油箱，汽车会猛然间停下来。"}}]},"examples":[{"en":"grinding poverty","cn":"贫困不堪"},{"en":"a country devastated by civil war and grinding poverty","cn":"一个被内战和极度贫困压垮的国家"}]},"grid":{"oxford":{"phon":"ɡrɪd","pos":"noun","senses":[{"en":"a pattern of straight lines, usually crossing each other to form squares","cn":"网格；方格","ex":{"en":"New York’s grid of streets","cn":"纽约棋盘式的街道布局"}},{"en":"a frame of metal or wooden bars that are parallel or cross each other","cn":"（金属或木制的）格子，格栅，栅栏"},{"en":"a pattern of squares on a map that are marked with letters or numbers to help you find the exact position of a place","cn":"（地图上的）坐标方格","ex":{"en":"The grid reference is C8.","cn":"地图上的坐标方格数字为 C8。"}},{"en":"a system of electric wires or pipes carrying gas, for sending power over a large area","cn":"（输电线路、天然气管道的）系统网络；输电网；煤气输送网","lab":"especially British English","ex":{"en":"the national grid (= the electricity supply in a country)","cn":"国家输电网"}},{"en":"a pattern of lines marking the starting positions for the racing cars","cn":"赛车起跑线","ex":{"en":"The 20-year-old didn't get the best of starts off the grid.","cn":"这位20岁的选手在比赛中并没有取得最好的开局。"}},{"en":"a number of computers that are linked together using the internet so that they can share power, data, etc. in order to work on difficult problems","cn":"（利用互联网的）联网，联机","g":"[singular]","lab":"computing"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"网格；（地图上的）坐标方格","en":"A grid is something which is in a pattern of straight lines that cross over each other, forming squares. On maps the grid is used to help you find a particular thing or place.","ex":{"en":"...a grid of ironwork.","cn":"铁格栅"}},{"pos":"N-COUNT 可数名词","cn":"（输送电力等的）系统网络","en":"A grid is a network of wires and cables by which sources of power, such as electricity, are distributed throughout a country or area.","ex":{"en":"...breakdowns in communications and electric power grids.","cn":"通信系统与输电网的中断"}},{"pos":"N-COUNT 可数名词","cn":"赛车起跑线","en":"The grid or the starting grid is the starting line on a car-racing track.","ex":{"en":"The Ferrari of Alain Prost will be second on the grid.","cn":"阿兰·普罗斯特的法拉利赛车将排在起跑线的第二位。"}}]},"media":{"uk":"media/uk/grid__gb_1.mp3","us":"media/us/grid__us_1.mp3"},"examples":[{"en":"The mountain cabin is entirely off the grid.","cn":"这山中小屋完全不用水电等公共设施。"},{"en":"The grid reference is C8.","cn":"地图上的坐标方格数字为 C8。"}]},"grammar":{"media":{"uk":"media/uk/grammar__gb_1.mp3","us":"media/us/grammar__us_1.mp3"},"oxford":{"phon":"ˈɡræmə(r)","pos":"noun","senses":[{"en":"the rules in a language for changing the form of words and joining them into sentences","cn":"语法；文法","g":"[uncountable]","ex":{"en":"the basic rules of grammar","cn":"基本语法规则"}},{"en":"a person’s knowledge and use of a language","cn":"（人的）语言知识及运用能力","g":"[uncountable]","ex":{"en":"His grammar is appalling.","cn":"他运用语言的能力糟透了。"}},{"en":"a book containing a description of the rules of a language","cn":"语法书","g":"[countable]","ex":{"en":"a French grammar","cn":"法语语法书"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"语法;文法","en":"Grammar is the ways that words can be put together in order to make sentences.","ex":{"en":"He doesn't have mastery of the basic rules of grammar.","cn":"他还没有掌握基本的语法规则。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"文法；语言的运用","en":"Someone's grammar is the way in which they obey or do not obey the rules of grammar when they write or speak.","ex":{"en":"His vocabulary was sound and his grammar excellent.","cn":"他的词汇丰富，语法也很精通。"}},{"pos":"N-COUNT 可数名词","cn":"语法书","en":"A grammar is a book that describes the rules of a language.","ex":{"en":"...an advanced English grammar.","cn":"高阶英语语法书"}},{"pos":"N-VAR 可变名词","cn":"语法理论；语法学","en":"A particular grammar is a particular theory that is intended to explain the rules of a language.","ex":{"en":"Transformational grammars are more restrictive.","cn":"转换生成语法局限性更大。"}}]},"examples":[{"en":"His grammar is appalling.","cn":"他运用语言的能力糟透了。"},{"en":"bad grammar","cn":"极差的语言运用能力"}]},"graded":{"oxford":{"phon":"ˈɡreɪdɪd","pos":"adjective","senses":[{"en":"arranged in order or in groups according to difficulty, size, etc.","cn":"（按难度、大小等）分级的","ex":{"en":"graded tests for language students","cn":"语言学习者的分级测验"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（动词或副词）有程度之分的，分级的","en":"In this dictionary, a graded adjective or adverb is one which is sometimes used with an adverb or phrase indicating degree. 'Clever' is an example of a graded adjective."}]},"media":{"uk":"media/uk/graded__gb_1.mp3","us":"media/us/graded__us_1.mp3"},"examples":[{"en":"graded tests for language students","cn":"语言学习者的分级测验"},{"en":"graded doses of a drug","cn":"药物的分级剂量"}]},"gravely":{"oxford":{"phon":"ˈɡreɪvli","pos":"adverb","senses":[{"en":"in a very serious and important way; in a way that gives you a reason to feel worried","cn":"严重的；重大的；严峻的；深切的","ex":{"en":"She is gravely ill.","cn":"她病得很重。"}},{"en":"in a way that is serious in manner, as if something sad or important has just happened","cn":"严肃的；庄严的；表情沉重的","ex":{"en":"He nodded gravely as I poured out my troubles.","cn":"我倾诉烦恼时，他神情肃穆地不断点头。"}}]},"media":{"uk":"media/uk/gravely__gb_1.mp3","us":"media/us/gravely__us_1.mp3"},"examples":[{"en":"He nodded gravely as I poured out my troubles.","cn":"我倾诉我的苦恼时他心情沉重地点了点头。"},{"en":"Local people are gravely concerned.","cn":"当地人都深感不安。"}]},"granting":{"oxford":{"phon":"ɡrɑːnt","pos":"verb","senses":[{"en":"to agree to give sb what they ask for, especially formal or legal permission to do sth （","cn":"尤指正式地或法律上）同意，准予，允许"},{"en":"to admit that sth is true, although you may not like or agree with it （","cn":"勉强）承认，同意"}]}},"grain":{"media":{"uk":"media/uk/grain__gb_1.mp3","us":"media/us/grain__us_1.mp3"},"oxford":{"phon":"ɡreɪn","pos":"noun","senses":[{"en":"the small hard seeds of food plants such as wheat, rice, etc.; a single seed of such a plant","cn":"谷物；谷粒","g":"[uncountable, countable]","ex":{"en":"Russia sold 12 million tons of grain abroad last year.","cn":"俄罗斯去年出口粮食 1 200 万吨。"}},{"en":"a small hard piece of particular substances","cn":"颗粒；细粒","g":"[countable]","ex":{"en":"a grain of salt/sand/sugar","cn":"一粒盐／沙／砂糖"}},{"en":"a very small amount","cn":"少量；微量；一点儿","g":"[countable]","ex":{"en":"There isn't a grain of truth in those rumours.","cn":"那些谣传一点也不可靠。"}},{"en":"a small unit of weight, equal to 0.00143 of a pound or 0.0648 of a gram, used for example for weighing medicines","cn":"格令（重量单位，等于 0.00143 磅或 0.0648 克，用于称量药物等）","g":"[countable]","ex":{"en":"The analysis showed a few grains of arsenic in the solution.","cn":"分析显示溶液中有几格令的砷。"}},{"en":"the natural direction of lines in wood, cloth, etc. or of layers of rock; the pattern of lines that you can see","cn":"（木、织物或石头等的）纹理","g":"[uncountable, singular]","ex":{"en":"to cut a piece of wood along/across the grain","cn":"顺着纹路劈木头；横对纹路把木头拦腰截断"}},{"en":"how rough or smooth a surface feels","cn":"（表面的）质地；触感","g":"[uncountable, countable]","ex":{"en":"wood of coarse/fine grain","cn":"质地粗／细的木头"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"谷粒","en":"A grain of wheat, rice, or other cereal crop is a seed from it.","ex":{"en":"...a grain of wheat.","cn":"一粒小麦"}},{"pos":"N-MASS 物质名词","cn":"谷物（尤指小麦或玉米）","en":"Grain is a cereal crop, especially wheat or corn, that has been harvested and is used for food or in trade.","ex":{"en":"...a bag of grain.","cn":"一袋谷物"}},{"pos":"N-COUNT 可数名词","cn":"细粒;微粒;小颗粒","en":"A grain of something such as sand or salt is a tiny hard piece of it.","ex":{"en":"...a grain of sand.","cn":"一粒沙子"}},{"pos":"N-SING 单数名词","cn":"一点；些微","en":"A grain of a quality is a very small amount of it.","ex":{"en":"There's more than a grain of truth in that.","cn":"其中含有很深刻的道理。"}},{"pos":"N-SING 单数名词","cn":"（木材表面的）纹理，纹路","en":"The grain of a piece of wood is the direction of its fibres. You can also refer to the pattern of lines on the surface of the wood as the grain.","ex":{"en":"Brush the paint generously over the wood in the direction of the grain.","cn":"顺着木材的纹理刷上厚厚的一层漆。"}},{"pos":"PHRASE 短语","cn":"违背本来的原则；与…格格不入","en":"If you say that an idea or action goes against the grain, you mean that it is very difficult for you to accept it or do it, because it conflicts with your previous ideas, beliefs, or principles.","ex":{"en":"Privatisation goes against the grain of their principle of opposition to private ownership of industry.","cn":"私有化有悖于他们反对工业私有的原则。"}}]},"examples":[{"en":"to cut a piece of wood along/across the grain","cn":"顺着纹路劈木头；横对纹路把木头拦腰截断"},{"en":"It really goes against the grain to have to work on a Sunday.","cn":"星期天还得上班的确不合常情。"}]},"grows":{"oxford":{"phon":"ɡrəʊ","pos":"verb","senses":[{"en":"to increase in size, number, strength or quality","cn":"扩大；增加；增强"},{"en":"to become bigger or taller and develop into an adult","cn":"长大；长高；发育；成长"}]},"media":{"uk":"media/uk/grow__gb_1.mp3","us":"media/us/grow__us_1.mp3"}},"grapes":{"oxford":{"phon":"ɡreɪp","pos":"noun","senses":[{"en":"a small green or purple fruit that grows in bunches on a climbing plant (called a vine ). Wine is made from grapes.","cn":"葡萄"}]},"media":{"img":["media/ldoce/img/grapes.jpg","media/pic/fruit_comp.jpg"],"uk":"media/uk/grape__gb_1.mp3","us":"media/us/grape__us_1.mp3"}},"greatly":{"media":{"uk":"media/uk/greatly__gb_1.mp3","us":"media/us/greatly__us_1.mp3"},"oxford":{"phon":"ˈɡreɪtli","pos":"adverb","senses":[{"en":"very much","cn":"非常；很","ex":{"en":"People's reaction to the film has varied greatly.","cn":"人们对这部影片的反应大不一样。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"非常地；极大地","en":"You use greatly to emphasize the degree or extent of something.","ex":{"en":"People would benefit greatly from a pollution-free vehicle","cn":"人们将享受到无污染汽车的诸多好处。"}}]},"examples":[{"en":"People's reaction to the film has varied greatly.","cn":"人们对这部影片的反应大不一样。"},{"en":"Your help would be greatly appreciated.","cn":"如蒙帮助，感激不尽。"}]},"greedy":{"media":{"uk":"media/uk/greedy__gb_1.mp3","us":"media/us/greedy__us_1.mp3"},"oxford":{"phon":"ˈɡriːdi","pos":"adjective","senses":[{"en":"wanting more money, power, food, etc. than you really need","cn":"贪婪的；贪心的；贪吃的","ex":{"en":"You greedy pig! You've already had two helpings!","cn":"你这个馋嘴！你已经吃了两份了！"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"贪婪的；贪心的；贪吃的","en":"If you describe someone as greedy, you mean that they want to have more of something such as food or money than is necessary or fair.","ex":{"en":"He attacked greedy bosses for awarding themselves big rises","cn":"他抨击那些贪心的老板为他们自己大幅加薪。"}}]},"examples":[{"en":"You greedy pig! You've already had two helpings!","cn":"你这个馋嘴！你已经吃了两份了！"},{"en":"He stared at the diamonds with greedy eyes.","cn":"他眼巴巴地盯着这些钻石。"}]},"granite":{"media":{"uk":"media/uk/granite__gb_1.mp3","us":"media/us/granite__us_1.mp3"},"oxford":{"phon":"ˈɡrænɪt","pos":"noun","senses":[{"en":"a type of hard grey stone, often used in building","cn":"花岗岩；花岗石"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"花岗石；花岗岩","en":"Granite is a very hard rock used in building."}]}},"grind":{"media":{"uk":"media/uk/grind__gb_1.mp3","us":"media/us/grind__us_1.mp3"},"oxford":{"phon":"ɡraɪnd","pos":"verb","senses":[{"en":"to break or press something into very small pieces between two hard surfaces or using a special machine","cn":"磨碎；碾碎；把…磨成粉","g":"[transitive]","sc":"food/flour/coffee","ex":{"en":"to grind coffee/corn","cn":"将咖啡／谷粒磨成粉"}},{"en":"to produce something such as flour by grinding","cn":"磨（粉）","g":"[transitive]","sc":"food/flour/coffee","ex":{"en":"The flour is ground using traditional methods.","cn":"这面粉是用传统方法磨制而成。"}},{"en":"to cut food, especially meat, into very small pieces using a special machine (called a mincer)","cn":"用绞肉机绞（食物，尤指肉）","g":"[transitive]","lab":"North American English","sc":"food/flour/coffee"},{"en":"to make something sharp or smooth by rubbing it against a hard surface","cn":"使锋利；磨快；磨光","g":"[transitive]","sc":"make sharp/smooth","ex":{"en":"a special stone for grinding knives","cn":"专门磨刀用的石头"}},{"en":"to press or rub something into a surface","cn":"用力挤压，用力擦（入表层）","g":"[transitive]","sc":"press into surface","ex":{"en":"He ground his cigarette into the ashtray.","cn":"他把香烟按在烟灰缸里捻灭。"}},{"en":"to rub together, or to make hard objects rub together, often producing an unpleasant noise","cn":"摩擦（发出刺耳声）","g":"[intransitive, transitive]","sc":"rub together","ex":{"en":"Parts of the machine were grinding together noisily.","cn":"机器零件摩擦发出刺耳的声音。"}},{"en":"to turn the handle of a machine that grinds something","cn":"摇动手柄（操纵压磨机器）","g":"[transitive]","sc":"machine","ex":{"en":"to grind a pepper mill","cn":"摇动胡椒磨"}},{"en":"an activity that is boring or makes you tired and takes a lot of time","cn":"令人疲劳（或厌倦）的工作；苦差事","g":"[singular]","lab":"informal","sc":"boring activity","ex":{"en":"the daily grind of family life","cn":"家庭生活中烦琐的家务劳动"},"pos":"noun"},{"en":"the unpleasant noise made by machines","cn":"刺耳的摩擦声","g":"[singular]","sc":"of machines","pos":"noun"},{"en":"a person who spends too much time studying","cn":"只知一味用功学习的人；书呆子","g":"[countable]","lab":"US English","sc":"swot","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"磨碎；碾碎； 将…磨成粉","en":"If you grind a substance such as corn, you crush it between two hard surfaces or with a machine until it becomes a fine powder.","ex":{"en":"Store the peppercorns in an airtight container and grind the pepper as you need it.","cn":"将胡椒粒储存在密封容器中，在需要的时候磨成粉。"}},{"pos":"VERB 动词","cn":"用力挤压；用劲擦","en":"If you grind something into a surface, you press and rub it hard into the surface using small circular or sideways movements.","ex":{"en":"'Well,' I said, grinding my cigarette nervously into the granite step.","cn":"“好吧，”我边说边紧张不安地把香烟在花岗岩台阶上捻灭。"}},{"pos":"VERB 动词","cn":"把…磨锋利；把…磨快；把…磨光","en":"If you grind something, you make it smooth or sharp by rubbing it against a hard surface.","ex":{"en":"...a shop where they grind knives","cn":"磨刀铺"}},{"pos":"VERB 动词","cn":"刺耳地缓慢移动","en":"If a vehicle grinds somewhere, it moves there very slowly and noisily.","ex":{"en":"Tanks had crossed the border at five fifteen and were grinding south.","cn":"坦克队于5点15分越过边境，正轰隆隆地缓慢向南开进。"}},{"pos":"N-SING 单数名词","cn":"（机器的）刺耳摩擦声","en":"The grind of a machine is the harsh, scraping noise that it makes, usually because it is old or is working too hard.","ex":{"en":"The grind of heavy machines could get on their nerves.","cn":"重型机器发出的刺耳的摩擦声会让他们心烦意乱。"}},{"pos":"N-SING 单数名词","cn":"枯燥乏味的事；苦差事","en":"If you refer to routine tasks or activities as the grind, you mean they are boring and take up a lot of time and effort.","ex":{"en":"The daily grind of government is done by Her Majesty's Civil Service","cn":"枯燥的日常政务都由女王陛下的政府行政部门来处理。"}},{"pos":"PHRASE 短语","cn":"逐渐停止；慢慢瘫痪","en":"If a country's economy or something such as a process grinds to a halt, it gradually becomes slower or less active until it stops.","ex":{"en":"The peace process has ground to a halt while Israel struggles to form a new government.","cn":"当以色列竭力组建新政府的时候，和平进程已经陷于停顿。"}},{"pos":"PHRASE 短语","cn":"（车辆）声音刺耳地缓缓停下","en":"If a vehicle grinds to a halt, it stops slowly and noisily.","ex":{"en":"The tanks ground to a halt after a hundred yards because the fuel had been siphoned out.","cn":"由于燃油被人抽走，这些坦克行驶了100码后又轰隆隆地缓缓停了下来。"}},{"pos":"","cn":"","en":"to have an axe to grind→see: ; to come to a grinding halt→see: ;"},{"pos":"","cn":"","en":"相关词组：grind down grind on grind out grind up"}]},"examples":[{"en":"It's a long grind to the top of that particular profession.","cn":"爬到那种行业的最高位置要经过漫长的艰苦奋斗。"},{"en":"She grinds out romantic novels at the rate of five a year.","cn":"她以一年五部的速度胡乱拼凑低劣的爱情小说。"}]},"grade":{"media":{"uk":"media/uk/grade__gb_1.mp3","us":"media/us/grade__us_1.mp3"},"oxford":{"phon":"ɡreɪd","pos":"noun","senses":[{"en":"a mark given in an exam or for a piece of school work","cn":"成绩等级；评分等级","lab":"British English","ex":{"en":"She got good grades in her exams.","cn":"她考试成绩优良。"}},{"en":"(in the US school system) one of the levels in a school with children of similar age","cn":"（美国学制）年级","ex":{"en":"Sam is in (the) second grade.","cn":"萨姆读二年级。"}},{"en":"the quality of a particular product or material","cn":"（产品、材料的）等级，品级","ex":{"en":"All the materials used were of the highest grade.","cn":"使用的材料全是最高等级的。"}},{"en":"a level of ability or rank that somebody has in an organization","cn":"（官衔的）级别；职别","ex":{"en":"salary/pay grades (= levels of pay)","cn":"工资／薪酬级别"}},{"en":"how serious an illness is","cn":"（疾病的）程度，阶段","lab":"specialist","ex":{"en":"low/high grade fever","cn":"低烧；高烧"}},{"en":"a slope on a road or railway; the degree to which the ground slopes","cn":"（公路或铁路的）坡；坡度；斜率；倾斜度","lab":"especially North American English","ex":{"en":"The hill has a grade of 25 per cent.","cn":"这座山的坡度为25%。"}},{"en":"a level of exam in musical skill","cn":"（音乐考试的）级别，水平","lab":"British English","ex":{"en":"grade 6 piano","cn":"六级钢琴"}},{"en":"to give a grade to a student or to a piece of their written work","cn":"给…评分；给…分数","lab":"especially North American English","ex":{"en":"I spent all weekend grading papers.","cn":"我整个周末都在评阅试卷。"},"pos":"verb"},{"en":"to arrange people or things in groups according to their ability, quality, size, etc.","cn":"（按能力、质量、大小等）分级，分等，分类","g":"[usually passive]","ex":{"en":"The containers are graded according to size.","cn":"这些容器按大小分类。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"将…分等级","en":"If something is graded, its quality is judged, and it is often given a number or a name that indicates how good or bad it is.","ex":{"en":"Dust masks are graded according to the protection they offer","cn":"防尘口罩根据它们的防护效果分等级。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指正式评定的）等级，品级","en":"The grade of a product is its quality, especially when this has been officially judged.","ex":{"en":"...a grade II listed building.","cn":"列入二级文物保护的建筑"}},{"pos":"N-COUNT 可数名词","cn":"（用数字或字母表示的）成绩，评分","en":"Your grade in an examination or piece of written work is the mark you get, usually in the form of a letter or number, that indicates your level of achievement.","ex":{"en":"What grade are you hoping to get?","cn":"你希望得到什么样的成绩？"}},{"pos":"N-COUNT 可数名词","cn":"（职位的）级别，等级","en":"Your grade in a company or organization is your level of importance or your rank.","ex":{"en":"Staff turnover is particularly high among junior grades.","cn":"基层职员的流动率特别高。"}},{"pos":"N-COUNT 可数名词","cn":"（美国学校中的）年级","en":"In the United States, a grade is a group of classes in which all the children are of a similar age. When you are six years old you go into the first grade and you leave school after the twelfth grade.","ex":{"en":"Mr White teaches first grade in south Georgia.","cn":"怀特先生在佐治亚州南部教一年级。"}},{"pos":"N-COUNT 可数名词","cn":"斜坡","en":"A grade is a slope.","ex":{"en":"She drove up a steep grade and then began the long descent into the desert.","cn":"她驾车开上一个陡坡，然后沿着长长的下坡路驶入沙漠。"}},{"pos":"N-COUNT 可数名词","cn":"军衔","en":"Someone's grade is their military rank.","ex":{"en":"I was a naval officer, lieutenant junior grade.","cn":"我是一名海军中尉军官。"}},{"pos":"PHRASE 短语","cn":"成功；达到理想标准","en":"If someone makes the grade, they succeed, especially by reaching a particular standard.","ex":{"en":"She had a strong desire to be a dancer but failed to make the grade.","cn":"她非常渴望成为舞蹈演员，但却因为达不到标准而未能圆梦。"}}]},"examples":[{"en":"Responses were graded from 1 (very satisfied) to 5 (not at all satisfied).","cn":"回答按 1（非常满意）到 5（完全不满意）分类。"},{"en":"About 10% of trainees fail to make the grade.","cn":"接受培训的人大约有 10% 未达标。"}]},"grids":{"oxford":{"phon":"ɡrɪd","pos":"noun","senses":[{"en":"a pattern of straight lines, usually crossing each other to form squares","cn":"网格；方格"},{"en":"a frame of metal or wooden bars that are parallel or cross each other （","cn":"金属或木制的）格子，格栅，栅栏"}]}},"graduation":{"oxford":{"phon":"ˌɡrædʒuˈeɪʃn","pos":"noun","senses":[{"en":"the act of successfully completing a university degree, or studies at an American high school","cn":"（大学或美国高中的）毕业","g":"[uncountable]","ex":{"en":"It was my first job after graduation.","cn":"那是我毕业后的第一个工作。"}},{"en":"a ceremony at which degrees, etc. are officially given out","cn":"毕业典礼","g":"[uncountable, countable]","ex":{"en":"graduation day","cn":"毕业典礼日"}},{"en":"a mark showing a division on a scale","cn":"刻度","g":"[countable]","ex":{"en":"The graduations are marked on the side of the flask.","cn":"烧瓶壁标有刻度。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"毕业","en":"Graduation is the successful completion of a course of study at a university, college, or school, for which you receive a degree or diploma.","ex":{"en":"They asked what his plans were after graduation","cn":"他们问他毕业之后有何打算。"}},{"pos":"N-COUNT 可数名词","cn":"毕业典礼","en":"A graduation is a special ceremony at university, college, or school, at which degrees and diplomas are given to students who have successfully completed their studies.","ex":{"en":"...the graduation ceremony at Yale","cn":"耶鲁大学的毕业典礼"}},{"pos":"N-COUNT 可数名词","cn":"刻度线；刻度","en":"A graduation is a line or number on a container or measuring instrument which marks a particular measurement.","ex":{"en":"...medicine bottles with graduations on them.","cn":"标有刻度线的药瓶"}}]},"media":{"uk":"media/uk/graduation__gb_1.mp3","us":"media/us/graduation__us_1.mp3"},"examples":[{"en":"My whole family came to my graduation.","cn":"我的家人都来参加了我的毕业典礼。"},{"en":"It was my first job after graduation.","cn":"那是我毕业后的第一个工作。"}]},"greenery":{"media":{"uk":"media/uk/greenery__gb_1.mp3","us":"media/us/greenery__us_1.mp3"},"oxford":{"phon":"ˈɡriːnəri","pos":"noun","senses":[{"en":"attractive green leaves and plants","cn":"青枝绿叶；青葱的草木；绿色植物","ex":{"en":"The room was decorated with flowers and greenery.","cn":"房间里装点着花卉和绿叶植物。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"绿色植物；青葱的草木","en":"Plants that make a place look attractive are referred to as greenery .","ex":{"en":"They have ordered a bit of greenery to brighten up the new wing at Guy's Hospital.","cn":"他们订购了一些绿色植物，以给盖伊医院的新配楼增添一抹亮色。"}}]},"examples":[{"en":"The room was decorated with flowers and greenery.","cn":"房间里装点着花卉和绿叶植物。"},{"en":"the rich greenery of grass and trees","cn":"茂盛的绿色草木"}]},"graceful":{"media":{"uk":"media/uk/graceful__gb_1.mp3","us":"media/us/graceful__us_1.mp3"},"oxford":{"phon":"ˈɡreɪsfl","pos":"adjective","senses":[{"en":"moving in an attractive way that shows control; having a smooth, attractive form","cn":"优美的；优雅的；雅致的","ex":{"en":"The dancers were all tall and graceful.","cn":"这些舞蹈演员都个子高高的，动作十分优雅。"}},{"en":"polite and kind in your behaviour, especially in a difficult situation","cn":"（尤指在困境中）得体的，有风度的","ex":{"en":"His father had always taught him to be graceful in defeat.","cn":"他父亲总是教导他输了也要有风度。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优美的;优雅的","en":"Someone or something that is graceful moves in a smooth and controlled way which is attractive to watch.","ex":{"en":"His movements were so graceful they seemed effortless.","cn":"他的动作优美自如，看起来毫不费劲。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优美的；动人的；雅致的","en":"Something that is graceful is attractive because it has a pleasing shape or style.","ex":{"en":"A graceful medieval cathedral","cn":"典雅的中世纪大教堂"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优雅的；得体的；有风度的","en":"If a person's behaviour is graceful, it is polite, kind, and pleasant, especially in a difficult situation.","ex":{"en":"Aubrey could think of no graceful way to escape Corbet's company","cn":"奥布里想不出有什么得体的办法能摆脱科比特。"}}]},"examples":[{"en":"The dancers were all tall and graceful.","cn":"这些舞蹈演员都个子高高的，动作十分优雅。"},{"en":"The cathedral's white towers climb gracefully into the sky.","cn":"大教堂白色的塔楼优雅庄重地耸入云霄。"}]},"graduate":{"media":{"uk":"media/uk/graduate__gb_1.mp3","us":"media/us/graduate__us_1.mp3"},"oxford":{"phon":"ˈɡrædʒuət","pos":"noun","senses":[{"en":"a person who has a university degree","cn":"大学毕业生；学士学位获得者","lab":"North American English","ex":{"en":"job prospects for graduates","cn":"毕业生就业前景"}},{"en":"a person who has completed their school studies","cn":"毕业生","lab":"North American English","ex":{"en":"a high school graduate","cn":"中学毕业生"}},{"en":"to get a degree, especially your first degree, from a university or college","cn":"获得学位（尤指学士）；大学毕业","g":"[intransitive, transitive]","lab":"North American English","ex":{"en":"She taught in France after she graduated.","cn":"她大学毕业后在法国任教。"},"pos":"verb"},{"en":"to complete a course in education, especially at high school","cn":"毕业（尤指中学）","g":"[intransitive, transitive]","lab":"North American English","ex":{"en":"He flunked math and never graduated.","cn":"他数学不及格，中学没毕业。"},"pos":"verb"},{"en":"to give a degree, diploma, etc. to somebody","cn":"授予（某人）学位（或毕业文凭等）","g":"[transitive]","lab":"North American English","ex":{"en":"The college graduated 50 students last year.","cn":"去年这所学院有 50 名毕业生。"},"pos":"verb"},{"en":"to start doing something more difficult or important than what you were doing before","cn":"逐渐发展（或变化、进展、上升）","g":"[intransitive]","ex":{"en":"She recently graduated from being a dancer to having a small role in a movie.","cn":"她最近从一个舞蹈演员逐步过渡到在电影里扮演小角色。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（英国的）大学毕业生，学士学位获得者","en":"In Britain, a graduate is a person who has successfully completed a degree at a university or college and has received a certificate that shows this.","ex":{"en":"In 1973, the first Open University graduates received their degrees.","cn":"1973年，第一批开放大学的毕业生获得了学位。"}},{"pos":"N-COUNT 可数名词","cn":"（美国的）高中（或学院、大学）毕业生","en":"In the United States, a graduate is a student who has successfully completed a course at a high school, college, or university.","ex":{"en":"The top one-third of all high school graduates are entitled to an education at the California State University.","cn":"高中毕业生当中排名前1/3的学生可以进入加利福尼亚州立大学深造。"}},{"pos":"VERB 动词","cn":"（英国）大学毕业","en":"In Britain, when a student graduates from university, they have successfully completed a degree course.","ex":{"en":"She graduated in English and Drama from Manchester University.","cn":"她毕业于曼彻斯特大学的英语和戏剧专业。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（美国）中学（或大学）毕业，授予…学位（或毕业文凭）","en":"In the United States, when a student graduates, they complete their studies successfully and leave their school or university. You can also say that a school or university graduates a student or students.","ex":{"en":"When the boys graduated from high school, Ann moved to a small town in Vermont","cn":"当儿子们高中毕业后，安搬到佛蒙特州的一个小镇上居住。"}},{"pos":"VERB 动词","cn":"晋升；升职；升级","en":"If you graduate from one thing to another, you go from a less important job or position to a more important one.","ex":{"en":"Bruce graduated to chef at the Bear Hotel","cn":"布鲁斯晋升为大熊饭店的厨师长。"}}]},"examples":[{"en":"She recently graduated from being a dancer to having a small role in a movie.","cn":"她最近从一个舞蹈演员逐步过渡到在电影里扮演小角色。"},{"en":"Only three students graduated in Czech studies last year.","cn":"去年只有三名学生获得捷克研究学士学位。"}]},"grams":{"oxford":{"phon":"ɡræm","pos":"noun","senses":[{"en":"a unit for measuring weight. There are 1 000 grams in one kilogram.","cn":"克（重量单位，1 公斤为 1 000 克）"},{"en":"a thing that is written or drawn","cn":"写（或画）的东西"}]}},"graced":{"oxford":{"phon":"ɡreɪs","pos":"noun","senses":[{"en":"an attractive quality of movement that is smooth, elegant and controlled","cn":"优美；优雅"},{"en":"a quality of behaviour that is polite and pleasant and deserves respect","cn":"文雅；高雅"}]}},"grounds":{"oxford":{"phon":"ɡraʊnd","pos":"noun","senses":[{"en":"the solid surface of the earth","cn":"地；地面"},{"en":"soil on the surface of the earth","cn":"土；土地；土壤"}]}},"graduates":{"oxford":{"phon":"ˈɡrædʒuət","pos":"noun","senses":[{"en":"a person who has a university degree","cn":"大学毕业生；学士学位获得者"},{"en":"( NAmE ) a person who has completed their school studies","cn":"毕业生"}]}},"grasses":{"oxford":{"phon":"ɡrɑːs","pos":"noun","senses":[{"en":"a common wild plant with narrow green leaves and stems that are eaten by cows, horses, sheep, etc.","cn":"草；青草；牧草"},{"en":"any type of grass","cn":"禾本科植物"}]}},"groped":{"oxford":{"phon":"ɡrəʊp","pos":"verb","senses":[{"en":"to try and find sth that you cannot see, by feeling with your hands","cn":"摸索；搜索；搜寻；探寻"},{"en":"to try and reach a place by feeling with your hands because you cannot see clearly （","cn":"用手）摸索着往前走"}]}},"grains":{"oxford":{"phon":"ɡreɪn","pos":"noun","senses":[{"en":"the small hard seeds of food plants such as wheat , rice, etc; a single seed of such a plant","cn":"谷物；谷粒"},{"en":"a small hard piece of particular substances","cn":"颗粒；细粒"}]}},"greater":{"oxford":{"phon":"ɡreɪt","pos":"adjective","senses":[{"en":"very large; much bigger than average in size or quantity","cn":"大的；巨大的；数量大的；众多的"},{"en":"( informal ) used to emphasize an adjective of size or quality （","cn":"强调尺寸、体积或质量）很"}]},"collins":{"senses":[{"pos":"","cn":"（great的比较级）","en":"Greater is the comparative of great."},{"pos":"ADJ 形容词","cn":"（与大城市的名称连用，指包括附近城区及郊区在内的整个城市）大的","en":"Greater is used with the name of a large city to refer to the city together with the surrounding urban and suburban area.","ex":{"en":"...Greater London.","cn":"大伦敦区"}},{"pos":"ADJ 形容词","cn":"（与某国名称连用，指包括该国和曾属该国或者人们认为应属该国的地区在内的更广阔的区域）大的","en":"Greater is used with the name of a country to refer to a larger area which includes that country and other land which used to belong to it, or which some people believe should belong to it.","ex":{"en":"...greater Syria.","cn":"大叙利亚"}}]}},"greens":{"oxford":{"phon":"ɡriːn","pos":"adjective","senses":[{"en":"having the colour of grass or the leaves of most plants and trees","cn":"绿色的；草绿色的"},{"en":"covered with grass or other plants","cn":"长满青草的；绿油油的；青葱的"}]}},"gratings":{"oxford":{"phon":"ˈɡreɪtɪŋ","pos":"noun","senses":[{"en":"a flat frame with metal bars across it, used to cover a window, a hole in the ground, etc. （","cn":"窗户、地沟口等的）栅栏，格栅，格子"},{"en":"unpleasant to listen to","cn":"刺耳的"}]}},"greeted":{"oxford":{"phon":"ɡriːt","pos":"verb","senses":[{"en":"to say hello to sb or to welcome them","cn":"和（某人）打招呼（或问好）；欢迎；迎接"},{"en":"to react to sb/sth in a particular way （","cn":"以某种方式）对 … 作出反应"}]}},"grandsons":{"oxford":{"phon":"ˈɡrænsʌn","pos":"noun","senses":[{"en":"a son of your son or daughter","cn":"孙子；外孙"}]}},"greeks":{"oxford":{"phon":"ɡriːk","pos":"noun","senses":[{"en":"a person from modern or ancient Greece","cn":"希腊人；古希腊人"},{"en":"the language of modern or ancient Greece","cn":"希腊语"}]}},"grades":{"oxford":{"phon":"ɡreɪd","pos":"noun","senses":[{"en":"the quality of a particular product or material （","cn":"产品、材料的）等级，品级"},{"en":"a level of ability or rank that sb has in an organization （","cn":"官衔的）级别；职别"}]}},"grooms":{"oxford":{"phon":"ɡruːm","pos":"verb","senses":[{"en":"to clean or brush an animal （","cn":"给动物）擦洗，刷洗"},{"en":"to clean the fur or skin of another animal or itself （","cn":"给自己或其他动物）理毛，梳毛"}]}},"groups":{"oxford":{"phon":"ɡruːp","pos":"noun","senses":[{"en":"a number of people or things that are together in the same place or that are connected in some way","cn":"组；群；批；类；簇"},{"en":"( business","cn":"商 ) a number of companies that are owned by the same person or organization 集团"}]}},"greatest":{"oxford":{"phon":"ɡreɪt","pos":"adjective","senses":[{"en":"very large; much bigger than average in size or quantity","cn":"大的；巨大的；数量大的；众多的"},{"en":"( informal ) used to emphasize an adjective of size or quality （","cn":"强调尺寸、体积或质量）很"}]}},"groping":{"oxford":{"phon":"ɡrəʊp","pos":"verb","senses":[{"en":"to try and find sth that you cannot see, by feeling with your hands","cn":"摸索；搜索；搜寻；探寻"},{"en":"to try and reach a place by feeling with your hands because you cannot see clearly （","cn":"用手）摸索着往前走"}]}},"greener":{"oxford":{"phon":"ɡriːn","pos":"adjective","senses":[{"en":"having the colour of grass or the leaves of most plants and trees","cn":"绿色的；草绿色的"},{"en":"covered with grass or other plants","cn":"长满青草的；绿油油的；青葱的"}]}},"grimace":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（因厌恶、痛苦等）做鬼脸，扮怪相，脸部扭曲","en":"If you grimace, you twist your face in an ugly way because you are annoyed, disgusted, or in pain.","ex":{"en":"She started to sit up, grimaced, and sank back weakly against the pillow","cn":"她坐了起来，露出痛苦的表情，又有气无力地倒在枕头上。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to twist your face in an ugly way because you do not like something, because you are feeling pain, or because you are trying to be funny 〔","cn":"因不喜欢某物﹑感到疼痛或开玩笑时〕做鬼脸﹐扮怪相"},{"en":"the expression on your face when you move your eyebrows together because you are angry, unhappy, or confused","cn":""},{"en":"an expression in which your mouth curves upwards, when you are being friendly or are happy or amused","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"The grimace on her face when he asked her to the prom told him her answer was \"no\" before she said a word. A grimace is a facial expression that usually suggests disgust or pain, but sometimes comic exaggeration."}]},"collocations":{"phrases":["ADJ. little, slight, small | ugly | rueful, wry | facial","VERB + GRIMACE give, make She made a wry grimace. | twist into His face twisted into a grimace.","GRIMACE + VERB twist sth An ugly grimace twisted her face.","PREP. with a ~ He acknowledged his mistake with a wry grimace. | ~ of a grimace of disgust/pain"]},"media":{"uk":"media/ldoce/hwd/bre/1/grimace_las3_br.mp3","us":"media/ldoce/hwd/ame/6/grimace1.mp3"},"examples":[{"en":"‘What's that?’ she asked with a grimace. “","cn":"那是什么？”她皱着眉头问道。"},{"en":"He grimaced at the bitter taste.","cn":"他一尝那苦味，做了个怪相。"}],"oxford":{"phon":"ˈɡrɪməs","pos":"verb","senses":[{"en":"to make an ugly expression with your face to show pain, dislike, etc.","cn":"（因痛苦、厌恶等）做鬼脸，做怪相","ex":{"en":"He grimaced at the bitter taste.","cn":"他一尝那苦味就做了个怪相。"}},{"en":"an ugly expression made by twisting your face, used to show pain, dislike, etc. or to make somebody laugh","cn":"怪相；鬼脸；脸部扭曲","ex":{"en":"to make/give a grimace of pain","cn":"做出／露出痛苦的表情"},"pos":"noun"}]}},"grunt":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（尤指因为烦恼或不感兴趣）咕噜，嘟哝着说","en":"If you grunt, you make a low sound, especially because you are annoyed or not interested in something.","ex":{"en":"The driver grunted, convinced that Michael was crazy","cn":"司机嘟哝了一声，认定迈克尔是发疯了。"}},{"pos":"VERB 动词","cn":"（动物）发出哼声，发出咕噜声","en":"When an animal grunts, it makes a low rough noise.","ex":{"en":"...the sound of a pig grunting.","cn":"猪发出的呼噜声"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something very quietly, using your breath rather than your voice","cn":""},{"en":"to say something quietly, especially when you are annoyed but do not want someone to hear you complaining","cn":""},{"en":"to say something quietly without pronouncing the words clearly, so that it is difficult to understand","cn":""}]},"vocab":{"pos":"1 v n 2 n 3 n","senses":[{"en":"If your younger brother is particularly grouchy, he might simply grunt in answer to your question about whose turn it is to take out the garbage. A grunt is a short, deep sound."}]},"collocations":{"phrases":["ADJ. little | low | non-committal He gave a non-committal grunt in reply.","VERB + GRUNT give, let out | hear","PREP. with a ~ He lifted the heavy box with a grunt. | ~ of a grunt of pain • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/e/grunt_v0205.mp3","us":"media/ldoce/hwd/ame/e/grunt1.mp3"},"examples":[{"en":"When I told her what had happened she just grunted and turned back to her book.","cn":"我告诉她出了什么事，她只哼了一声就又看起书来了。"},{"en":"He pulled harder on the rope, grunting with the effort.","cn":"他边用力边哼声，使出更大的力气拉绳子。"}],"oxford":{"phon":"ɡrʌnt","pos":"verb","senses":[{"en":"to make a short, low sound in the throat","cn":"发出呼噜声","g":"[intransitive]"},{"en":"to make a short, low sound in your throat, especially to show that you are in pain, annoyed or not interested; to say something using this sound","cn":"发出哼声；咕哝；嘟哝","g":"[intransitive, transitive]","ex":{"en":"He pulled harder on the rope, grunting with the effort.","cn":"他边用力边哼声，使出更大的力气拉绳子。"}},{"en":"a short, low sound made by a person or an animal (especially a pig)","cn":"哼声；咕哝声；嘟哝声；（尤指猪的）呼噜声","ex":{"en":"to give a grunt of effort/pain","cn":"发出费力／痛苦的哼声"},"pos":"noun"},{"en":"a worker who does boring tasks for low pay","cn":"工作乏味收入低的工人","lab":"North American English, informal，，","pos":"noun"},{"en":"a soldier of low rank","cn":"士兵；步兵","lab":"North American English, informal，，","pos":"noun"}]}},"grief":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"悲伤；悲痛","en":"Grief is a feeling of extreme sadness.","ex":{"en":"...a huge outpouring of national grief for the victims of the shootings","cn":"举国上下对枪击事件中的遇害者所表现出的万分悲痛之情"}},{"pos":"PHRASE 短语","cn":"（事情）失败；（人）受挫，遭到不幸","en":"If something comes to grief, it fails. If someone comes to grief, they fail in something they are doing, and may be hurt.","ex":{"en":"So many marriages have come to grief over lack of money","cn":"许多婚姻都因缺钱而以失败告终。"}},{"pos":"EXCLAM 感叹语","cn":"（表示惊奇或震惊）哎呀，天哪","en":"Some people say 'Good grief' when they are surprised or shocked.","ex":{"en":"'He's been arrested for theft and burglary.' — 'Good grief!'","cn":"“他因为偷窃和入室盗窃而被逮捕了。”——“我的天哪！”"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sad feeling, caused especially when a happy time is ending, or when you feel sorry about someone else’s unhappiness","cn":""},{"en":"the unhappy feeling you have when you are in a very difficult or unpleasant situation, especially when this lasts for a long time","cn":""},{"en":"the feeling of being very sad, especially because someone has died or because terrible things have happened to you","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Grief means intense sorrow. You feel grief if something terribly sad happens, like if your dog dies or if your childhood sweetheart breaks up with you."}]},"collocations":{"phrases":["ADJ. considerable, deep, great, inconsolable, real | private I felt awkward at intruding on their private grief.","VERB + GRIEF be overcome with, be stricken with, experience, feel Her parents were stricken with grief. | express, show | die from/of | come","PREP. ~ at Children can feel real grief at the loss of a pet. | ~ for her grief for her dead husband","PHRASES a feeling/sense of grief"]},"media":{"uk":"media/ldoce/hwd/bre/6/grief0205.mp3","us":"media/ldoce/hwd/ame/2/grief.mp3"},"examples":[{"en":"Several pedestrians came to grief on the icy pavement.","cn":"好几个人都在结了冰的人行道上摔伤了。"},{"en":"It was a grief to them that they had no children.","cn":"没有孩子是他们的一块心病。"}],"oxford":{"phon":"ɡriːf","pos":"noun","senses":[{"en":"a very sad feeling, especially when somebody dies","cn":"（尤指因某人去世引起的）悲伤，悲痛，伤心","g":"[uncountable, countable]","ex":{"en":"She was overcome with grief when her husband died.","cn":"丈夫去世时她悲痛欲绝。"}},{"en":"something that makes you feel very sad","cn":"伤心事；痛苦","g":"[countable, usually singular]","ex":{"en":"It was a grief to them that they had no children.","cn":"没有孩子是他们的一块心病。"}},{"en":"problems and worry","cn":"担心；忧虑","g":"[uncountable]","lab":"informal","ex":{"en":"He caused his parents a lot of grief.","cn":"他没少让父母操心。"}}]}},"gradient":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"斜坡；坡度；倾斜度","en":"A gradient is a slope, or the degree to which the ground slopes.","ex":{"en":"...a gradient of 1 in 3","cn":"1比3的倾斜度"}},{"pos":"N-COUNT 可数名词","cn":"变化率","en":"The gradient of a graph or series of measurements is the rate at which one set of amounts changes in relation to another."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a slope or a degree of slope, especially in a road or railway 〔","cn":"尤指道路或铁路的〕斜坡﹐坡度"}]},"vocab":{"pos":"n","senses":[{"en":"The gradient of a surface is its slope. If you're a daredevil and you're looking for a road to fly down on your skateboard, you'll want to find one with a fairly steep gradient ."}]},"collocations":{"phrases":["ADJ. steep | gentle, slight | downhill, uphill","VERB + GRADIENT have The road has a fairly steep gradient.","PREP. on a ~ The football pitch was on a slight gradient."]},"media":{"uk":"media/ldoce/hwd/bre/9/gradient0205.mp3","us":"media/ldoce/hwd/ame/8/gradient.mp3"},"examples":[{"en":"a hill with a gradient of 1 in 4 (or 25%)","cn":"倾斜度为 1:4（或 25%）的小山"},{"en":"a steep gradient","cn":"陡峭的坡度"}],"oxford":{"phon":"ˈɡreɪdiənt","pos":"noun","senses":[{"en":"a slope on a road or railway; the degree to which the ground slopes","cn":"（公路或铁路的）坡；坡度；斜率；倾斜度","lab":"especially in North American English","ex":{"en":"The route includes some steep gradients.","cn":"该路线包括一些陡峭的坡度。"}},{"en":"the rate at which temperature, pressure, etc. changes, or increases and decreases, between one region and another","cn":"（温度、压力等的）变化率，梯度变化曲线","lab":"specialist"}]}},"graph":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"图；图表；曲线图","en":"A graph is a mathematical diagram which shows the relationship between two or more sets of numbers or measurements."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drawing that uses a line or lines to show how two or more sets of measurements are related to each other","cn":"图表﹐曲线图"}]},"vocab":{"pos":"n v","senses":[{"en":"A graph is a visual plotting of the relationship between two or more quantities, like a math map. To graph is to create such a chart."}]},"collocations":{"phrases":["ADJ. bar, line","VERB + GRAPH draw, produce | depict sth as/on, show sth as/in/on The statistics can be depicted as a graph. | plot sth on The figures are al","GRAPH + VERB show sth She drew a graph showing the relationship between costs and sales.","GRAPH + NOUN paper","PREP. in a/the ~ I decided to show the results in a bar graph. | on a/the ~ We can see on this graph how the company has grown over the last","PHRASES in graph form Results can be shown in numeric or graph form."]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdegraph.mp3","us":"media/ldoce/hwd/ame/6/graph.mp3","img":["media/thumb/graph.jpg"]},"examples":[{"en":"The graph shows how house prices have risen since the 1980s.","cn":"此图表明了自 20 世纪 80 年代以来房价上涨的情况。"},{"en":"Plot a graph of height against age.","cn":"绘制一张身高与年龄对照的曲线图。"}],"oxford":{"phon":"ɡrɑːf","pos":"noun","senses":[{"en":"a diagram consisting of a line or lines, showing how two or more sets of numbers are related to each other","cn":"图；图表；曲线图","ex":{"en":"Plot a graph of height against age.","cn":"绘制一张身高与年龄对照的曲线图。"}}]}},"grandeur":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"宏伟；堂皇；壮丽","en":"If something such as a building or a piece of scenery has grandeur, it is impressive because of its size, its beauty, or its power.","ex":{"en":"...the grandeur and natural beauty of South America","cn":"南美洲壮丽的自然美景"}},{"pos":"N-UNCOUNT 不可数名词","cn":"高贵；显赫；自命不凡","en":"Someone's grandeur is the great importance and social status that they have, or think they have.","ex":{"en":"He is wholly concerned with his own grandeur.","cn":"他只关心自己的显赫地位。"}},{"pos":"","cn":"","en":"delusions of grandeur→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"impressive beauty, power, or size","cn":"壮丽﹐雄伟"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun grandeur to describe something that is splendid or magnificent, such as a lofty idea or an impressive building: “The gilded domes and ornate detail added to the grandeur of the church on Red Square.”"}]},"collocations":{"phrases":["ADJ. rugged the rugged grandeur of the mountains | breathtaking, dramatic, majestic, sheer the breathtaking grandeur of the cathedral | fade"]},"media":{"uk":"media/ldoce/hwd/bre/8/grandeur0205.mp3","us":"media/ldoce/hwd/ame/c/grandeur.mp3"},"examples":[{"en":"The hotel had an air of faded grandeur.","cn":"这家旅馆给人一种繁华已逝的感觉。"},{"en":"She is clearly suffering from delusions of grandeur (= thinks she is more important than she really is).","cn":"她显然是犯了妄自尊大的毛病。"}],"oxford":{"phon":"ˈɡrændʒə(r)","pos":"noun","senses":[{"en":"the quality of being great and impressive in appearance","cn":"宏伟；壮丽；堂皇","ex":{"en":"We admired the grandeur and simplicity of the Roman architecture.","cn":"我们欣赏罗马建筑的宏伟和简洁。"}},{"en":"the importance or social status somebody has or thinks they have","cn":"高贵；显赫；伟大","ex":{"en":"He has a sense of grandeur about him.","cn":"他觉得自己很了不起。"}}]}},"groundwork":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"基础；根基","en":"The groundwork for something is the early work on it which forms the basis for further work.","ex":{"en":"Yesterday's meeting was to lay the groundwork for the task ahead","cn":"昨天的会议是为以后的工作做准备。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to make plans or arrangements for something that will happen in the future, so that you will be ready when it happens","cn":""},{"en":"to do all the things you need to do to prepare for a special occasion or event","cn":""},{"en":"to do all the things you must do in order to prepare for an important event","cn":""}]},"collocations":{"phrases":["ADJ. basic","VERB + GROUNDWORK do, lay, prepare, provide (sb with) The first meeting laid the groundwork for the final agreement. The first year provides","PREP. ~ for We are already doing the groundwork for the introduction of the scheme next year."]},"media":{"uk":"media/ldoce/hwd/bre/7/groundwork0205.mp3","us":"media/ldoce/hwd/ame/0/groundwork.mp3"},"examples":[{"en":"Officials are laying the groundwork for a summit conference of world leaders.","cn":"官员们正在为世界首脑峰会做准备工作。"},{"en":"His speech laid the groundwork for independence.","cn":"他的演说为独立打下了基础。"}],"oxford":{"phon":"ˈɡraʊndwɜːk","pos":"noun","senses":[{"en":"work that is done as preparation for other work that will be done later","cn":"基础工作；准备工作","ex":{"en":"Officials are laying the groundwork for a summit conference of world leaders.","cn":"官员们正在为世界首脑峰会做准备工作。"}}]}},"grate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"炉栅；炉格；炉排；炉箅","en":"A grate is a framework of metal bars in a fireplace, which holds the coal or wood.","ex":{"en":"A wood fire burned in the grate.","cn":"木柴在炉栅中燃烧着。"}},{"pos":"VERB 动词","cn":"磨碎,擦碎（食物）","en":"If you grate food such as cheese or carrots, you rub it over a metal tool called a grater so that the food is cut into very small pieces.","ex":{"en":"Grate the cheese into a mixing bowl.","cn":"将干酪磨碎放进搅拌碗中。"}},{"pos":"VERB 动词","cn":"发出吱吱嘎嘎的摩擦声；发出刺耳的摩擦声","en":"When something grates, it rubs against something else making a harsh, unpleasant sound.","ex":{"en":"His chair grated as he got to his feet","cn":"他起身时椅子发出吱吱嘎嘎的声音。"}},{"pos":"VERB 动词","cn":"使烦躁；使气恼；使难受","en":"If something such as someone's behaviour grates on you or grates, it makes you feel annoyed.","ex":{"en":"His manner always grated on me","cn":"他的态度总是让我感到气恼。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to cut cheese, carrot etc into small pieces by rubbing it against a special tool","cn":""},{"en":"to make butter, chocolate etc become liquid","cn":""},{"en":"to put flour or other powders through a sieve (= tool like a net made of wire, which you use for removing larger grains or pieces )","cn":""}]},"vocab":{"pos":"1 v n 2 n v","senses":[{"en":"When you grate something you rip it to shreds, like a pound of solid cheese that you shred for a recipe."}]},"collocations":{"phrases":["ADV. coarsely | finely Sprinkle the top of the dish with some finely grated cheese.","PHRASES freshly grated a teaspoon of freshly grated nutmeg 2 make a sharp unpleasant sound","ADV. harshly","PREP. against The steel of the helmet grated against the door. | on The grit beneath her soles grated harshly on the wooden deck."]},"media":{"uk":"media/ldoce/hwd/bre/6/grate_n0205.mp3","us":"media/ldoce/hwd/ame/a/grate1.mp3","img":["media/thumb/grate.jpg"]},"examples":[{"en":"The rusty hinges grated as the gate swung back.","cn":"大门荡了回去，生锈的铰链发出吱嘎吱嘎的刺耳声。"},{"en":"It grated with him when people implied he wasn't really British.","cn":"当有人暗示他不是地道的英国人时，他很是恼火。"}],"oxford":{"phon":"ɡreɪt","pos":"noun","senses":[{"en":"a metal frame for holding the wood or coal in a fireplace","cn":"炉条；炉箅","ex":{"en":"A huge log fire was burning in the grate.","cn":"壁炉里熊熊燃烧着大火。"}},{"en":"a frame of metal bars over the opening to a drain in the ground","cn":"下水道孔盖","lab":"both US English"},{"en":"to rub food against a grater in order to cut it into small pieces","cn":"擦碎，磨碎（食物）","g":"[transitive]","lab":"British English","ex":{"en":"grated apple/carrot/cheese, etc.","cn":"擦成细丝的苹果、胡萝卜、干酪等"},"pos":"verb"},{"en":"to annoy somebody","cn":"激怒（某人）；招惹（某人）","g":"[intransitive]","ex":{"en":"Her voice really grates on me.","cn":"她的声音真叫我难受。"},"pos":"verb"},{"en":"when two hard surfaces grate as they rub together, they make a sharp unpleasant sound; somebody can also make one thing grate against another","cn":"（使）发出刺耳的声音，发出吱吱嘎嘎的摩擦声","g":"[intransitive, transitive]","ex":{"en":"The rusty hinges grated as the gate swung back.","cn":"大门荡了回去，生锈的铰链发出吱嘎吱嘎的刺耳声。"},"pos":"verb"}]}},"growl":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（狗等）低声吼叫","en":"When a dog or other animal growls, it makes a low noise in its throat, usually because it is angry.","ex":{"en":"The dog was biting, growling and wagging its tail.","cn":"那条狗在一边撕咬一边低声吼叫，尾巴也跟着摇摆。"}},{"pos":"VERB 动词","cn":"（人）发出低沉的怒吼，咆哮","en":"If someone growls something, they say something in a low, rough, and angry voice.","ex":{"en":"His fury was so great he could hardly speak. He growled some unintelligible words at Pete","cn":"他气得几乎说不出话来，冲着皮特不知咆哮些什么。"}},{"pos":"VERB 动词","cn":"隆隆作响；轰鸣","en":"If you say that something growls, you mean that it makes a deep low noise.","ex":{"en":"My stomach growled","cn":"我的肚子咕咕叫。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something very quietly, using your breath rather than your full voice","cn":""},{"en":"to say something quietly without pronouncing the words clearly","cn":""},{"en":"to say something quietly, especially when you are annoyed but do not want someone to hear you complaining","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To growl is to make a low, guttural, aggressive sound, like “grrrrrrrrrrr.” If you’ve ever gotten too close to an angry dog, you’ve probably heard a growl ."}]},"collocations":{"phrases":["ADV. angrily, savagely &lsquo;I'm a desperate man,&rsquo; he growled savagely. | softly, throatily","PREP. at The dog growled softly at me. | with Her stomach was growling with hunger."]},"media":{"uk":"media/ldoce/hwd/bre/7/growl0205.mp3","us":"media/ldoce/hwd/ame/2/growl.mp3"},"examples":[{"en":"She growled a sarcastic reply.","cn":"她以讥讽的口吻咬牙切齿地回答。"},{"en":"‘Who are you?’ he growled at the stranger. “","cn":"你是谁？”他向陌生人怒吼道。"}],"oxford":{"phon":"ɡraʊl","pos":"verb","senses":[{"en":"to make a low sound in the throat, usually as a sign of anger","cn":"低声吼叫","g":"[intransitive]","lab":"figurative","ex":{"en":"The dog growled at them.","cn":"狗对着他们咆哮。"}},{"en":"to say something in a low angry voice","cn":"发出低沉的怒吼；咆哮","g":"[transitive]","ex":{"en":"‘Who are you?’ he growled at the stranger.","cn":"“你是谁？”他向陌生人怒吼道。"}},{"en":"a deep angry sound made when somebody/something growls","cn":"怒吼声；咆哮","ex":{"en":"The dog gave a threatening growl.","cn":"那只狗发出了一声威胁的低吼。"},"pos":"noun"}]}},"grievance":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"委屈；不满；不平；抱怨","en":"If you have a grievance about something that has happened or been done, you believe that it was unfair.","ex":{"en":"They had a legitimate grievance","cn":"他们的抱怨是合乎情理的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you say or write when you are complaining, especially to someone in an official position","cn":""},{"en":"when someone complains publicly about something that they think is wrong or unfair and should not be allowed to happen","cn":""},{"en":"something that you feel unhappy about because you think that you have been treated unfairly – use this especially about an official complaint you make about the place where you work","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A grievance is a complaint. It can be formal, like an employee files grievance because of unsafe working conditions, or more of an emotional matter, like a grievance against an old friend who betrayed you."}]},"collocations":{"phrases":["ADJ. genuine, legitimate, real Some people will complain even if they have no genuine grievance. | imaginary, imagined | long-standing, old ","VERB + GRIEVANCE harbour, have, nurse She still nursed her old grievance. | air, express, vent, voice | hear (formal) , listen to MPs spend ","PREP. ~ about/over The meeting will be a chance to air your grievances about the organization. | ~ against He had a personal grievance again","PHRASES a sense of grievance"]},"media":{"uk":"media/ldoce/hwd/bre/0/grievance0205.mp3","us":"media/ldoce/hwd/ame/6/grievance.mp3"},"examples":[{"en":"Parents were invited to air their grievances (= express them) at the meeting.","cn":"家长们应邀在会上诉说他们的苦衷。"},{"en":"He had been nursing a grievance against his boss for months.","cn":"他几个月来一直对老板心怀不满。"}],"oxford":{"phon":"ˈɡriːvəns","pos":"noun","senses":[{"en":"something that you think is unfair and that you complain or protest about; a feeling that you have been badly treated","cn":"不平的事；委屈；抱怨；牢骚","ex":{"en":"Parents were invited to air their grievances (= express them) at the meeting.","cn":"家长们应邀在会上诉说他们的苦衷。"}}]}},"grace":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"优美；优雅","en":"If someone moves with grace, they move in a smooth, controlled, and attractive way.","ex":{"en":"He moved with the grace of a trained boxer","cn":"他的动作带着一种训练有素的拳击手的风采。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"修养；涵养","en":"If someone behaves with grace, they behave in a pleasant, polite, and dignified way, even when they are upset or being treated unfairly.","ex":{"en":"The new King seemed to be carrying out his duties with grace and due decorum","cn":"新国王在履行职责时看起来举止得体、端庄稳重。"}},{"pos":"N-PLURAL 复数名词","cn":"风度；体面","en":"The graces are the ways of behaving and doing things which are considered polite and well-mannered.","ex":{"en":"She didn't fit in and she had few social graces.","cn":"她不适合这种场合，对社交礼仪所知甚少。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"宽限期；延缓期","en":"Grace is used in expressions such as a day's grace and a month's grace to say that you are allowed that amount of extra time before you have to finish something.","ex":{"en":"She wanted a couple of days' grace to get the maisonette cleaned before she moved in","cn":"她想延缓几天，等到把这套复式公寓清理干净后再搬进去。"}},{"pos":"VERB 动词","cn":"为…增色；使更加优美","en":"If you say that something graces a place or a person, you mean that it makes them more attractive.","ex":{"en":"He went to the beautiful old Welsh dresser that graced this homely room","cn":"他走到为这间舒适的房间增色不少的漂亮的旧威尔士碗橱前。"}},{"pos":"VERB 动词","cn":"给…增光;使生辉","en":"If you say that someone important will grace an event or an organization, you mean that they have agreed to be present at the event or to be part of the organization.","ex":{"en":"He had been invited to grace a function at the evening college.","cn":"他应邀为这所夜校的活动捧场。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（上帝的）恩宠，恩典","en":"In Christianity and some other religions, grace is the kindness that God shows to people because he loves them.","ex":{"en":"It was only by the grace of God that no one died.","cn":"承蒙上帝保佑才无人死亡。"}},{"pos":"N-VAR 可变名词","cn":"（饭前或饭后的）谢恩祷告","en":"When someone says grace before or after a meal, they say a prayer in which they thank God for the food and ask Him to bless it.","ex":{"en":"Leo, will you say grace?","cn":"利奥，你来做饭前祷告吧？"}},{"pos":"N-VOC; N-PROPER 称呼名词；专有名词","cn":"（对公爵、公爵夫人或大主教的尊称）大人，阁下，夫人","en":"You use expressions such as Your Grace and His Grace when you are addressing or referring to a duke, duchess, or archbishop.","ex":{"en":"Your Grace, I have a great favour to ask of you.","cn":"大人，我想请您施以大惠。"}},{"pos":"PHRASE 短语","cn":"突然失利；过气；受冷落","en":"If someone falls from grace, they suddenly stop being successful or popular.","ex":{"en":"All went well at first, and I was in high favour; but presently I fell from grace","cn":"我最初一帆风顺，备受器重，但现在却失宠了。"}},{"pos":"PHRASE 短语","cn":"通情达理地做;知趣地做","en":"If someone has the good grace to do something, they are polite enough or honest enough to do it.","ex":{"en":"He did not even have the grace to apologise","cn":"他甚至连一个道歉都没有。"}},{"pos":"PHRASE 短语","cn":"若非上帝保佑，要不是我福大命大（我也会遭此不幸）","en":"If you are talking about someone who is in a bad situation and you say 'There but for the grace of God go I', you mean that you are lucky not to be in the same situation as them and you feel sympathy for them."},{"pos":"PHRASE 短语","cn":"情愿地/ 不情愿地；欣然地/不乐意地","en":"If you do something unpleasant with good grace or with a good grace, you do it cheerfully and without complaining. If you do something with bad grace or with a bad grace, you do it unwillingly and without enthusiasm.","ex":{"en":"He accepted the decision with good grace, and wished me the very best of luck","cn":"他欣然接受这一决定并祝我好运。"}},{"pos":"PHRASE 短语","cn":"为…所赞同;得到…的欢心","en":"If you are in someone's good graces, they are pleased with you.","ex":{"en":"You're so eager to stay in the good graces of the King that nothing else matters to you.","cn":"你如此急于博得国王的欢心，以致其他事情都不管不顾了。"}},{"pos":"","cn":"","en":"airs and graces→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the one good quality that something or someone has that saves it from being completely bad, useless, or unacceptable","cn":""},{"en":"something, often the only thing, that makes someone or something not completely bad","cn":""},{"en":"a graceful and attractive manner or appearance","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"Grace commonly refers to a smooth and pleasing way of moving, or a polite and thoughtful way of behaving. But when someone says they were late to the airport and only made it onto their plane by the grace of God, they're talking about grace in the context of God's favor."}]},"collocations":{"phrases":["ADJ. easy, lithe, supple | natural | feline","VERB + GRACE have, move with","PREP. with ~ Ann moved with easy grace."]},"media":{"uk":"media/ldoce/hwd/bre/1/grace_v0205.mp3","us":"media/ldoce/hwd/ame/5/grace1.mp3"},"examples":[{"en":"She is one of the finest players ever to have graced the game.","cn":"她是曾使这场比赛生辉的最杰出的运动员之一。"},{"en":"She moves with the natural grace of a ballerina.","cn":"她的动作具有芭蕾舞演员自然优雅的丰姿。"}],"oxford":{"phon":"ɡreɪs","pos":"noun","senses":[{"en":"an attractive quality of movement that is smooth and done with control; a simple and beautiful quality","cn":"优美；优雅","g":"[uncountable]","sc":"of movement","ex":{"en":"She moves with the natural grace of a ballerina.","cn":"她的动作具有芭蕾舞演员自然优雅的丰姿。"}},{"en":"a quality of behaviour that is polite and pleasant and deserves respect","cn":"文雅；高雅","g":"[uncountable]","sc":"behaviour","ex":{"en":"He conducted himself with grace and dignity throughout the trial.","cn":"在整个审讯过程中他表现得文雅而有尊严。"}},{"en":"ways of behaving that people think are polite and acceptable","cn":"风度；体面","g":"[plural]","lab":"especially British English","sc":"behaviour","ex":{"en":"He was not particularly well versed in the social graces.","cn":"他对社交礼节并不特别熟悉。"}},{"en":"extra time that is given to somebody to enable them to pay a bill, finish a piece of work, etc.","cn":"宽限期；延缓期","g":"[uncountable]","sc":"extra time","ex":{"en":"They've given me a month's grace to get the money.","cn":"他们宽限我一个月弄到这笔钱。"}},{"en":"the love that God shows towards the human race","cn":"恩宠；恩典","g":"[uncountable]","lab":"North American English","sc":"of God","ex":{"en":"the power of divine grace","cn":"神恩的力量"}},{"en":"a short prayer that is usually said before a meal to thank God for the food","cn":"（饭前的）谢恩祈祷","g":"[uncountable, countable]","sc":"prayer","ex":{"en":"Let's say grace.","cn":"我们做饭前祷告吧。"}},{"en":"used as a title of respect when talking to or about an archbishop, a duke or a duchess","cn":"（对大主教、公爵、公爵夫人、女公爵的尊称）大人，阁下，夫人","g":"[countable]","sc":"title","ex":{"en":"Good Morning, Your Grace.","cn":"早上好，阁下。"}},{"en":"to make something more attractive; to decorate something","cn":"为…增色；为…锦上添花；装饰","ex":{"en":"The table had once graced a duke's drawing room.","cn":"这张桌子曾一度为公爵的起居室增色不少。"},"pos":"verb"},{"en":"to bring honour to somebody/something; to be kind enough to attend or take part in something","cn":"使荣耀；使生辉；承蒙光临","lab":"ironic","ex":{"en":"She is one of the finest players ever to have graced the game.","cn":"她是曾使这项运动生辉的最杰出的运动员之一。"},"pos":"verb"},{"en":"a first name for girls","cn":"格雷斯（女子名）","pos":""}]}},"graft":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"移植的皮肤（或骨骼）;移植的器官","en":"A graft is a piece of healthy skin or bone, or a healthy organ, which is attached to a damaged part of your body by a medical operation in order to replace it.","ex":{"en":"I am having a skin graft on my arm soon.","cn":"我马上就要接受手臂的皮肤移植手术。"}},{"pos":"VERB 动词","cn":"将（皮肤等）移植到","en":"If a piece of healthy skin or bone or a healthy organ is grafted onto a damaged part of your body, it is attached to that part of your body by a medical operation.","ex":{"en":"The top layer of skin has to be grafted onto the burns.","cn":"必须将表层皮肤移植到烫伤处。"}},{"pos":"VERB 动词","cn":"将…嫁接（到）","en":"If a part of one plant or tree is grafted onto another plant or tree, they are joined together so that they will become one plant or tree, often in order to produce a new variety.","ex":{"en":"Pear trees are grafted on quince rootstocks.","cn":"梨树被嫁接到榅的根茎上。"}},{"pos":"VERB 动词","cn":"将…接入（到另一思想或制度）","en":"If you graft one idea or system on to another, you try to join one to the other.","ex":{"en":"The Japanese tried to graft their own methods on to this different structure.","cn":"日本人试图将自己的方法移植到这种不同的体制中。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"劳累的工作；重活","en":"Graft means hard work.","ex":{"en":"His career has been one of hard graft.","cn":"他从事的职业劳动强度很大。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"贪污；受贿","en":"In politics, graft is used to refer to the activity of using power or authority to obtain money dishonestly.","ex":{"en":"...another politician accused of graft.","cn":"又一位被控贪污的政界人物"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"dishonest behaviour","cn":""},{"en":"when someone who works for the government, the police etc uses their power dishonestly to get money or gain an advantage","cn":""},{"en":"when someone offers money to a politician or government official in order to persuade them to do something","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"Graft can mean bribery or corruption. It's also a way of transplanting skin or bones in medicine, as in a skin graft ."}]},"collocations":{"phrases":["ADJ. bone, skin","VERB + GRAFT do Doctors are hoping to do a bone graft to repair the damaged bone.","GRAFT + VERB take If the skin graft takes, then surgeons will do another operation a few weeks later. 2 hard work","ADJ. hard Starting a new business involves a lot of hard graft.","VERB + GRAFT do Most of the graft was done for them by their assistants."]},"media":{"uk":"media/ldoce/hwd/bre/7/graft_v0205.mp3","us":"media/ldoce/hwd/ame/7/graft1.mp3"},"examples":[{"en":"Old values are being grafted onto a new social class.","cn":"旧的价值观念正植根于新的社会阶层。"},{"en":"Their success was the result of years of hard graft.","cn":"他们的成功是多年艰苦奋斗的结果。"}],"oxford":{"phon":"ɡrɑːft","pos":"noun","senses":[{"en":"a piece cut from a living plant and fixed in a cut made in another plant, so that it grows there; the process or result of doing this","cn":"接穗；嫁接","g":"[countable]","ex":{"en":"A healthy shoot should form a strong graft.","cn":"健康的嫩枝可作强壮的接穗。"}},{"en":"a piece of skin, bone, etc. removed from a living body and placed in another part of the body that has been damaged; the process or result of doing this","cn":"移植物，移植片（皮肤、骨骼等）；移植","g":"[countable]","ex":{"en":"Linda had to undergo four skin grafts.","cn":"琳达必须接受 4 次植皮手术。"}},{"en":"hard work","cn":"艰苦的工作","g":"[uncountable]","lab":"British English, informal，，","ex":{"en":"Their success was the result of years of hard graft.","cn":"他们的成功是多年艰苦奋斗的结果。"}},{"en":"the use of illegal or unfair methods, especially bribery, to gain advantage in business, politics, etc.; money obtained in this way","cn":"行贿；贿赂；受贿；赃款","g":"[uncountable]","lab":"especially North American English","ex":{"en":"He promised an end to graft and corruption in public life.","cn":"他承诺结束公共事务中的贿赂和腐败行为。"}},{"en":"to take a piece of skin, bone, etc. from a living body and attach it to a damaged part","cn":"移植（皮肤、骨骼等）","g":"[transitive]","ex":{"en":"newly grafted tissue","cn":"新移植的组织"},"pos":"verb"},{"en":"to cut a piece from a living plant and attach it to another plant","cn":"嫁接","g":"[transitive]","pos":"verb"},{"en":"to make one idea, system, etc. become part of another one","cn":"使（思想、制度等）成为（…的一部分）；植根","g":"[transitive]","ex":{"en":"Old values are being grafted onto a new social class.","cn":"旧的价值观念正植根于新的社会阶层。"},"pos":"verb"},{"en":"to work hard","cn":"卖力地工作","g":"[intransitive]","lab":"British English, informal，，","ex":{"en":"She’s been grafting all day.","cn":"她整天都在努力工作。"},"pos":"verb"}]}},"graze":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（动物）吃青草；放牛；放羊；放牧","en":"When animals graze or are grazed, they eat the grass or other plants that are growing in a particular place. You can also say that a field is grazed by animals.","ex":{"en":"Five cows graze serenely around a massive oak","cn":"5头奶牛在一棵大橡树旁悠闲自在地啃着青草。"}},{"pos":"VERB 动词","cn":"擦伤（身体部位）","en":"If you graze a part of your body, you injure your skin by scraping against something.","ex":{"en":"I had grazed my knees a little.","cn":"我的膝盖擦破了一点皮。"}},{"pos":"N-COUNT 可数名词","cn":"擦伤","en":"A graze is a small wound caused by scraping against something."},{"pos":"VERB 动词","cn":"轻擦；轻触；蹭","en":"If something grazes another thing, it touches that thing lightly as it passes by.","ex":{"en":"A bullet had grazed his arm","cn":"一颗子弹擦过他的手臂。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cut part of your body very slightly leaving a long very thin cut","cn":""},{"en":"to slightly break the surface of your skin by rubbing against something, for example when you fall on the ground","cn":""},{"en":"a large, deep cut in someone's skin","cn":""}]},"vocab":{"pos":"1 v n 2 v n","senses":[{"en":"Cows graze on grass people graze on snacks and finger-foods, like when you keep grabbing a handful of chips every time you pass by the table at a get-together."}]},"collocations":{"phrases":["ADV. peacefully, quietly Sheep were grazing peacefully in the fields.","VERB + GRAZE allow sth to, turn sth out to The cattle were turned out to graze.","PREP. on/upon lambs grazing on the rough moorland pasture 2 break the surface of your skin","ADV. badly She had grazed her elbow quite badly.","PREP. on He fell and grazed his knees on a rock"]},"media":{"uk":"media/ldoce/hwd/bre/7/graze_v0205.mp3","us":"media/ldoce/hwd/ame/4/graze1.mp3"},"examples":[{"en":"Adam walked away from the crash with just cuts and grazes.","cn":"亚当在撞车事故中平安脱险，只受了点划伤和擦伤。"},{"en":"I have this really bad habit of grazing on junk food.","cn":"我有个特别不好的习惯，就是吃垃圾食品。"}],"oxford":{"phon":"ɡreɪz","pos":"verb","senses":[{"en":"to eat grass that is growing in a field","cn":"（在草地上）吃青草","g":"[intransitive, transitive]","ex":{"en":"There were cows grazing beside the river.","cn":"有些牛在河边吃青草。"}},{"en":"to put cows, sheep, etc. in a field so that they can eat the grass there","cn":"放牧；放牛；放羊","g":"[transitive]","lab":"North American English","ex":{"en":"The land is used by local people to graze their animals.","cn":"这块地当地人用来放牧。"}},{"en":"to eat small amounts of food many times during the day, often while doing other things, instead of eating three meals","cn":"吃零食（代替正餐）","g":"[intransitive]","lab":"informal","ex":{"en":"I have this really bad habit of grazing on junk food.","cn":"我有个特别不好的习惯，就是吃垃圾食品。"}},{"en":"to break the surface of your skin by rubbing it against something rough","cn":"擦伤，擦破（皮肤）","g":"[transitive]","lab":"especially British English","ex":{"en":"I fell and grazed my knee.","cn":"我摔了一跤擦伤了膝盖。"}},{"en":"to touch something lightly while passing it","cn":"（经过时）轻擦，轻触，蹭","g":"[transitive]","ex":{"en":"The bullet grazed his cheek.","cn":"子弹从他的脸颊擦过。"}},{"en":"a small injury where the surface of the skin has been slightly broken by rubbing against something","cn":"（表皮）擦伤","ex":{"en":"Adam walked away from the crash with just cuts and grazes.","cn":"亚当在撞车事故中平安脱险，只受了点划伤和擦伤。"},"pos":"noun"}]}},"grieve":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（尤指因某人的亡故而）悲痛，悲伤，伤心","en":"If you grieve over something, especially someone's death, you feel very sad about it.","ex":{"en":"He's grieving over his dead wife and son","cn":"他因丧妻失子而悲痛不已。"}},{"pos":"VERB 动词","cn":"使难过；使悲伤","en":"If you are grieved by something, it makes you unhappy or upset.","ex":{"en":"He was deeply grieved by the sufferings of the common people","cn":"百姓的困苦使他痛心不已。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to feel extremely sad because someone that you love has died","cn":""},{"en":"to feel sadness and respect for someone who has died, and to show this by the way you behave publicly, the clothes you wear etc","cn":""},{"en":"to feel very sad because someone has died, and to show this in the way you behave","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To grieve is to feel sorrow over something, especially people who have died."}]},"collocations":{"phrases":["ADV. deeply She had grieved deeply for her father. | still","PREP. for They are still grieving for their child. | over grieving over the loss of his daughter"]},"media":{"uk":"media/ldoce/hwd/bre/f/grieve0205.mp3","us":"media/ldoce/hwd/ame/3/grieve.mp3"},"examples":[{"en":"They are still grieving for their dead child.","cn":"他们还在为死去的孩子伤心。"},{"en":"Their lack of interest grieved her.","cn":"他们不感兴趣使她很痛心。"}],"oxford":{"phon":"ɡriːv","pos":"verb","senses":[{"en":"to feel very sad, especially because somebody has died","cn":"（尤指因某人的去世而）悲伤，悲痛，伤心","g":"[intransitive, transitive]","ex":{"en":"They are still grieving for their dead child.","cn":"他们还在为死去的孩子伤心。"}},{"en":"to make you feel very sad","cn":"使悲伤；使悲痛；使伤心","g":"[transitive]","lab":"formal","ex":{"en":"It grieved him that he could do nothing to help her.","cn":"他因无法帮助她而伤心。"}}]}},"grab":{"collins":{"senses":[{"pos":"VERB 动词","cn":"抓住；攫取","en":"If you grab something, you take it or pick it up suddenly and roughly.","ex":{"en":"I managed to grab her hand","cn":"我抓到了她的手。"}},{"pos":"VERB 动词","cn":"（试图）抓住,夺取","en":"If you grab at something, you try to grab it.","ex":{"en":"He was clumsily trying to grab at Alfred's arms.","cn":"他笨手笨脚地想抓住艾尔弗雷德的手臂。"}},{"pos":"VERB 动词","cn":"引起…的注意；吸引","en":"If you grab someone who is walking past, you succeed in getting their attention.","ex":{"en":"Grab that waiter, Mary Ann.","cn":"玛丽·安，叫那位侍者过来。"}},{"pos":"VERB 动词","cn":"吸引（某人的注意）","en":"If you grab someone's attention, you do something in order to make them notice you.","ex":{"en":"I jumped on the wall to grab the attention of the crowd.","cn":"为了吸引那群人的注意，我纵身跃上墙头。"}},{"pos":"VERB 动词","cn":"（匆忙地）拿，取；抓紧（吃、睡等）","en":"If you grab something such as food, drink, or sleep, you manage to get some quickly.","ex":{"en":"Grab a beer.","cn":"拿瓶啤酒来。"}},{"pos":"VERB 动词","cn":"抓住（机会等）","en":"If you grab something such as a chance or opportunity, or grab at it, you take advantage of it eagerly.","ex":{"en":"She grabbed the chance of a job interview","cn":"她抓住了一次求职面试的机会。"}},{"pos":"N-COUNT 可数名词","cn":"攫取；争取；赚取","en":"A grab for something such as power or fame is an attempt to gain it.","ex":{"en":"...a grab for personal power.","cn":"对个人权力的巧取豪夺"}},{"pos":"See also:","cn":"","en":"to grab hold of→see: ;"},{"pos":"PHRASE 短语","cn":"供人竞购的；供争夺的","en":"If something is up for grabs, it is available to anyone who is interested.","ex":{"en":"The famous Ritz hotel is up for grabs for £100m.","cn":"著名的里兹饭店开价1亿英镑供各方竞购。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have something in your hand, hands, or arms","cn":""},{"en":"to hold something very tightly and not let it go","cn":""},{"en":"to hold something tightly, especially because you do not want to drop or lose it","cn":""}]},"collocations":{"phrases":["ADV. suddenly","VERB + GRAB try to | manage to He managed to grab a couple of hours' sleep.","PREP. at I grabbed at his arm as he ran past. | by As he walked past the boys, one of them grabbed him by the arm. | from Somebody tried to ","PHRASES grab hold of sth He grabbed hold of a handrail to save himself from falling."]},"media":{"uk":"media/ldoce/hwd/bre/1/grab_n0205.mp3","us":"media/ldoce/hwd/ame/d/grab1.mp3"},"examples":[{"en":"There are £25 000 worth of prizes up for grabs in our competition!","cn":"在我们的比赛中有价值 25 000 英镑的奖品供人争夺！"},{"en":"I'll see if I can grab the waitress and get the bill.","cn":"我要看能不能引起服务员的注意，让她拿账单来。"}],"oxford":{"phon":"ɡræb","pos":"verb","senses":[{"en":"to take or hold somebody/something with your hand suddenly or roughly","cn":"抓住；攫取","g":"[transitive, intransitive]","ex":{"en":"She grabbed his arm as he got up to leave.","cn":"他起身准备离开时，她一把抓住他的胳膊。"}},{"en":"to try to take hold of something","cn":"（试图）抓住，夺得","g":"[intransitive]","ex":{"en":"She grabbed at the branch, missed and fell.","cn":"她抓树枝，可没抓着，就跌倒了。"}},{"en":"to take advantage of an opportunity to do or have something","cn":"利用，抓住（机会）","g":"[transitive, intransitive]","ex":{"en":"This was my big chance and I grabbed it with both hands.","cn":"这是我的大好机会，我紧紧抓住。"}},{"en":"to have or take something quickly, especially because you are in a hurry","cn":"（尤指匆忙地）取，拿，吃，喝","g":"[transitive]","ex":{"en":"Let's grab a sandwich before we go.","cn":"咱们赶快吃个三明治就走吧。"}},{"en":"to take something for yourself, especially in a selfish or greedy way","cn":"（尤指自私、贪婪地）捞取，赚取，抢占","g":"[transitive]","ex":{"en":"By the time we arrived, someone had grabbed all the good seats.","cn":"我们到达时，所有的好位子都给人占了。"}},{"en":"to get somebody’s attention","cn":"引人注意；吸引","g":"[transitive]","ex":{"en":"I'll see if I can grab the waitress and get the bill.","cn":"我要看能不能引起服务员的注意，让她拿账单来。"}},{"en":"to take a picture from a television or video film, or from a computer screen, and store it as an image on a computer","cn":"抓取（或截获、采集）的图像","g":"[transitive]","ex":{"en":"You can use this keyboard shortcut to grab part of the screen.","cn":"您可以使用此键盘快捷键来抓取屏幕的一部分。"}},{"en":"a sudden attempt to take or hold somebody/something","cn":"猛然的抓取；突然的抢夺","g":"[usually singular]","ex":{"en":"He made a grab for her bag.","cn":"他突然去抢她的手提包。"},"pos":"noun"},{"en":"a picture taken from a television or video film, or from a computer screen, stored as an image on a computer","cn":"截屏；截图","lab":"computing","ex":{"en":"a frame grab from CCTV","cn":"从闭路电视抓取的一帧图像"},"pos":"noun"},{"en":"a piece of equipment that lifts and holds goods, for example the equipment that hangs from a crane","cn":"抓斗；抓具","pos":"noun"}]}},"grope":{"collins":{"senses":[{"pos":"VERB 动词","cn":"摸索；探寻","en":"If you grope for something that you cannot see, you try to find it by moving your hands around in order to feel it.","ex":{"en":"With his left hand he groped for the knob, turned it, and pulled the door open","cn":"他左手摸索着门把手，转动一下，然后推开门。"}},{"pos":"VERB 动词","cn":"摸索着走","en":"If you grope your way to a place, you move there, holding your hands in front of you and feeling the way because you cannot see anything.","ex":{"en":"I didn't turn on the light, but groped my way across the room.","cn":"我没有开灯，而是一路摸黑走过房间。"}},{"pos":"VERB 动词","cn":"探索；努力寻求","en":"If you grope for something, for example the solution to a problem, you try to think of it, when you have no real idea what it could be.","ex":{"en":"He groped for solutions to the problems facing the country","cn":"他在探求国家所面临问题的解决办法。"}},{"pos":"VERB 动词","cn":"抚摸；猥亵","en":"If one person gropes another, they touch or take hold of them in a rough, sexual way.","ex":{"en":"He would try to grope her breasts and put his hand up her skirt.","cn":"他会试图摸她的胸部，还把手从她的裙子上向上移。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put your fingers or hand onto someone or something for a very short time","cn":""},{"en":"to touch something with your fingers in order to find out about it","cn":""},{"en":"to touch something and pick it up and hold it in your hands","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you grope for something, you try to get a grip on it. If you drop your flashlight in a dark cave, you might grope around for it. Beware of snakes!"}]},"collocations":{"phrases":["ADV. blindly | vaguely | about/around/round","PREP. for She groped blindly for the door handle.","PHRASES grope your way I groped my way across the pitch-black stage."]},"media":{"uk":"media/ldoce/hwd/bre/6/grope_n0205.mp3","us":"media/ldoce/hwd/ame/e/grope1.mp3"},"examples":[{"en":"( figurative ) ‘It's so … , so … ’ I was groping for the right word to describe it. “","cn":"它是那么 … ，那么 … ”我想找一个恰当的字眼来描述它。"},{"en":"He groped around in the dark for his other sock.","cn":"他在黑暗中到处瞎摸找另一只袜子。"}],"oxford":{"phon":"ɡrəʊp","pos":"verb","senses":[{"en":"to try and find something that you cannot see, by feeling with your hands","cn":"摸索；搜索；搜寻；探寻","g":"[intransitive]","lab":"figurative","ex":{"en":"He groped around in the dark for his other sock.","cn":"他在黑暗中到处摸找另一只袜子。"}},{"en":"to try and reach a place by feeling with your hands because you cannot see clearly","cn":"（用手）摸索着往前走","g":"[transitive, intransitive]","ex":{"en":"He groped his way up the staircase in the dark.","cn":"他摸黑走上楼梯。"}},{"en":"to touch somebody sexually, especially when they do not want you to","cn":"猥亵；对（某人）毛手毛脚","g":"[transitive]","lab":"informal","ex":{"en":"She described how he had groped her whenever they were alone.","cn":"她述说了他每次和她单独相处时是怎样猥亵她的。"}},{"en":"an act of groping somebody (= touching them sexually)","cn":"猥亵；摸","pos":"noun"}]}},"groove":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"沟；槽；辙","en":"A groove is a deep line cut into a surface.","ex":{"en":"Their wheels left grooves in the ground.","cn":"他们的车轮在地面上留下了车辙印。"}},{"pos":"N-COUNT 可数名词","cn":"（流行音乐的）节奏","en":"In popular music, a groove is a rhythm.","ex":{"en":"...Latin and African grooves.","cn":"拉丁乐和非洲音乐的节奏"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long thin mark on a piece of paper, the ground, or another surface","cn":""},{"en":"a thin line that has been cut into a surface","cn":""},{"en":"a deep line in the ground which has been made by the wheels of vehicles","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A groove is an indentation or rut in something — like the grooves on an old record."}]},"collocations":{"phrases":["ADJ. deep, shallow | narrow, wide","VERB + GROOVE carve, cut, make Running water had carved a groove down the face of the wall.","PREP. ~ in a deep groove in the surface of the rock"]},"media":{"uk":"media/ldoce/hwd/bre/e/groove0205.mp3","us":"media/ldoce/hwd/ame/0/groove.mp3"},"examples":[{"en":"a jazz groove","cn":"爵士乐节奏"},{"en":"The bolt slid easily into the groove.","cn":"插销顺畅地滑入凹槽。"}],"oxford":{"phon":"ɡruːv","pos":"noun","senses":[{"en":"a long narrow cut in the surface of something hard","cn":"沟；槽；辙；纹","ex":{"en":"Cut a groove 3 cm from the top of the piece of wood.","cn":"在距离木头顶部 3 厘米处切出一个凹槽。"}},{"en":"a particular type of musical rhythm","cn":"（某种）音乐节奏（或律动）","lab":"informal","ex":{"en":"a jazz groove","cn":"爵士乐节奏"}}]}},"grandparent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（外）祖父母","en":"Your grandparents are the parents of your father or mother.","ex":{"en":"Tammy was raised by her grandparents.","cn":"塔米是爷爷奶奶抚养大的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"grandfather","cn":""},{"en":"grandmother","cn":""},{"en":"grandfather","cn":""}]},"collocations":{"phrases":["ADJ. maternal, paternal | doting a present from his doting grandparents","QUANT. set I've sent photos of the children to both sets of grandparents."]},"media":{"uk":"media/ldoce/hwd/bre/8/grandparent0205.mp3","us":"media/ldoce/hwd/ame/3/grandparent.mp3"},"examples":[{"en":"The children are staying with their grandparents.","cn":"孩子们与祖父母住在一起。"},{"en":"My grandparents live in Sussex.","cn":"我的祖父母住在萨塞克斯郡。"}],"oxford":{"phon":"ˈɡrænpeərənt","pos":"noun","senses":[{"en":"the father or mother of your father or mother","cn":"祖父；祖母；外祖父；外祖母","ex":{"en":"The children are staying with their grandparents.","cn":"孩子们与祖父母住在一起。"}}]}},"groundless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（恐惧、指控、报道等）无理由的，无根据的","en":"If you say that a fear, accusation, or story is groundless, you mean that it is not based on evidence and is unlikely to be true or valid.","ex":{"en":"Fears that the world was about to run out of fuel proved groundless","cn":"事实证明对于世界燃料即将耗尽的担忧毫无根据。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this to say that there is no reason for someone to think or behave in a particular way","cn":""},{"en":"use this to say that there is no acceptable reason for someone to think or behave in a bad or unfair way. Be no justification is more formal than be no excuse","cn":""},{"en":"groundless fears, suspicions etc that are unnecessary because there are no facts to base them on","cn":""}]},"collocations":{"phrases":["VERBS be, prove, seem","ADV. completely, entirely, quite, totally, utterly Our fears proved totally groundless. | largely"]},"media":{"uk":"media/ldoce/hwd/bre/d/groundless0205.mp3","us":"media/ldoce/hwd/ame/7/groundless.mp3"},"examples":[{"en":"Our fears proved groundless.","cn":"我们的担心证明是毫无道理的。"},{"en":"groundless allegations","cn":"毫无根据的指控"}],"oxford":{"phon":"ˈɡraʊndləs","pos":"adjective","senses":[{"en":"not based on reason or evidence","cn":"无理由的；无根据的","ex":{"en":"They denied what they called completely groundless allegations.","cn":"他们否认了他们称之为毫无根据的指控。"}}]}},"grease":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"润滑油","en":"Grease is a thick, oily substance which is put on the moving parts of cars and other machines in order to make them work smoothly.","ex":{"en":"...grease-stained hands.","cn":"沾满油渍的手"}},{"pos":"VERB 动词","cn":"给…加润滑油；为…涂（或抹）油","en":"If you grease a part of a car, machine, or device, you put grease on it in order to make it work smoothly.","ex":{"en":"I greased front and rear hubs and adjusted the brakes.","cn":"我在前后轮毂上都抹了润滑油，还调校了刹车。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（皮肤分泌的）油脂","en":"Grease is an oily substance that is produced by your skin.","ex":{"en":"His hair is thick with grease.","cn":"他的头发油乎乎的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"动物油脂","en":"Grease is animal fat that is produced by cooking meat. You can use grease for cooking.","ex":{"en":"He could smell the bacon grease.","cn":"他闻到一股腌肉的油脂味儿。"}},{"pos":"VERB 动词","cn":"给…涂上油（以防粘锅）","en":"If you grease a dish, you put a small amount of fat or oil around the inside of it in order to prevent food sticking to it during cooking.","ex":{"en":"Grease two sturdy baking sheets and heat the oven to 400 degrees","cn":"在两块结实的烤板上抹些油，把烤炉加热到400度。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a fatty or oily substance that comes off meat when it is cooked, or off food made using butter or oil 〔","cn":"肉或食物中的〕油脂"},{"en":"a thick oily substance that is put on the moving parts of a car, machine etc to make it run or move smoothly","cn":"润滑油"},{"en":"an oily substance that is produced by your skin 〔","cn":"皮肤上的〕油脂"}]},"collocations":{"phrases":["ADV. well | lightly Place the cakes on a lightly greased baking tray."]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdegrease.mp3","us":"media/ldoce/hwd/ame/1/grease1.mp3"},"examples":[{"en":"Grease marks can be removed with liquid detergent.","cn":"用洗涤液可除去油渍。"},{"en":"Her hands were covered with oil and grease.","cn":"她满手油垢。"}],"oxford":{"phon":"ɡriːs","pos":"noun","senses":[{"en":"any thick oily substance, especially one that is used to make machines run smoothly","cn":"油脂；润滑脂","ex":{"en":"Grease marks can be removed with liquid detergent.","cn":"用洗涤液可除去油渍。"}},{"en":"animal fat that has been made softer by cooking or heating","cn":"（炼过的）动物油脂","ex":{"en":"He collected the plates, which were covered with grease.","cn":"他收走那些油腻的盘子。"}},{"en":"to rub grease or fat on something","cn":"给…加润滑油；在…上涂油（或抹油、擦油）","ex":{"en":"to grease a cake tin/pan","cn":"在蛋糕烤盘上抹油"},"pos":"verb"},{"en":"a US musical play about the love affairs of young people, especially Danny and Sandy, in a high school in the early days of rock and roll. The title refers to the hair oil used by the boys. In the successful film version (1978) John Travolta and Olivia Newton-John played the main parts. Grease 2 (1982) with different actors was less successful.","cn":"油脂：这是一部关于音乐的音乐剧，讲述了摇滚乐时代初期年轻人在高中时的爱情，尤其是丹尼和桑迪。标题是指男孩使用的发油。在成功的电影版本（1978年）中，约翰·特拉沃尔塔和奥利维亚·牛顿·约翰扮演了主要角色。油脂2（1982）由不同的演员完成，效果不佳。","pos":""}]}},"groomed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"打扮得（干净利落或邋遢）的","en":"You use groomed in expressions such as well groomed and badly groomed to say how neat, clean, and smart a person is.","ex":{"en":"...a very well groomed man","cn":"衣着整洁得体的男子"}}]},"collocations":{"phrases":["VERBS be, look She is always perfectly groomed.","ADV. well | immaculately, impeccably, meticulously, perfectly | beautifully | sleekly, smoothly"]},"examples":[{"en":"She is always perfectly groomed.","cn":"她总是打扮得干净利落。"}],"oxford":{"phon":"ɡruːmd","pos":"adjective","senses":[{"en":"used to describe the way in which a person cares for their clothes and hair","cn":"（描述穿着打扮情况）","ex":{"en":"She is always perfectly groomed.","cn":"她总是打扮得干净利落。"}}]}},"grounding":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"基础训练；基础知识；基础","en":"If you have a grounding in a subject, you know the basic facts or principles of that subject, especially as a result of a particular course of training or instruction.","ex":{"en":"The degree provides a thorough grounding in both mathematics and statistics.","cn":"该学位课程将为数学和统计学打下扎实的基础。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a training in the basic parts of a subject or skill","cn":"基础训练"},{"en":"a punishment for a child’s bad behaviour in which they are not allowed to go out with their friends for a period of time","cn":"禁足〔罚小孩一段时间内不准与朋友出门〕"},{"en":"the process of officially stopping an aircraft from flying, especially because it is not safe to fly","cn":"飞机停飞"}]},"collocations":{"phrases":["ADJ. good, solid, thorough | basic","VERB + GROUNDING have All applicants for the job should have a basic grounding in computer skills. | get | give (sb), provide (sb with) The ","PREP. ~ in to get a good grounding in science"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdegrounding.mp3","us":"media/ldoce/hwd/ame/8/grounding.mp3"},"examples":[{"en":"a good grounding in grammar","cn":"扎实的语法基本功训练"},{"en":"A basic grounding in math is essential for the economics course.","cn":"对经济学这门课程来说﹐基本的数学功底是必不可少的。"}],"oxford":{"phon":"ˈɡraʊndɪŋ","pos":"noun","senses":[{"en":"the teaching of the basic parts of a subject","cn":"基础训练；基础教学","g":"[singular]","ex":{"en":"He has a good grounding in grammar.","cn":"他有良好的语法基础。"}},{"en":"the act of keeping a plane on the ground or a ship in a port, especially because it is not in a good enough condition to travel","cn":"（尤指因机件故障等）（飞机的）留地停飞，（船的）留港停航","g":"[uncountable, countable]"}]}},"graffiti":{"collins":{"senses":[{"pos":"N-UNCOUNT-COLL 不可数集合名词","cn":"（在公共场所的）涂画，涂鸦","en":"Graffiti is words or pictures that are written or drawn in public places, for example on walls or posters.","ex":{"en":"Buildings old and new are thickly covered with graffiti","cn":"新老建筑上都有密密麻麻的涂鸦。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a picture drawn with a pencil, pen, crayon etc","cn":""},{"en":"a drawing that is done quickly and has few details","cn":""},{"en":"a shape or pattern that you draw when you are bored or thinking about other things","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Graffiti is a word, phrase, or image painted or drawn somewhere in public, like on the side of a building or on the walls in a restroom."}]},"collocations":{"phrases":["ADJ. political, racist","QUANT. piece","VERB + GRAFFITI daub, draw, scrawl, scribble, spray, write Graffiti was scribbled all over the walls. | be covered with, be daubed with, be ","GRAFFITI + NOUN artist a fashionable graffiti artist"]},"media":{"uk":"media/ldoce/hwd/bre/6/graffiti0205.mp3","us":"media/ldoce/hwd/ame/b/graffiti.mp3"},"examples":[{"en":"The subway was covered in graffiti.","cn":"过街地道里涂满了乱七八糟的图画和文字。"},{"en":"The walls are daubed with graffiti.","cn":"墙上满是乱七八糟的涂鸦。"}],"oxford":{"phon":"ɡrəˈfiːti","pos":"noun","senses":[{"en":"drawings or writing on a wall, etc. in a public place","cn":"（公共场所墙上等处的）涂鸦，胡写乱画","ex":{"en":"The subway was covered in graffiti.","cn":"地下通道里到处是涂鸦。"}}]}},"greed":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"贪婪；贪心；贪欲","en":"Greed is the desire to have more of something, such as food or money, than is necessary or fair.","ex":{"en":"...an insatiable greed for personal power","cn":"对个人权力的贪得无厌"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is greedy wants more money, possessions, power etc than they need, or wants more than their share","cn":""},{"en":"very greedy so that you are not at all generous and treat other people very badly","cn":""},{"en":"believing that having a lot of money and possessions is the most important thing in life","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Greed is an overwhelming urge to have more of something, usually more than you really need. Watching kids at a birthday party furiously grabbing for candy from a piñata, you might find yourself surprised at their greed ."}]},"collocations":{"phrases":["ADJ. pure, sheer, simple | human, personal","VERB + GREED satisfy She killed him to satisfy her greed. | be consumed by, be driven by","PREP. ~ for He was driven by greed for money and power."]},"media":{"uk":"media/ldoce/hwd/bre/d/greed0205.mp3","us":"media/ldoce/hwd/ame/8/greed.mp3"},"examples":[{"en":"I had another helping of ice cream out of pure greed.","cn":"我纯粹是因为嘴馋贪吃，又吃了一份冰淇淋。"},{"en":"His actions were motivated by greed.","cn":"他的作为是贪婪之心所驱使的。"}],"oxford":{"phon":"ɡriːd","pos":"noun","senses":[{"en":"a strong desire for more wealth, possessions, power, etc. than a person needs","cn":"贪婪；贪心；贪欲","ex":{"en":"His actions were motivated by greed.","cn":"他的所作所为是受贪婪之心所驱使。"}},{"en":"a strong desire for more food or drink when you are no longer hungry or thirsty","cn":"贪食；贪吃","ex":{"en":"I had another helping of ice cream out of pure greed.","cn":"我纯粹是因为嘴馋贪吃，又吃了一份冰激凌。"}}]}},"grenade":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手榴弹；榴弹","en":"A grenade or a hand grenade is a small bomb that can be thrown by hand.","ex":{"en":"A hand grenade was thrown at an army patrol.","cn":"一枚手榴弹掷向了陆军巡逻队。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a weapon that explodes","cn":""},{"en":"bombs or substances that can cause explosions","cn":""},{"en":"a bomb – used especially in news reports","cn":""}]},"collocations":{"phrases":["ADJ. hand, smoke, stun | rocket-propelled | live","VERB + GRENADE be armed with, carry, have The hijackers were armed with hand grenades. | hold She was holding the grenade above her head, re","GRENADE + VERB fall, land | explode, go off","GRENADE + NOUN attack | launcher"]},"media":{"uk":"media/ldoce/hwd/bre/2/grenade0205.mp3","us":"media/ldoce/hwd/ame/9/grenade.mp3"},"examples":[{"en":"a hand grenade","cn":"手榴弹"}],"oxford":{"phon":"ɡrəˈneɪd","pos":"noun","senses":[{"en":"a small bomb that can be thrown by hand or fired from a gun","cn":"榴弹；手榴弹；枪榴弹","ex":{"en":"His vehicle was damaged by a rocket-propelled grenade.","cn":"他的车毁于火箭榴弹。"}}]}},"grit":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"沙粒；沙砾","en":"Grit is very small pieces of stone. It is often put on roads in winter to make them less slippery.","ex":{"en":"He felt tiny bits of grit and sand peppering his knees.","cn":"他感到细小的沙砾不断打在膝盖上。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"勇气；坚毅；果敢","en":"If someone has grit, they have the determination and courage to continue doing something even though it is very difficult.","ex":{"en":"You've got to admire her grit.","cn":"你不得不佩服她的勇气。"}},{"pos":"N-PLURAL 复数名词","cn":"粗玉米粉，玉米渣（美国南部常食用）","en":"Grits are coarsely ground grains of corn which are cooked and eaten for breakfast or as part of a meal in the southern United States."},{"pos":"VERB 动词","cn":"（通常指因愤怒而）咬紧牙关，咬牙切齿","en":"If you grit your teeth, you press your upper and lower teeth tightly together, usually because you are angry about something.","ex":{"en":"Gritting my teeth, I did my best to stifle one or two remarks","cn":"我咬紧牙关，硬是吞回了几句话。"}},{"pos":"PHRASE 短语","cn":"下定决心；鼓起勇气","en":"If you grit your teeth, you make up your mind to carry on even if the situation is very difficult.","ex":{"en":"There is going to be hardship, but we have to grit our teeth and get on with it.","cn":"未来会很艰难，但是我们必须咬牙坚持下去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"very small pieces of stone or sand","cn":"沙砾﹔沙粒"},{"en":"determination and courage","cn":"坚毅﹐勇气"},{"en":"a type of grain that is roughly crushed and cooked, and often eaten for breakfast","cn":"粗磨的谷物〔常于早餐食用〕"}]},"vocab":{"pos":"1 n v 2 v n","senses":[{"en":"Grit is a coarse, gravelly dust. If you don't rinse dried beans before you cook them, you may end up crunching grit between your teeth."}]},"collocations":{"phrases":["QUANT. bit, piece A bit of grit had got into my eye. 2 courage/determination","ADJ. sheer, true","VERB + GRIT have Don't give in yet. You have more grit than that. | display, show The team showed their true grit and played a magnificent g"]},"media":{"uk":"media/ldoce/hwd/bre/f/grit_v0205.mp3","us":"media/ldoce/hwd/ame/9/grit1.mp3"},"examples":[{"en":"It started to rain harder, but we gritted our teeth and carried on.","cn":"雨开始大起来，可我们鼓起勇气继续下去。"},{"en":"They were spreading grit and salt on the icy roads.","cn":"他们在结冰的路上撒沙子和盐。"}],"oxford":{"phon":"ɡrɪt","pos":"noun","senses":[{"en":"very small pieces of stone or sand","cn":"沙粒；沙砾；细沙","ex":{"en":"I had a piece of grit in my eye.","cn":"我眼睛里进了一粒沙子。"}},{"en":"the courage and strength of mind that makes it possible for somebody to continue doing something difficult or unpleasant","cn":"勇气；毅力","ex":{"en":"It takes sheer grit to stand up to a bully like that.","cn":"挺身而出对抗那样一个恃强凌弱者需要极大的勇气。"}},{"en":"to spread grit, salt or sand on a road that is covered with ice","cn":"（在结冰的路上）撒沙砾，撒盐，撒沙子","pos":"verb"}]}},"groan":{"collins":{"senses":[{"pos":"VERB 动词","cn":"呻吟；叹息","en":"If you groan, you make a long, low sound because you are in pain, or because you are upset or unhappy about something.","ex":{"en":"Slowly, he opened his eyes. As he did so, he began to groan with pain","cn":"他慢慢地睁开眼睛，并发出痛苦的呻吟。"}},{"pos":"VERB 动词","cn":"不高兴地低声说；咕哝","en":"If you groan something, you say it in a low, unhappy voice.","ex":{"en":"'My leg — I think it's broken,' Eric groaned.","cn":"“我的腿——我想是断了，”埃里克咕哝着说。"}},{"pos":"VERB 动词","cn":"抱怨；发牢骚","en":"If you groan about something, you complain about it.","ex":{"en":"His parents were beginning to groan about the price of college tuition.","cn":"他的父母开始抱怨大学的学费太贵。"}},{"pos":"VERB 动词","cn":"（树木等）发出嘎吱声","en":"If wood or something made of wood groans, it makes a loud sound when it moves.","ex":{"en":"The timbers groan and creak and the floorboards shift.","cn":"这些木头在吱吱嘎嘎作响，木地板有些摇晃。"}},{"pos":"VERB 动词","cn":"堆满，摆满，装满（食物）","en":"If you say that something such as a table groans under the weight of food, you are emphasizing that there is a lot of food on it.","ex":{"en":"The bar counter groans under the weight of huge plates of the freshest fish.","cn":"吧台上摆满了大碟大碟非常新鲜的鱼。"}},{"pos":"VERB 动词","cn":"受…重压；受…折磨；不堪重负","en":"If you say that someone or something is groaning under the weight of something, you think there is too much of that thing.","ex":{"en":"Consumers were groaning under the weight of high interest rates","cn":"高利率令消费者不堪重负。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a long deep sound because you are in pain, upset, or disappointed, or because something is very enjoyable 〔","cn":"因疼痛﹑心烦或失望而〕呻吟﹔〔因快乐而〕哼哼"},{"en":"to complain about something","cn":"抱怨﹐发牢骚"},{"en":"to make a low deep sound","cn":"发出低沉的声音"}]},"vocab":{"pos":"n v","senses":[{"en":"A groan is a sound of pain or disapproval that doesn't consist of words, usually heard after homework is assigned or bad jokes are told."}]},"collocations":{"phrases":["ADJ. loud He let out a loud groan of frustration. | little, small | deep, low | harsh, hoarse | muffled","VERB + GROAN give, let out, utter | stifle, suppress | hear","PREP. with a ~ He stood up slowly with a groan of pain. | ~ of • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/b/groan_v0205.mp3","us":"media/ldoce/hwd/ame/b/groan1.mp3"},"examples":[{"en":"We all groaned at his terrible jokes.","cn":"他讲的笑话很糟糕，我们都发出不满的抱怨声。"},{"en":"The house was filled with the cello's dismal squeaks and groans.","cn":"房子里回荡着大提琴低沉而凄厉的声音。"}],"oxford":{"phon":"ɡrəʊn","pos":"verb","senses":[{"en":"to make a long deep sound because you are annoyed, upset or in pain, or with pleasure","cn":"呻吟；叹息；哼哼","g":"[intransitive, transitive]","ex":{"en":"He lay on the floor groaning.","cn":"他躺在地板上呻吟。"}},{"en":"to complain about something, especially in an annoying way","cn":"抱怨；发牢骚","g":"[intransitive, transitive]","ex":{"en":"They were all moaning and groaning about the amount of work they had.","cn":"他们都对工作量太大怨声载道。"}},{"en":"to make a sound like a person groaning","cn":"发出似呻吟的声音","g":"[intransitive]","ex":{"en":"The trees creaked and groaned in the wind.","cn":"树在风中嘎吱作响。"}},{"en":"a long deep sound made when somebody/something groans","cn":"呻吟声；叹息声；哼哼声；嘎吱声","ex":{"en":"She let out a groan of dismay.","cn":"她发出沮丧的叹息声。"},"pos":"noun"},{"en":"a complaint","cn":"怨言；牢骚","ex":{"en":"I don't have time to listen to your moans and groans.","cn":"我没时间听你唧唧歪歪发牢骚。"},"pos":"noun"}]}},"grudge":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"不满；积怨；怨恨","en":"If you have or bear a grudge against someone, you have unfriendly feelings towards them because of something they did in the past.","ex":{"en":"He appears to have a grudge against certain players","cn":"他看来对某些选手怀恨在心。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to refuse to forgive someone, because they have done something very bad","cn":""},{"en":"to continue to feel angry with someone for a long time because they treated you badly in the past","cn":""},{"en":"to dislike someone because of something they did in the past, even though it is no longer important","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you tend to hold a grudge , you don't let it go when you feel someone's insulted or wronged you. I hope you won't hold a grudge against me for bringing it up."}]},"collocations":{"phrases":["ADJ. long-standing, old It's time to forget old grudges. | personal","VERB + GRUDGE bear, harbour, have, hold, nurse I don't hold grudges for very long.","PREP. ~ against Do you know anyone who might harbour a grudge against you?"]},"media":{"uk":"media/ldoce/hwd/bre/7/grudge_n0205.mp3","us":"media/ldoce/hwd/ame/c/grudge1.mp3"},"examples":[{"en":"England beat New Zealand in a grudge match (= a match where there is strong dislike between the teams).","cn":"英格兰队在一场势不两立的比赛中打败了新西兰队。"},{"en":"He grudges the time he spends travelling to work.","cn":"他不情愿上班花这么多时间在路上。"}],"oxford":{"phon":"ɡrʌdʒ","pos":"noun","senses":[{"en":"a feeling of anger or dislike towards somebody because of something bad they have done to you in the past","cn":"积怨；怨恨；嫌隙","ex":{"en":"I bear him no grudge.","cn":"我对他不怀任何积怨。"}},{"en":"to do or give something unwillingly","cn":"勉强做；不情愿地给；吝惜","ex":{"en":"I grudge having to pay so much tax.","cn":"得付这么多的税，我很不情愿。"},"pos":"verb"},{"en":"to think that somebody does not deserve to have something","cn":"认为…不应得到","ex":{"en":"You surely don't grudge her her success?","cn":"她获得成功，你没有不以为然吧？"},"pos":"verb"}]}},"gruesome":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人厌恶的；恐怖的；令人震惊的","en":"Something that is gruesome is extremely unpleasant and shocking.","ex":{"en":"There has been a series of gruesome murders in the capital.","cn":"在首都发生了一连串让人毛骨悚然的谋杀案。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very unpleasant or shocking, and involving someone being killed or badly injured","cn":"令人毛骨悚然的﹐可怕的〔涉及有人被杀或受重伤〕"}]},"vocab":{"pos":"adj","senses":[{"en":"Gothic novels, horror movies, and crime dramas don't shy away from showing gruesome scenes of death, pictures that inspire fright and repulsion. Synonyms include \"ghastly,\" \"grisly,\" \"loathsome,\" and \"macabre.\""}]},"collocations":{"phrases":["VERBS be","ADV. horribly, particularly, truly | pretty, rather a rather gruesome sight"]},"media":{"uk":"media/ldoce/hwd/bre/b/gruesome0205.mp3","us":"media/ldoce/hwd/ame/a/gruesome.mp3"},"examples":[{"en":"( humorous ) We spent a week in a gruesome apartment in Miami.","cn":"我们在迈阿密一套糟糕透顶的公寓里住了一星期。"},{"en":"We spent a week in a gruesome apartment in Miami.","cn":""}],"oxford":{"phon":"ˈɡruːsəm","pos":"adjective","senses":[{"en":"very unpleasant and filling you with horror, usually because it is connected with death or injury","cn":"令人厌恶的；恐怖的；可怕的","lab":"humorous","ex":{"en":"a gruesome murder","cn":"骇人听闻的谋杀案"}}]}},"grill":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（烤炉内的）烤架","en":"A grill is a part of a stove which produces strong heat to cook food that has been placed underneath it.","ex":{"en":"Place the omelette under a gentle grill until the top is set.","cn":"将煎蛋饼放在烤架下用文火烘烤，直到表面凝固。"}},{"pos":"N-COUNT 可数名词","cn":"（置于火上的）烤架","en":"A grill is a flat frame of metal bars on which food can be cooked over a fire."},{"pos":"V-ERG 及物/不及物动词","cn":"烧烤；烤炙","en":"When you grill food, or when it grills, you cook it using very strong heat directly above or below it.","ex":{"en":"Grill the meat for 20 minutes each side","cn":"将肉的每一面各烤20分钟。"}},{"pos":"VERB 动词","cn":"追问；盘问；审问","en":"If you grill someone about something, you ask them a lot of questions for a long period of time.","ex":{"en":"Grill your travel agent about the facilities for families with children","cn":"请仔细询问旅行代办人会为带孩子的家庭提供何种设施。"}},{"pos":"N-COUNT 可数名词","cn":"烤肉餐馆；烤肉店","en":"A grill is a restaurant that serves grilled food."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cook things such as bread or cakes in an oven","cn":""},{"en":"to cook meat or vegetables in an oven","cn":""},{"en":"to cook food in hot oil","cn":""}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"Not all grilling involves fire and delicious food. Sometimes, to grill means to ask a person really intense questions, like when you suspect them of doing something wrong and you want to make them confess the truth."}]},"collocations":{"phrases":["ADJ. hot Cook under a hot grill for 7 minutes. | eye-level | electric, gas","VERB + GRILL preheat Preheat the grill to medium.","GRILL + NOUN pan","PREP. under a/the ~ Place the chops in the grill pan, and put it under the grill. 2 framework of metal bars that you cook food on","ADJ. charcoal","PREP. on a/the ~ Once the charcoal is glowing, place the food on the grill, turning it regularly."]},"media":{"uk":"media/ldoce/hwd/bre/2/grill_v0205.mp3","us":"media/ldoce/hwd/ame/c/grill1.mp3"},"examples":[{"en":"They grilled her about where she had been all night.","cn":"他们盘问她整个夜晚待在什么地方。"},{"en":"Grill the sausages for ten minutes.","cn":"把香肠烤十分钟。"}],"oxford":{"phon":"ɡrɪl","pos":"noun","senses":[{"en":"the part of a cooker that directs heat downwards to cook food that is placed under it","cn":"（炊具、烤炉内的）烘烤器","lab":"British English","ex":{"en":"Put it under a hot grill to brown for two minutes.","cn":"将其放在热烤架下烤两分钟至棕色。"}},{"en":"a flat metal frame that you put food on to cook over a fire","cn":"（置于火上的）烤架","ex":{"en":"Once the charcoal is glowing, place the food on the grill, turning it regularly.","cn":"木炭发红后，将食物放到烧烤架上，并不时翻转。"}},{"en":"a dish of grilled food, especially meat","cn":"一盘烧烤食物（尤指烤肉）"},{"en":"a restaurant serving grilled food","cn":"烤肉餐馆；烧烤店","ex":{"en":"Harry’s Bar and Grill","cn":"哈里烤肉酒吧"}},{"en":"a screen made of metal bars or wire that is placed in front of a window, door or machine in order to protect it","cn":"（置于窗、门、机器前面的）铁栅栏，金属网罩"},{"en":"to cook food under a very strong heat","cn":"（在高温下方）烧烤，炙烤","lab":"British English","ex":{"en":"Grill the sausages for ten minutes.","cn":"把香肠烤十分钟。"},"pos":"verb"},{"en":"to cook food over a fire, especially outdoors","cn":"（在火上，尤指户外）烧，烤，焙","ex":{"en":"grilled meat and shrimp","cn":"烤肉和烤虾"},"pos":"verb"},{"en":"to ask somebody a lot of questions about their ideas, actions, etc., often in an unpleasant way","cn":"盘问；追问；审问；责问","ex":{"en":"They grilled her about where she had been all night.","cn":"他们盘问她整个晚上去哪里了。"},"pos":"verb"}]}},"grandson":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（外）孙子;（外）孙女","en":"Someone's grandson is the son of their son or daughter.","ex":{"en":"My grandson's birthday was on Tuesday.","cn":"星期二是我孙子的生日。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the son of your son or daughter","cn":"孙子﹔外孙"}]},"media":{"uk":"media/ldoce/hwd/bre/9/grandson0205.mp3","us":"media/ldoce/hwd/ame/6/grandson.mp3"},"oxford":{"phon":"ˈɡrænsʌn","pos":"noun","senses":[{"en":"a son of your son or daughter","cn":"孙子；外孙"}]}}});
